-- #####################################################################################################
-- ### PART 1 of 9 — reassign keeps the old tutor's link when they still teach the student
-- ### source branch: claude/b4-fix   file: db/migration_reassign_link.sql   undo: db/migration_reassign_link_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- B4-FIX — reassign + "also make them the assigned tutor": keep the old tutor's link when they still teach the student elsewhere
-- undo: migration_reassign_link_down.sql        Run AFTER migration_staff_reassign.sql. Run on DEV first. Safe to run twice. Reads/changes no row by itself.
-- =====================================================================================================
-- BEFORE: ticking "Also make them <student>'s assigned tutor" always ended the OLD tutor's link, even when that tutor still taught the student in
-- another weekly slot or has other upcoming lessons with them. NOW: the link is ended only when the old tutor teaches the student nowhere else
-- (no other active weekly slot, no other upcoming non-cancelled lesson that is not from the slot being moved). The result and the audit entry carry
-- 'links_kept' (how many old links were kept). Everything else in the function is unchanged.

create or replace function public.staff_reassign_lesson(p_lesson uuid, p_new_tutor uuid, p_mode text, p_reason text default null,
                                                        p_update_links boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare l lessons; cl lessons; today date; md text := lower(trim(coalesce(p_mode, ''))); why text := nullif(trim(coalesce(p_reason, '')), '');
        nt memberships; cfg jsonb; allowed boolean; ids uuid[]; locked text; orig uuid; new_cf uuid; old_tutor uuid;
        sid uuid; ended int := 0; added int := 0; kept int := 0; still boolean; moved_slots uuid[]; n_ended int; before_j jsonb := '[]'::jsonb; link_ids uuid[];
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into l from lessons where id = p_lesson;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := staff_slots_gate(l.org_id, true);                                            -- NOT_FOUND for strangers, NOT_ALLOWED without manage_timetable

  if md not in ('reassign', 'cover') then raise exception 'BAD_MODE: choose cover or reassign' using errcode = 'P0001'; end if;
  if p_new_tutor is null then raise exception 'PICK_TUTOR: choose who will teach this lesson' using errcode = 'P0001'; end if;
  if why is not null and length(why) > 500 then raise exception 'TOO_LONG: keep the reason under 500 characters' using errcode = 'P0001'; end if;
  if coalesce(p_update_links, false) and md = 'cover' then
    raise exception 'LINK_NOT_FOR_COVER: a cover is one lesson only, so it never changes who a student is assigned to' using errcode = 'P0001'; end if;

  select * into nt from memberships m where m.id = p_new_tutor and m.org_id = l.org_id and m.role in ('tutor', 'staff', 'owner') and m.status = 'active';
  if not found then raise exception 'NOT_AVAILABLE: that person can''t be given lessons at this centre (they must be an active member here)' using errcode = 'P0001'; end if;
  if l.taught_by is not distinct from p_new_tutor then
    raise exception 'NO_CHANGE: that tutor already teaches this lesson' using errcode = 'P0001'; end if;

  if l.taught_by is null then
    if md = 'cover' then raise exception 'NO_TUTOR_TO_COVER: this lesson has no tutor yet, so there is nobody to cover for. Use Assign instead' using errcode = 'P0001'; end if;
  else
    -- a lesson that already has a tutor changing hands is a replacement: the centre's own rule decides (read as of today)
    cfg := org_settings_on(l.org_id, today) #> '{lessons,replacement_tutors}';
    allowed := case when jsonb_typeof(cfg) = 'boolean' then (cfg #>> '{}')::boolean else true end;      -- missing = on (the default)
    if not allowed then
      raise exception 'REPLACEMENT_OFF: this centre doesn''t allow replacement tutors. An owner can switch this on in the centre settings' using errcode = 'P0001'; end if;
    if why is null then raise exception 'REASON_REQUIRED: say why this lesson is changing tutor. It is kept on record' using errcode = 'P0001'; end if;
  end if;

  -- the lesson, or the whole class of that day (lessons sharing a session_id): all or nothing
  select coalesce(array_agg(x.id order by x.id), array[l.id]) into ids from lessons x
   where x.org_id = l.org_id and (x.id = l.id or (l.session_id is not null and x.session_id = l.session_id));
  perform 1 from lessons x where x.id = any(ids) order by x.id for update;
  foreach sid in array ids loop
    locked := lesson_locked_reason(sid);
    if locked is not null then
      raise exception '%', case locked
        when 'MARKED'    then 'ALREADY_MARKED: this lesson is already marked, so it stays with the tutor who taught it'
        when 'CANCELLED' then 'CANCELLED: this lesson was cancelled'
        when 'PAID'      then 'PAID: this lesson is already paid, so it can''t change hands'
        else                  'INVOICED: this lesson is on an invoice, so it can''t change hands' end
        || case when array_length(ids, 1) > 1 then ' (it is part of a class that moves together)' else '' end using errcode = 'P0001';
    end if;
  end loop;

  -- move them
  for cl in select * from lessons x where x.id = any(ids) order by x.id loop
    before_j := before_j || jsonb_build_object('lesson_id', cl.id, 'taught_by', cl.taught_by, 'covered_for', cl.covered_for);
    if md = 'cover' then
      orig := coalesce(cl.covered_for, cl.taught_by);                                    -- who it was meant for stays the same however often it is covered
      new_cf := case when orig is distinct from p_new_tutor then orig end;              -- handed back to the original tutor = nobody is covering
    else new_cf := null; end if;
    update lessons set taught_by = p_new_tutor, covered_for = new_cf where id = cl.id;
  end loop;

  -- reassign only, and only when asked: the student's assigned-tutor link follows (the old tutor's ends, the new tutor's starts)
  if coalesce(p_update_links, false) then
    for sid in select distinct x.student_id from lessons x where x.id = any(ids) loop
      old_tutor := (select (e ->> 'taught_by')::uuid from jsonb_array_elements(before_j) e
                     join lessons y on y.id = (e ->> 'lesson_id')::uuid where y.student_id = sid limit 1);
      if old_tutor is not null then
        -- the old tutor stays this student's assigned tutor when they still teach the student somewhere else: another weekly slot, or another
        -- upcoming lesson that does not come from the slot of the lesson(s) being moved (a reassign leaves those weekly slots alone)
        select coalesce(array_agg(distinct x.slot_id) filter (where x.slot_id is not null), '{}') into moved_slots from lessons x where x.id = any(ids) and x.student_id = sid;
        still := exists (select 1 from recurring_slots rs where rs.org_id = l.org_id and rs.student_id = sid and rs.taught_by = old_tutor and rs.active
                           and not (rs.id = any(moved_slots)))
              or exists (select 1 from lessons y where y.org_id = l.org_id and y.student_id = sid and y.taught_by = old_tutor and y.lesson_date >= today
                           and y.status is distinct from 'cancelled' and not (y.id = any(ids)) and (y.slot_id is null or not (y.slot_id = any(moved_slots))));
        if still then kept := kept + 1;
        else
          update student_tutors set active = false, until = today where org_id = l.org_id and student_id = sid and membership_id = old_tutor and active;
          get diagnostics n_ended = row_count; ended := ended + n_ended;
        end if;
      end if;
      if not exists (select 1 from student_tutors x where x.org_id = l.org_id and x.student_id = sid and x.membership_id = p_new_tutor and x.active) then
        insert into student_tutors(org_id, student_id, membership_id, since, created_by) values (l.org_id, sid, p_new_tutor, today, auth.uid());
        added := added + 1;
      end if;
    end loop;
  end if;

  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (l.org_id, auth.uid(), 'staff_reassign_lesson', 'lessons', l.id::text,
          jsonb_build_object('lessons', before_j),
          jsonb_build_object('mode', md, 'new_tutor', p_new_tutor, 'new_tutor_name', nt.display_name, 'lessons', to_jsonb(ids), 'reason', why,
                             'covered_for', (select covered_for from lessons where id = l.id),
                             'links_updated', coalesce(p_update_links, false), 'links_ended', ended, 'links_added', added, 'links_kept', kept));
  return jsonb_build_object('lesson_id', l.id, 'lessons', array_length(ids, 1), 'mode', md, 'tutor_id', p_new_tutor,
                            'tutor_name', coalesce(nt.display_name, 'Tutor'), 'covered_for', (select covered_for from lessons where id = l.id),
                            'links_ended', ended, 'links_added', added, 'links_kept', kept);
end $$;

revoke all on function public.staff_reassign_lesson(uuid, uuid, text, text, boolean) from public, anon;
grant execute on function public.staff_reassign_lesson(uuid, uuid, text, text, boolean) to authenticated;

-- #####################################################################################################
-- ### PART 2 of 9 — Record payment fix (DELETE without WHERE refused by Supabase)
-- ### source branch: claude/b4-fix   file: db/migration_payment_fix.sql   undo: db/migration_payment_fix_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- B4-FIX — "Record payment" failed with "Something went wrong" (PostgREST error 21000)   undo: migration_payment_fix_down.sql
-- =====================================================================================================
-- Run order: AFTER migration_centre_payments.sql (any time after; it only replaces one function). Run on the DEV project first. Safe to run twice.
-- Needs no data change and reads/changes no row.
--
-- CAUSE: centre_record_payment cleared its scratch table with `delete from _td_pay_open;` (no WHERE). Supabase's API layer runs the pg-safeupdate
-- extension, which refuses any DELETE or UPDATE without a WHERE clause with SQLSTATE 21000 ("DELETE requires a WHERE clause"). The throwaway test
-- Postgres has no such extension, so the SQL tests passed. Only this one statement was affected (every other DELETE / UPDATE in the migrations has a WHERE).
-- FIX: the same function with `delete from _td_pay_open where true;` (the scratch table is per-transaction, so it is empty on a first call anyway).
-- Behaviour is otherwise identical; grants are kept by CREATE OR REPLACE and restated below.
-- =====================================================================================================

create or replace function public.centre_record_payment(p_org uuid, p_household uuid, p_method text, p_amount_cents bigint, p_received_on date,
  p_reference text default null, p_invoice_ids uuid[] default null, p_payer_name text default null, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_money_gate(p_org, 'record_payments'); s jsonb; partial boolean; mode text; modes jsonb;
  hh uuid := p_household; pid uuid := gen_random_uuid(); ref text := nullif(trim(coalesce(p_reference, '')), ''); payer text := nullif(trim(coalesce(p_payer_name, '')), '');
  note text := nullif(trim(coalesce(p_note, '')), ''); explicit boolean := coalesce(cardinality(p_invoice_ids), 0) > 0; r record; bad record;
  remaining bigint; take bigint; allocated jsonb := '[]'::jsonb; n_alloc int := 0; excess bigint := 0; hh_i uuid; ids uuid[]; open_n int;
begin
  if p_method is null or p_method not in ('manual_paynow', 'bank', 'cash', 'cheque', 'other') then
    raise exception 'BAD_VALUE: choose how it was paid (PayNow, bank transfer, cash, cheque or other)' using errcode = 'P0001'; end if;
  if p_amount_cents is null or p_amount_cents <= 0 then raise exception 'BAD_VALUE: the amount must be more than S$0.00' using errcode = 'P0001'; end if;
  if p_amount_cents > 100000000 then raise exception 'BAD_VALUE: that amount is too large to be right (over S$1,000,000)' using errcode = 'P0001'; end if;
  if p_received_on is null then raise exception 'BAD_VALUE: say the date it was received' using errcode = 'P0001'; end if;
  if p_received_on > today then raise exception 'BAD_VALUE: the date received can''t be in the future' using errcode = 'P0001'; end if;
  if p_received_on < today - 1825 then raise exception 'BAD_VALUE: the date received is too far back (over 5 years)' using errcode = 'P0001'; end if;
  if length(coalesce(ref, '')) > 120 or length(coalesce(payer, '')) > 120 or length(coalesce(note, '')) > 300 then
    raise exception 'TOO_LONG: keep the reference and name under 120 characters and the note under 300' using errcode = 'P0001'; end if;
  s := org_settings_on(p_org, today);
  if s is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  partial := coalesce((s#>>'{payments,partial_payments}')::boolean, true);
  mode := centre_overpay_mode(s);
  modes := coalesce(s#>'{payments,modes}', '[]'::jsonb);
  if p_method = 'manual_paynow' and not (modes ? 'manual_paynow') then
    raise exception 'NOT_ALLOWED: manual PayNow isn''t switched on in this centre''s payment settings (cash, bank transfer and cheque still can be recorded)' using errcode = '42501'; end if;

  -- which household? (from the chosen invoices when it isn't given)
  if explicit then
    select array(select distinct x from unnest(p_invoice_ids) x) into ids;
    for r in select i.id, i.status, i.kind, i.number_text, centre_invoice_household(i.id) as hid from centre_invoices i where i.org_id = p_org and i.id = any(ids) loop
      if r.status <> 'issued' or r.kind = 'credit_note' then raise exception 'NOT_ALLOWED: % can''t be paid (only an issued invoice can)', coalesce(r.number_text, 'that document') using errcode = '42501'; end if;
      if hh is null then hh := r.hid; end if;
      if r.hid is distinct from hh then raise exception 'NOT_ALLOWED: those invoices belong to different families; record one payment per family' using errcode = '42501'; end if;
    end loop;
    if (select count(*) from centre_invoices where org_id = p_org and id = any(ids)) <> cardinality(ids) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  end if;
  if hh is null then raise exception 'BAD_VALUE: choose which family paid' using errcode = 'P0001'; end if;
  if not exists (select 1 from households h where h.id = hh and h.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(hh::text, 4));      -- two people recording for the same family: one waits

  -- the invoices this payment may cover, in the order money is applied: oldest issued first (issue date, then number)
  create temp table if not exists _td_pay_open(invoice_id uuid, number_text text, total_cents bigint, balance_cents bigint, ord int) on commit drop;
  delete from _td_pay_open where true;                                 -- Supabase refuses a DELETE with no WHERE (pg-safeupdate, SQLSTATE 21000)
  insert into _td_pay_open
    select i.id, i.number_text, i.total_cents, b.balance_cents, (row_number() over (order by i.issue_date, i.number_seq))::int
      from centre_invoices i, lateral centre_balance_rows(p_org, array[i.id]) b
     where i.org_id = p_org and i.status = 'issued' and i.kind <> 'credit_note'
       and (case when explicit then i.id = any(ids)
                 else (i.household_id = hh or (i.household_id is null and i.student_id in (select s2.id from students s2 where s2.household_id = hh and s2.org_id = p_org))) end);
  if explicit then
    select * into bad from _td_pay_open where balance_cents = 0 limit 1;
    if bad.invoice_id is not null then raise exception 'NOT_ALLOWED: % is already paid in full', bad.number_text using errcode = '42501'; end if;
  end if;
  select count(*) into open_n from _td_pay_open where balance_cents > 0;

  -- partial payments switched off: the money must cover whole invoices (the first one it can't finish is named)
  if not partial and open_n > 0 then
    remaining := p_amount_cents;
    for r in select * from _td_pay_open where balance_cents > 0 order by ord loop
      if remaining < r.balance_cents then
        raise exception 'PART_NOT_ALLOWED: this centre doesn''t accept part payments, so a payment has to cover whole invoices. % still owes %.', r.number_text, centre_fmt_money(r.balance_cents) using errcode = '42501';
      end if;
      remaining := remaining - r.balance_cents;
    end loop;
  end if;

  insert into centre_payments(id, org_id, kind, household_id, method, amount_cents, received_on, reference, payer_name, note)
  values (pid, p_org, 'payment', hh, p_method, p_amount_cents, p_received_on, ref, payer, note);
  remaining := p_amount_cents;
  for r in select * from _td_pay_open where balance_cents > 0 order by ord loop
    exit when remaining <= 0;
    take := least(remaining, r.balance_cents);
    insert into centre_payment_allocations(org_id, payment_id, invoice_id, cents) values (p_org, pid, r.invoice_id, take);
    remaining := remaining - take; n_alloc := n_alloc + 1;
    allocated := allocated || jsonb_build_object('invoice_id', r.invoice_id, 'number', r.number_text, 'cents', take, 'balance_after_cents', r.balance_cents - take);
  end loop;
  excess := remaining;
  if excess > 0 then
    insert into centre_family_credit(org_id, household_id, kind, handling, cents, payment_id, reason)
    values (p_org, hh, 'overpayment', mode, excess, pid, case when open_n = 0 then 'Paid in advance: nothing was owed' else 'More than the open invoices came to' end);
  end if;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'centre_payment_record', 'centre_payments', pid::text, null,
          jsonb_build_object('method', p_method, 'amount_cents', p_amount_cents, 'received_on', p_received_on, 'invoices_covered', n_alloc, 'excess_cents', excess, 'excess_handling', case when excess > 0 then mode end));
  return jsonb_build_object('payment_id', pid, 'household_id', hh, 'amount_cents', p_amount_cents, 'allocated', allocated, 'excess_cents', excess,
                            'excess_handling', case when excess > 0 then mode end, 'credit_balance_cents', centre_credit_balance(p_org, hh));
end $$;

revoke all on function public.centre_record_payment(uuid, uuid, text, bigint, date, text, uuid[], text, text) from public, anon;
grant execute on function public.centre_record_payment(uuid, uuid, text, bigint, date, text, uuid[], text, text) to authenticated, service_role;

-- #####################################################################################################
-- ### PART 3 of 9 — refundable deposits: ledger, deposit invoice, waive, opening balance
-- ### source branch: claude/t4-s4-deposits   file: db/migration_centre_deposits.sql   undo: db/migration_centre_deposits_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T4 step S4 — centre deposits: refundable deposit ledger, deposit invoice with the first run, "Deposits held"   undo: migration_centre_deposits_down.sql
-- =====================================================================================================
-- Run order everywhere: org_foundation → billing → attendance → tutor_access → org_delete → function_lockdown → org_separation →
--   staff_home → staff_students → staff_attendance → staff_charges → staff_trials → staff_timetable → money_settings →
--   centre_money → centre_invoice_run → centre_payments → centre_deposits.
-- Needs migration_money_settings.sql (S0: the deposit options), migration_centre_money.sql (S1), migration_centre_invoice_run.sql (S2) and
-- migration_centre_payments.sql (S3: payments, credit notes). Run on the DEV project first. LIVE only when the owner says ship: this migration
-- reads no existing row and changes none (two new tables, two nullable columns, new functions; it REPLACES five S1/S2 functions with versions that
-- also know about deposits, and widens two checks on centre_invoices). Safe to run twice.
--
-- WHAT A DEPOSIT IS HERE (owner-approved T4 decisions, 2026-11-26)
--   A refundable deposit is a LIABILITY: money the centre holds for a family. It lives in its own ledger, is NEVER revenue, carries NO GST when
--   received (a `taxable` flag on every deposit row lets an accountant's answer change the default without a schema change: the setting
--   billing.deposit.taxable, read when the deposit is raised and then frozen on the row), and never appears in a revenue figure
--   (centre_revenue_totals below leaves deposit invoices and the cash that paid them out and reports them separately).
--
-- WHAT THIS ADDS
--   centre_deposits          one row per student: the REQUIRED amount, frozen the first time it is computed (mode, percent used, first month's fee,
--                            taxable flag). Never recomputed when fees change. Only its invoice link may move (a discarded draft is re-raised).
--   centre_deposit_ledger    APPEND-ONLY cents per student: received · reversal · waived · adjusted · applied · forfeited · refunded · transferred_out ·
--                            transferred_in · opening_balance. Held = every row except `waived` (a waiver reduces what is asked, it is not cash).
--                            Never below zero. Refund / release / forfeit / transfer / adjustment are S5; the kinds exist so S5 needs no rewrite.
--   invoice kind 'deposit'   a separate document called "Refundable deposit", raised WITH the student's first invoice run, sharing the one gap-free
--                            counter; a draft until approved (or issued straight away when the centre doesn't review). Paid like any invoice through
--                            S3 payments: the allocation writes the ledger row (trigger below), so there is no second way to "receive" a deposit.
--   invoice kind 'opening'   (T33 plan, decision 3) an old invoice carried over from the centre's previous books. It KEEPS ITS OLD NUMBER
--                            (centre_invoices.imported_number), does NOT use the counter, and is issued, immutable and payable like any other.
--   students.start_date      nullable: the day lessons started (T33 import). Recorded only: it doesn't decide anything about deposits.
--
-- THE RULES
--   mode none                  nothing is raised.
--   mode fixed                 the centre's fixed amount (billing.one_off_fees.deposit_cents) for each student with a non-trial lesson in a ready invoice.
--   mode percent_first_month   percent_bp of THAT student's first month: their non-trial lessons in this run, before sibling discount, fees and GST.
--   FIRST RUN ONLY             a student gets a deposit once: when they have no deposit row yet, no lesson on any earlier invoice of the centre, and
--                              their household's invoice is READY (not held back). A second run adds nothing. A discarded deposit DRAFT is raised
--                              again with the same frozen amount. Trial students (no non-trial lesson) get none. A deposit never gets a late fee.
--   billing.deposit.due        only with_first_invoice is built; before_first_lesson is `soon`: the preview says so and no deposit is raised.
--   billing.deposit.waived_by  owner / issue_invoices / nobody, read as of today. Waiving needs a reason. A draft deposit invoice is discarded; an
--                              issued one is credited for what is still unpaid (a credit note, the S3 way); a fully paid deposit can't be waived.
--   opening balance            OWNER ONLY, one per student, for deposits collected before TutorDeck (no invoice, no number used, no revenue).
--
-- WHO MAY CALL: reading the ledger and "Deposits held": an owner or staff with record_payments OR view_revenue. Opening balance: owner. Waiving: as
--   the waived_by setting says. Everyone else (tutors, parents, switched-off staff, solo owners, strangers, anonymous) gets NOT_FOUND. The two new
--   tables have a read policy by the same rule and NO write policy: browsers never write a deposit.
-- AUDIT: both tables use the S1 audit trigger (free text replaced by "[redacted]"); each function adds a summary row with amounts and counts only.
-- =====================================================================================================

-- ---------------------------------------------------------------------------------------------------
-- 1. small additions to existing tables
-- ---------------------------------------------------------------------------------------------------
alter table public.students add column if not exists start_date date;
alter table public.centre_invoices add column if not exists imported_number text;

do $$
declare c record;
begin
  -- the allowed kinds gain 'opening'
  for c in select conname from pg_constraint where conrelid = 'public.centre_invoices'::regclass and contype = 'c'
            and pg_get_constraintdef(oid) like '%''lesson''%' and pg_get_constraintdef(oid) like '%''credit_note''%' and pg_get_constraintdef(oid) like '%''late_fee''%'
            and pg_get_constraintdef(oid) not like '%opening%' loop
    execute format('alter table public.centre_invoices drop constraint %I', c.conname);
  end loop;
  if not exists (select 1 from pg_constraint where conname = 'centre_invoices_kind_ck') then
    alter table public.centre_invoices add constraint centre_invoices_kind_ck check (kind in ('lesson', 'deposit', 'late_fee', 'credit_note', 'opening'));
  end if;
  -- "issued ⇔ numbered": an opening invoice keeps its old number as text and has no counter number
  for c in select conname from pg_constraint where conrelid = 'public.centre_invoices'::regclass and contype = 'c'
            and pg_get_constraintdef(oid) like '%number_seq IS NOT NULL) AND (number_text IS NOT NULL)%' loop
    execute format('alter table public.centre_invoices drop constraint %I', c.conname);
  end loop;
  if not exists (select 1 from pg_constraint where conname = 'centre_invoices_number_ck') then
    alter table public.centre_invoices add constraint centre_invoices_number_ck check (
      ((status = 'issued') = (number_text is not null)) and ((status = 'issued' and kind <> 'opening') = (number_seq is not null)));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'centre_invoices_imported_ck') then
    alter table public.centre_invoices add constraint centre_invoices_imported_ck check ((kind = 'opening') = (imported_number is not null));
  end if;
end $$;
create unique index if not exists centre_invoices_opening_number on public.centre_invoices(org_id, lower(imported_number)) where kind = 'opening' and status <> 'void';
-- one live deposit invoice per student (a discarded draft is void and doesn't count)
create unique index if not exists centre_invoices_one_deposit on public.centre_invoices(org_id, student_id) where kind = 'deposit' and status <> 'void';

-- ---------------------------------------------------------------------------------------------------
-- 2. the tables
-- ---------------------------------------------------------------------------------------------------
create table if not exists public.centre_deposits (
  id                uuid primary key default gen_random_uuid(),
  org_id            uuid not null references public.organisations(id) on delete cascade,
  student_id        uuid not null,
  household_id      uuid,                                   -- the family at the time (a snapshot; the student may move later)
  source            text not null check (source in ('invoice_run', 'opening_balance')),
  mode              text not null check (mode in ('fixed', 'percent_first_month', 'opening')),
  percent_bp        int  check (percent_bp between 1 and 10000),
  first_month_cents bigint check (first_month_cents >= 0),  -- the first month's fee the percent was applied to (frozen with the deposit)
  required_cents    bigint not null check (required_cents > 0),
  taxable           boolean not null default false,          -- frozen from billing.deposit.taxable when raised; see the header
  period_start      date,                                    -- the invoice-run month it was raised in
  invoice_id        uuid,                                    -- the deposit invoice (null for an opening balance)
  created_by        uuid default auth.uid(),
  created_at        timestamptz not null default now(),
  unique (id, org_id),
  unique (org_id, student_id),
  foreign key (student_id, org_id)   references public.students(id, org_id),
  foreign key (household_id, org_id) references public.households(id, org_id),
  foreign key (invoice_id, org_id)   references public.centre_invoices(id, org_id),
  check ((source = 'invoice_run') = (mode in ('fixed', 'percent_first_month'))),
  check ((mode = 'percent_first_month') = (percent_bp is not null and first_month_cents is not null)),
  check ((source = 'opening_balance') = (invoice_id is null))
);
create index if not exists centre_deposits_invoice on public.centre_deposits(invoice_id) where invoice_id is not null;

create table if not exists public.centre_deposit_ledger (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references public.organisations(id) on delete cascade,
  student_id    uuid not null,
  deposit_id    uuid not null,
  kind          text not null check (kind in ('received', 'reversal', 'waived', 'adjusted', 'applied', 'forfeited', 'refunded', 'transferred_out', 'transferred_in', 'opening_balance')),
  cents         bigint not null check (cents <> 0),
  taxable       boolean not null default false,             -- copied from the deposit row, so the accountant can total the taxable part
  invoice_id    uuid,
  payment_id    uuid,
  allocation_id uuid unique,                                 -- one ledger row per payment allocation (a payment can't be counted twice)
  entry_date    date not null default current_date,
  reason        text,                                        -- free text; redacted in the audit copy
  created_by    uuid default auth.uid(),
  created_at    timestamptz not null default now(),
  unique (id, org_id),
  foreign key (student_id, org_id) references public.students(id, org_id),
  foreign key (deposit_id, org_id) references public.centre_deposits(id, org_id),
  foreign key (invoice_id, org_id) references public.centre_invoices(id, org_id),
  foreign key (payment_id, org_id) references public.centre_payments(id, org_id),
  foreign key (allocation_id)      references public.centre_payment_allocations(id),
  check (case kind when 'received' then cents > 0 when 'opening_balance' then cents > 0 when 'transferred_in' then cents > 0 when 'waived' then cents > 0
                   when 'reversal' then cents < 0 when 'applied' then cents < 0 when 'forfeited' then cents < 0 when 'refunded' then cents < 0
                   when 'transferred_out' then cents < 0 else true end),
  check (kind not in ('waived', 'adjusted') or length(trim(coalesce(reason, ''))) > 0)
);
create index if not exists centre_deposit_ledger_student on public.centre_deposit_ledger(org_id, student_id, entry_date);
create index if not exists centre_deposit_ledger_invoice on public.centre_deposit_ledger(invoice_id) where invoice_id is not null;

-- ---------------------------------------------------------------------------------------------------
-- 3. guards (same shape as S1: centres only, append-only, the exception for deleting a whole organisation)
-- ---------------------------------------------------------------------------------------------------
-- the deposit row is frozen: only its invoice link may move, and only from "none or discarded" to a new draft deposit invoice of the same student
create or replace function public.centre_deposit_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare cur record; nw record;
begin
  if tg_op = 'DELETE' then
    if centre_money_deleting(old.org_id) then return old; end if;
    raise exception 'A deposit record can''t be deleted (it is a money record)' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    if new.source = 'invoice_run' then
      select * into nw from centre_invoices where id = new.invoice_id and org_id = new.org_id;
      if nw.id is null or nw.kind <> 'deposit' or nw.student_id is distinct from new.student_id then
        raise exception 'A deposit needs its own deposit invoice for the same student' using errcode = '42501'; end if;
    end if;
    return new;
  end if;
  -- UPDATE: nothing but the invoice link
  if (to_jsonb(new) - 'invoice_id') <> (to_jsonb(old) - 'invoice_id') then
    raise exception 'A deposit''s amount and terms are frozen (record an adjustment instead)' using errcode = '42501'; end if;
  if new.invoice_id is distinct from old.invoice_id then
    if old.source <> 'invoice_run' then raise exception 'This deposit has no invoice' using errcode = '42501'; end if;
    if old.invoice_id is not null then
      select * into cur from centre_invoices where id = old.invoice_id and org_id = old.org_id;
      if cur.status <> 'void' then raise exception 'This deposit already has a live invoice' using errcode = '42501'; end if;
    end if;
    select * into nw from centre_invoices where id = new.invoice_id and org_id = new.org_id;
    if nw.id is null or nw.kind <> 'deposit' or nw.status <> 'draft' or nw.student_id is distinct from new.student_id then
      raise exception 'The new invoice must be a draft deposit invoice for the same student' using errcode = '42501'; end if;
  end if;
  return new;
end $$;

-- the ledger is append-only, and what is held for a student never goes below zero (you can't hand back what you don't hold)
create or replace function public.centre_deposit_ledger_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare bal bigint; d record;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if tg_op = 'DELETE' and centre_money_deleting(old.org_id) then return old; end if;
    raise exception 'The deposit ledger is append-only (a correction is a new row)' using errcode = '42501';
  end if;
  select * into d from centre_deposits where id = new.deposit_id and org_id = new.org_id;
  if d.id is null or d.student_id <> new.student_id then raise exception 'That ledger row doesn''t match its deposit' using errcode = '42501'; end if;
  if new.kind <> 'waived' then
    perform pg_advisory_xact_lock(hashtextextended(new.student_id::text, 6));
    select coalesce(sum(cents), 0) + new.cents into bal from centre_deposit_ledger where org_id = new.org_id and student_id = new.student_id and kind <> 'waived';
    if bal < 0 then
      raise exception 'DEPOSIT_SHORT: that would take the deposit held below zero (% cents held)', bal - new.cents using errcode = '23514'; end if;
  end if;
  return new;
end $$;

-- a payment allocated to a deposit invoice is how a deposit is received (and a reversed payment un-receives it): one row per allocation
create or replace function public.centre_deposit_alloc_hook() returns trigger
language plpgsql security definer set search_path = public as $$
declare d record; pdate date;
begin
  select * into d from centre_deposits where invoice_id = new.invoice_id and org_id = new.org_id;
  if d.id is null then return null; end if;
  select received_on into pdate from centre_payments where id = new.payment_id and org_id = new.org_id;
  insert into centre_deposit_ledger(org_id, student_id, deposit_id, kind, cents, taxable, invoice_id, payment_id, allocation_id, entry_date)
  values (new.org_id, d.student_id, d.id, case when new.cents > 0 then 'received' else 'reversal' end, new.cents, d.taxable, new.invoice_id, new.payment_id, new.id, pdate);
  return null;
end $$;

do $$
declare t text;
begin
  foreach t in array array['centre_deposits', 'centre_deposit_ledger'] loop
    execute format('drop trigger if exists centre_money_org_guard on public.%I', t);
    execute format('create trigger centre_money_org_guard before insert on public.%I for each row execute function public.centre_money_org_guard()', t);
    execute format('drop trigger if exists audit_row on public.%I', t);
    execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function public.centre_money_audit()', t);
  end loop;
end $$;
drop trigger if exists centre_deposit_guard on public.centre_deposits;
create trigger centre_deposit_guard before insert or update or delete on public.centre_deposits for each row execute function public.centre_deposit_guard();
drop trigger if exists centre_deposit_ledger_guard on public.centre_deposit_ledger;
create trigger centre_deposit_ledger_guard before insert or update or delete on public.centre_deposit_ledger for each row execute function public.centre_deposit_ledger_guard();
drop trigger if exists centre_deposit_alloc_hook on public.centre_payment_allocations;
create trigger centre_deposit_alloc_hook after insert on public.centre_payment_allocations for each row execute function public.centre_deposit_alloc_hook();

-- access: read by permission, written by nobody from a browser
alter table public.centre_deposits enable row level security;
alter table public.centre_deposit_ledger enable row level security;
drop policy if exists money_read on public.centre_deposits;
create policy money_read on public.centre_deposits for select using ((org_can(org_id, 'record_payments') or org_can(org_id, 'view_revenue')) and not org_is_solo(org_id));
drop policy if exists money_read on public.centre_deposit_ledger;
create policy money_read on public.centre_deposit_ledger for select using ((org_can(org_id, 'record_payments') or org_can(org_id, 'view_revenue')) and not org_is_solo(org_id));
revoke all on public.centre_deposits, public.centre_deposit_ledger from anon, authenticated;
grant select on public.centre_deposits, public.centre_deposit_ledger to authenticated;

-- ---------------------------------------------------------------------------------------------------
-- 4. the invoice guard, now also issuing an OPENING invoice under its old number (copy of the S1 function with one branch added)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_invoice_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare s jsonb; prefix text; sub bigint; nlines int; t record; credited bigint; inv record; day date;
begin
  if tg_op = 'DELETE' then
    if old.status = 'draft' or centre_money_deleting(old.org_id) then return old; end if;
    raise exception 'An issued or voided document can''t be deleted (issue a credit note instead)' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'draft' or new.number_seq is not null or new.number_text is not null then
      raise exception 'A new document starts as a draft with no number' using errcode = '42501';
    end if;
    return new;
  end if;
  -- UPDATE
  if old.status <> 'draft' then
    raise exception 'An % document can''t be changed (issue a credit note instead)', old.status using errcode = '42501';
  end if;
  if new.org_id <> old.org_id or new.kind <> old.kind then raise exception 'A document''s organisation and kind can''t change'; end if;
  if new.status = 'draft' then
    if new.number_seq is not null or new.number_text is not null then raise exception 'A draft has no number; it is given one when issued' using errcode = '42501'; end if;
    return new;
  end if;
  if new.status = 'void' then
    new.voided_at := coalesce(new.voided_at, now());
    if new.number_seq is not null or new.number_text is not null then raise exception 'A voided draft has no number' using errcode = '42501'; end if;
    return new;
  end if;
  -- issuing: validate, take the number, freeze
  select coalesce(sum(line_cents), 0), count(*) into sub, nlines from centre_invoice_lines where invoice_id = new.id;
  if nlines = 0 then raise exception 'A document needs at least one line before it is issued' using errcode = '42501'; end if;
  select * into t from centre_gst_totals(sub, new.gst_rate_bp, new.gst_inclusive, new.gst_registered);
  if t.net_cents <> new.net_cents or t.gst_cents <> new.gst_cents or t.total_cents <> new.total_cents then
    raise exception 'The totals don''t match the lines (expected net %, GST %, total %)', t.net_cents, t.gst_cents, t.total_cents using errcode = '42501';
  end if;
  if new.total_cents < 0 then raise exception 'A document''s total can''t be negative' using errcode = '42501'; end if;
  if new.kind = 'credit_note' then
    select * into inv from centre_invoices where id = new.credits_invoice_id and org_id = new.org_id;
    if inv.id is null or inv.status <> 'issued' or inv.kind = 'credit_note' then
      raise exception 'A credit note must credit an issued invoice' using errcode = '42501';
    end if;
    if new.reason is null or length(trim(new.reason)) = 0 then raise exception 'A credit note needs a reason' using errcode = '42501'; end if;
    perform pg_advisory_xact_lock(hashtextextended(inv.id::text, 0));
    select coalesce(sum(total_cents), 0) into credited from centre_invoices
     where credits_invoice_id = inv.id and status = 'issued' and id <> new.id;
    if credited + new.total_cents > inv.total_cents then
      raise exception 'Credit notes can''t add up to more than the invoice (invoice %, already credited %, this one %)', inv.total_cents, credited, new.total_cents using errcode = '42501';
    end if;
    if inv.household_id is distinct from new.household_id or inv.student_id is distinct from new.student_id then
      raise exception 'A credit note must be for the same household and student as its invoice' using errcode = '42501';
    end if;
  end if;
  day := coalesce(new.issue_date, (now() at time zone coalesce((select timezone from organisations where id = new.org_id), 'Asia/Singapore'))::date);
  s := org_settings_on(new.org_id, day);
  prefix := coalesce(nullif(trim(s#>>'{profile,invoice_prefix}'), ''), 'INV');
  if new.kind = 'opening' then
    -- an OPENING invoice keeps the number it already had in the centre's old books: it never touches the counter (T33 import)
    new.imported_number := nullif(trim(coalesce(new.imported_number, '')), '');
    if new.imported_number is null then raise exception 'An opening invoice needs the number it already has' using errcode = '42501'; end if;
    if exists (select 1 from centre_invoices x where x.org_id = new.org_id and x.id <> new.id and x.status = 'issued' and lower(x.number_text) = lower(new.imported_number)) then
      raise exception 'Another document already has the number %', new.imported_number using errcode = '23505';
    end if;
    new.number_seq := null;
    new.number_text := new.imported_number;
  else
    new.number_seq := centre_next_number(new.org_id, case when new.kind = 'credit_note' then 'credit_note' else 'invoice' end);   -- (generated columns are not filled yet in a BEFORE trigger)
    new.number_text := case when new.kind = 'credit_note' then 'CN-' else '' end || prefix || '-' || new.number_seq;
  end if;
  new.issue_date := day;
  new.issued_at := now();
  new.issued_by := coalesce(auth.uid(), new.created_by);
  return new;
end $$;


-- ---------------------------------------------------------------------------------------------------
-- 5. deposit helpers (internal)
-- ---------------------------------------------------------------------------------------------------
-- who and when: 'view' = owner or staff with record_payments / view_revenue;  'record' = record_payments;  'owner' = the centre owner.
-- Returns the centre's own "today". Everyone who isn't owner/staff of THIS centre (tutor, parent, solo, stranger, anonymous) gets NOT_FOUND.
create or replace function public.centre_deposit_gate(p_org uuid, p_perm text) returns date
language plpgsql stable security definer set search_path = public as $$
declare tz text; ok boolean;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select o.timezone into tz from organisations o where o.id = p_org and o.kind = 'centre';
  if tz is null or not exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active' and m.role in ('owner', 'staff')) then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  ok := case p_perm when 'member' then true when 'view' then org_can(p_org, 'record_payments') or org_can(p_org, 'view_revenue')
                    when 'owner' then org_can(p_org, 'owner')
                    else org_can(p_org, 'record_payments') end;
  if not ok then
    raise exception 'NOT_ALLOWED: your account can''t % at this centre', case p_perm when 'owner' then 'do that (only the centre owner can)' when 'view' then 'see deposits' else 'record deposits' end using errcode = '42501';
  end if;
  return (now() at time zone tz)::date;
end $$;

-- plain words when the centre's deposit option can't be acted on yet (null = nothing to say)
create or replace function public.centre_deposit_note(p_settings jsonb) returns text
language sql immutable set search_path = public as $$
  select case
    when coalesce(p_settings#>>'{billing,deposit,mode}', 'none') = 'none' then null
    when coalesce(p_settings#>>'{billing,deposit,due}', 'with_first_invoice') <> 'with_first_invoice'
      then 'Deposits invoiced before the first lesson are coming soon. No deposit is raised until the setting says “together with the first lesson invoice”.'
    when p_settings#>>'{billing,deposit,mode}' = 'fixed' and coalesce((p_settings#>>'{billing,one_off_fees,deposit_cents}')::bigint, 0) <= 0
      then 'The deposit is a fixed amount of S$0.00, so none is raised.'
    else null end
$$;

-- the deposits this run would raise (reads the run's temporary tables: call centre_invoice_run_prepare first).
-- NEW  = a student with no deposit row, no lesson on an earlier invoice, and a non-trial lesson in a READY invoice → mode applied to their first month.
-- REUSE = a student whose deposit invoice was discarded as a draft → the SAME frozen amount again.
create or replace function public.centre_deposit_run_candidates(p_org uuid, p_ms date, p_today date)
returns table(d_student_id uuid, d_student_name text, d_household_id uuid, d_unit_key text, d_deposit_id uuid, d_mode text, d_percent_bp int,
              d_first_month_cents bigint, d_amount_cents bigint, d_taxable boolean, d_frozen boolean)
language plpgsql security definer set search_path = public, pg_temp as $$
declare s jsonb := coalesce(org_settings_on(p_org, p_ms), org_settings_on(p_org, p_today)); me date := (p_ms + interval '1 month - 1 day')::date;
  v_mode text; v_due text; v_bp int; v_fix bigint; v_tax boolean;
begin
  if s is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  v_mode := coalesce(s#>>'{billing,deposit,mode}', 'none');
  v_due  := coalesce(s#>>'{billing,deposit,due}', 'with_first_invoice');
  v_bp   := coalesce((s#>>'{billing,deposit,percent_bp}')::int, 0);
  v_fix  := coalesce((s#>>'{billing,one_off_fees,deposit_cents}')::bigint, 0);
  v_tax  := coalesce((s#>>'{billing,deposit,taxable}')::boolean, false);
  return query
  with fm as (                                       -- each student's non-trial lesson fee in an invoice that is READY (before discounts, fees and GST)
    select r.unit_key as ukey, r.student_id as sid, max(r.student_name) as sname, sum(r.qty * r.unit_cents)::bigint as cents
      from _td_run r
      join _td_units u on u.unit_key = r.unit_key and u.status = 'ready'
      join lessons l on l.id = r.lesson_id and l.org_id = p_org
     where r.state = 'line' and r.line_kind = 'lesson' and not coalesce(l.trial, false)
     group by r.unit_key, r.student_id
  )
  select st.id, st.name, st.household_id, fm.ukey, null::uuid,
         case v_mode when 'fixed' then 'fixed' else 'percent_first_month' end,
         case when v_mode = 'percent_first_month' then v_bp end,
         fm.cents,
         case v_mode when 'fixed' then v_fix when 'percent_first_month' then centre_div_round(fm.cents * v_bp, 10000) else 0 end,
         v_tax, false
    from fm join students st on st.id = fm.sid and st.org_id = p_org
   where v_mode in ('fixed', 'percent_first_month') and v_due = 'with_first_invoice'
     and not exists (select 1 from centre_deposits d where d.org_id = p_org and d.student_id = st.id)
     and not exists (select 1 from centre_invoice_lines cl join centre_invoices ci on ci.id = cl.invoice_id and ci.org_id = cl.org_id
                      where cl.org_id = p_org and cl.student_id = st.id and ci.kind in ('lesson', 'opening') and ci.status <> 'void' and ci.period_start <= p_ms)
     and case v_mode when 'fixed' then v_fix when 'percent_first_month' then centre_div_round(fm.cents * v_bp, 10000) else 0 end > 0
  union all
  select st.id, st.name, st.household_id, fm.ukey, d.id, d.mode, d.percent_bp, d.first_month_cents, d.required_cents, d.taxable, true
    from fm join students st on st.id = fm.sid and st.org_id = p_org
    join centre_deposits d on d.org_id = p_org and d.student_id = st.id and d.source = 'invoice_run'
   where d.invoice_id is null or exists (select 1 from centre_invoices i where i.id = d.invoice_id and i.org_id = p_org and i.status = 'void');
end $$;

-- makes ONE deposit draft (internal): the "Refundable deposit" invoice and, for a new deposit, its frozen row. GST only when the deposit is taxable.
create or replace function public.centre_deposit_make_invoice(p_org uuid, p_student uuid, p_deposit uuid, p_amount bigint, p_taxable boolean, p_mode text,
  p_bp int, p_first bigint, p_ms date, p_me date, p_today date) returns uuid
language plpgsql security definer set search_path = public as $$
declare st students; pr jsonb := org_settings_on(p_org, p_today); reg boolean; rate int; inc boolean; g record; inv uuid := gen_random_uuid(); dep uuid := p_deposit;
begin
  select * into st from students where id = p_student and org_id = p_org;
  reg  := coalesce(p_taxable, false) and coalesce((pr#>>'{profile,gst_registered}')::boolean, false);
  rate := case when reg then coalesce((pr#>>'{profile,gst_rate_bp}')::int, 0) else 0 end;
  inc  := reg and coalesce((pr#>>'{profile,gst_inclusive}')::boolean, false);
  select * into g from centre_gst_totals(p_amount, rate, inc, reg);
  insert into centre_invoices(id, org_id, kind, household_id, student_id, period_start, period_end, gst_registered, gst_rate_bp, gst_inclusive, net_cents, gst_cents, total_cents)
  values (inv, p_org, 'deposit', st.household_id, p_student, p_ms, p_me, reg, rate, inc, g.net_cents, g.gst_cents, g.total_cents);
  insert into centre_invoice_lines(org_id, invoice_id, position, student_id, description, qty, unit_cents)
  values (p_org, inv, 1, p_student, 'Refundable deposit', 1, p_amount);
  if dep is null then
    insert into centre_deposits(org_id, student_id, household_id, source, mode, percent_bp, first_month_cents, required_cents, taxable, period_start, invoice_id)
    values (p_org, p_student, st.household_id, 'invoice_run', p_mode, p_bp, p_first, p_amount, coalesce(p_taxable, false), p_ms, inv);
  else
    update centre_deposits set invoice_id = inv where id = dep and org_id = p_org;
  end if;
  return inv;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 6. the invoice run learns about deposits (copies of the S2 functions, each with a small addition; undo restores the originals)
-- ---------------------------------------------------------------------------------------------------
-- preview: adds `deposits` (who would get one, how much, the first month it came from), `deposit_note`, and two totals
create or replace function public.centre_invoice_run_preview(p_org uuid, p_period date) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_invoicing_gate(p_org); ms date := centre_invoice_month(p_period, today); me date := (ms + interval '1 month - 1 day')::date;
  s jsonb := coalesce(org_settings_on(p_org, ms), org_settings_on(p_org, today)); note text; res jsonb; deps jsonb; dcents bigint; dnote text;
begin
  if s is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  note := centre_invoice_model_note(s);
  res := jsonb_build_object('today', today, 'period_start', ms, 'period_end', me, 'model', coalesce(s#>>'{billing,model}', 'postpaid_lessons'),
           'fixed_period', coalesce(s#>>'{billing,fixed_period}', 'month'), 'grouping', coalesce(s#>>'{invoicing,grouping}', 'family'),
           'review_before_sending', coalesce((s#>>'{invoicing,review_before_sending}')::boolean, true),
           'due_days', coalesce((s#>>'{invoicing,due_days}')::int, 7),
           'built', note is null, 'message', note);
  if note is not null then
    return res || jsonb_build_object('ready', '[]'::jsonb, 'held_back', '[]'::jsonb, 'drafts', '[]'::jsonb,
                                     'totals', jsonb_build_object('ready', 0, 'held_back', 0, 'drafts', 0, 'lessons', 0, 'subtotal_cents', 0, 'gst_cents', 0, 'total_cents', 0));
  end if;
  perform centre_invoice_run_prepare(p_org, ms, today);
  select coalesce(jsonb_agg(jsonb_build_object('student_id', c.d_student_id, 'name', c.d_student_name, 'household_id', c.d_household_id, 'key', c.d_unit_key,
           'mode', c.d_mode, 'percent_bp', c.d_percent_bp, 'first_month_cents', c.d_first_month_cents, 'amount_cents', c.d_amount_cents,
           'taxable', c.d_taxable, 'frozen', c.d_frozen) order by c.d_student_name, c.d_student_id), '[]'::jsonb), coalesce(sum(c.d_amount_cents), 0)
    into deps, dcents from centre_deposit_run_candidates(p_org, ms, today) c;
  dnote := centre_deposit_note(s);
  return res || jsonb_build_object('deposits', deps, 'deposit_note', dnote, 'deposit_mode', coalesce(s#>>'{billing,deposit,mode}', 'none'),
    'ready', (select coalesce(jsonb_agg(jsonb_build_object(
        'key', u.unit_key, 'name', u.uname, 'household_id', u.hid, 'student_id', u.ustu, 'lessons', u.n_lessons,
        'subtotal_cents', u.subtotal, 'net_cents', u.net, 'gst_cents', u.gst, 'total_cents', u.total,
        'not_marked', u.n_unmarked, 'no_price', u.n_no_price, 'free_trials', u.n_free,
        'lines', (select jsonb_agg(jsonb_build_object('kind', r.line_kind, 'lesson_id', r.lesson_id, 'student_id', r.student_id, 'student_name', r.student_name,
                                                      'date', r.lesson_date, 'description', r.description, 'qty', r.qty, 'unit_cents', r.unit_cents,
                                                      'line_cents', r.qty * r.unit_cents)
                                       order by r.student_name, r.ord, r.lesson_date, r.start_time, r.lesson_id)
                    from _td_run r where r.unit_key = u.unit_key and r.state = 'line')) order by u.uname, u.unit_key), '[]'::jsonb)
                from _td_units u where u.status = 'ready'),
    'held_back', (select coalesce(jsonb_agg(jsonb_build_object(
        'key', u.unit_key, 'name', u.uname, 'household_id', u.hid, 'student_id', u.ustu, 'not_marked', u.n_unmarked,
        'reasons', (select jsonb_agg(jsonb_build_object('reason', 'charge pending: ' || x.sname, 'student_id', x.sid, 'student_name', x.sname, 'lessons', x.n)
                                    order by x.sname) from (select r.student_name as sname, r.student_id as sid, count(*)::int as n
                                                              from _td_run r where r.unit_key = u.unit_key and r.state = 'pending' group by 1, 2) x),
        'lessons', (select jsonb_agg(jsonb_build_object('lesson_id', r.lesson_id, 'student_name', r.student_name, 'date', r.lesson_date) order by r.lesson_date, r.student_name)
                      from _td_run r where r.unit_key = u.unit_key and r.state = 'pending')) order by u.uname, u.unit_key), '[]'::jsonb)
                from _td_units u where u.status = 'held'),
    'drafts', (select coalesce(jsonb_agg(jsonb_build_object('key', u.unit_key, 'name', u.uname, 'invoice_id', u.draft_id, 'household_id', u.hid, 'student_id', u.ustu,
                                                            'total_cents', (select i.total_cents from centre_invoices i where i.id = u.draft_id), 'new_lessons', u.n_lessons)
                                         order by u.uname, u.unit_key), '[]'::jsonb) from _td_units u where u.status = 'draft'),
    'totals', jsonb_build_object(
        'deposits', jsonb_array_length(deps), 'deposit_cents', dcents,
        'ready',     (select count(*) from _td_units where status = 'ready'),
        'held_back', (select count(*) from _td_units where status = 'held'),
        'drafts',    (select count(*) from _td_units where status = 'draft'),
        'lessons',   (select coalesce(sum(n_lessons), 0) from _td_units where status = 'ready'),
        'not_marked',(select coalesce(sum(n_unmarked), 0) from _td_units),
        'subtotal_cents', (select coalesce(sum(subtotal), 0) from _td_units where status = 'ready'),
        'gst_cents',      (select coalesce(sum(gst), 0) from _td_units where status = 'ready'),
        'total_cents',    (select coalesce(sum(total), 0) from _td_units where status = 'ready')));
end $$;

-- create drafts: after the lesson drafts, one separate 'Refundable deposit' draft per student getting their first deposit (issued straight away when the centre doesn't review)
create or replace function public.centre_invoice_run_create_drafts(p_org uuid, p_period date) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_invoicing_gate(p_org); ms date := centre_invoice_month(p_period, today); me date := (ms + interval '1 month - 1 day')::date;
  s jsonb := coalesce(org_settings_on(p_org, ms), org_settings_on(p_org, today)); note text; review boolean; u record; inv uuid; made jsonb := '[]'::jsonb;
  n_made int := 0; n_issued int := 0; n_held int; n_draft int; n_empty int; iss centre_invoices;
  dep record; dinv uuid; dmade jsonb := '[]'::jsonb; n_dep int := 0; n_dep_issued int := 0;
begin
  if s is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  note := centre_invoice_model_note(s);
  if note is not null then raise exception 'NOT_BUILT: %', note using errcode = 'P0001'; end if;
  review := coalesce((s#>>'{invoicing,review_before_sending}')::boolean, true);
  perform pg_advisory_xact_lock(hashtextextended(p_org::text || ':' || ms::text, 77));      -- two people pressing the button at once: one waits
  perform centre_invoice_run_prepare(p_org, ms, today);
  -- the deposits to raise are decided BEFORE the lesson drafts exist (a student's "first invoice" is judged without the one being made now)
  drop table if exists pg_temp._td_dep;
  create temp table _td_dep on commit drop as select * from centre_deposit_run_candidates(p_org, ms, today);
  for u in select * from _td_units where status = 'ready' order by uname, unit_key loop
    insert into centre_invoices(org_id, kind, household_id, student_id, period_start, period_end, gst_registered, gst_rate_bp, gst_inclusive, net_cents, gst_cents, total_cents)
    values (p_org, 'lesson', u.hid, u.ustu, ms, me, u.gst_reg, u.gst_rate, u.gst_inc, u.net, u.gst, u.total) returning id into inv;
    insert into centre_invoice_lines(org_id, invoice_id, position, lesson_id, student_id, fee_kind, description, qty, unit_cents)
    select p_org, inv, row_number() over (order by r.student_name, r.ord, r.lesson_date, r.start_time, r.lesson_id), r.lesson_id, r.student_id,
           case when r.line_kind in ('registration', 'materials', 'sibling_discount') then r.line_kind end, r.description, r.qty, r.unit_cents
      from _td_run r where r.unit_key = u.unit_key and r.state = 'line';
    n_made := n_made + 1;
    if not review then iss := centre_invoice_issue_draft(inv, today); n_issued := n_issued + 1; end if;
    made := made || jsonb_build_object('id', inv, 'name', u.uname, 'total_cents', u.total);
  end loop;
  -- the refundable deposits: each its own invoice, raised once per student, with the student's first run
  for dep in select * from _td_dep order by d_student_name, d_student_id loop
    dinv := centre_deposit_make_invoice(p_org, dep.d_student_id, dep.d_deposit_id, dep.d_amount_cents, dep.d_taxable, dep.d_mode, dep.d_percent_bp, dep.d_first_month_cents, ms, me, today);
    if not review then iss := centre_invoice_issue_draft(dinv, today); n_dep_issued := n_dep_issued + 1; end if;
    n_dep := n_dep + 1; dmade := dmade || jsonb_build_object('id', dinv, 'name', dep.d_student_name, 'total_cents', dep.d_amount_cents);
  end loop;
  select count(*) into n_held from _td_units where status = 'held';
  select count(*) into n_draft from _td_units where status = 'draft';
  select count(*) into n_empty from _td_units where status = 'empty';
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'centre_invoice_run_create', 'centre_invoices', p_org::text || ':' || ms::text, null,
          jsonb_build_object('period_start', ms, 'created', n_made, 'issued_straight_away', n_issued, 'held_back', n_held, 'already_drafted', n_draft, 'deposits', n_dep, 'deposits_issued', n_dep_issued));
  return jsonb_build_object('period_start', ms, 'created', n_made, 'issued', n_issued, 'held_back', n_held, 'already_drafted', n_draft, 'nothing_to_bill', n_empty,
                            'review_before_sending', review, 'invoices', made, 'deposits', n_dep, 'deposits_issued', n_dep_issued, 'deposit_invoices', dmade);
end $$;

-- approve all: the month's deposit drafts are issued with the lesson drafts, each family's lesson invoice first
create or replace function public.centre_invoice_approve_all(p_org uuid, p_period date) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := centre_invoicing_gate(p_org); ms date := centre_invoice_month(p_period, today); d record; r centre_invoices; n int := 0; nd int := 0; tot bigint := 0; first_no text; last_no text;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_org::text || ':' || ms::text, 77));
  for d in select i.id from centre_invoices i left join households h on h.id = i.household_id and h.org_id = i.org_id left join students st on st.id = i.student_id and st.org_id = i.org_id
            where i.org_id = p_org and i.kind in ('lesson', 'deposit') and i.status = 'draft' and i.period_start = ms
            order by coalesce(h.name, st.name), (i.kind <> 'lesson'), st.name, i.id for update of i loop
    r := centre_invoice_issue_draft(d.id, today);
    n := n + 1; tot := tot + r.total_cents; if r.kind = 'deposit' then nd := nd + 1; end if; first_no := coalesce(first_no, r.number_text); last_no := r.number_text;
  end loop;
  if n = 0 then raise exception 'NOTHING_TO_APPROVE: there are no drafts for that month' using errcode = 'P0001'; end if;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'centre_invoice_approve_all', 'centre_invoices', p_org::text || ':' || ms::text, null,
          jsonb_build_object('period_start', ms, 'issued', n, 'first', first_no, 'last', last_no, 'total_cents', tot, 'deposits', nd));
  return jsonb_build_object('issued', n, 'first_number', first_no, 'last_number', last_no, 'total_cents', tot, 'deposits', nd);
end $$;

-- list: deposit invoices are listed with the month's invoices, marked kind = 'deposit'
create or replace function public.centre_invoice_list(p_org uuid, p_period date default null, p_status text default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_invoicing_gate(p_org); ms date := case when p_period is null then null else centre_invoice_month(p_period, today) end;
begin
  if p_status is not null and p_status not in ('draft', 'issued', 'void') then raise exception 'BAD_VALUE: unknown status' using errcode = 'P0001'; end if;
  return jsonb_build_object('today', today, 'rows', (select coalesce(jsonb_agg(jsonb_build_object(
      'id', q.id, 'kind', q.kind, 'status', q.status, 'number', q.number_text, 'name', q.nm, 'household_id', q.household_id, 'student_id', q.student_id,
      'period_start', q.period_start, 'period_end', q.period_end, 'issue_date', q.issue_date, 'due_date', q.due_date,
      'net_cents', q.net_cents, 'gst_cents', q.gst_cents, 'total_cents', q.total_cents, 'lines', q.nl) order by q.ord, q.nm, q.id), '[]'::jsonb)
    from (select i.*, coalesce(case when i.kind = 'deposit' or (i.student_id is not null and i.household_id is null) then st.name end, h.name, st.name) as nm,
                 case i.status when 'draft' then 0 when 'issued' then 1 else 2 end as ord,
                 (select count(*) from centre_invoice_lines l where l.invoice_id = i.id)::int as nl
            from centre_invoices i left join households h on h.id = i.household_id and h.org_id = i.org_id left join students st on st.id = i.student_id and st.org_id = i.org_id
           where i.org_id = p_org and i.kind in ('lesson', 'deposit') and (ms is null or i.period_start = ms) and (p_status is null or i.status = p_status)
           order by case i.status when 'draft' then 0 when 'issued' then 1 else 2 end, coalesce(h.name, st.name), i.id limit 1000) q));
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 7. WHAT THE DEPOSITS SCREEN READS (explicit columns; no table access needed)
-- ---------------------------------------------------------------------------------------------------
-- one row per student with a deposit: required, held, short, waived, state and the invoice. p_student narrows it to one student.
--   state: draft (invoice not approved) · unpaid · part_paid · held · waived
create or replace function public.centre_deposit_status(p_org uuid, p_student uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_deposit_gate(p_org, 'view'); res jsonb;
begin
  with led as (
    select l.student_id, coalesce(sum(l.cents) filter (where l.kind <> 'waived'), 0)::bigint as held,
           coalesce(sum(l.cents) filter (where l.kind = 'waived'), 0)::bigint as waived,
           coalesce(sum(l.cents) filter (where l.kind <> 'waived' and l.taxable), 0)::bigint as taxable_held
      from centre_deposit_ledger l where l.org_id = p_org group by l.student_id
  ), q as (
    select d.id as deposit_id, d.student_id, st.name, h.name as household_name, d.household_id, d.source, d.mode, d.percent_bp, d.first_month_cents,
           d.required_cents, coalesce(i.total_cents, d.required_cents) as due, d.taxable, d.period_start, i.id as invoice_id, i.number_text, i.status as istatus, i.issue_date, i.due_date,
           coalesce((select sum(c.total_cents) from centre_invoices c where c.credits_invoice_id = i.id and c.status = 'issued'), 0)::bigint as credited,
           coalesce(led.held, 0) as held, coalesce(led.waived, 0) as waived, coalesce(led.taxable_held, 0) as taxable_held
      from centre_deposits d
      join students st on st.id = d.student_id and st.org_id = d.org_id
      left join households h on h.id = d.household_id and h.org_id = d.org_id
      left join centre_invoices i on i.id = d.invoice_id and i.org_id = d.org_id
      left join led on led.student_id = d.student_id
     where d.org_id = p_org and (p_student is null or d.student_id = p_student)
  ), r as (
    select q.*, case when q.waived > 0 then 'waived' when q.istatus = 'draft' then 'draft' when q.held >= q.due - q.credited then 'held'
                     when q.held > 0 then 'part_paid' when q.istatus = 'void' then 'draft' else 'unpaid' end as state,
           case when q.waived > 0 or q.istatus in ('draft', 'void') then 0 else greatest(q.due - q.credited - q.held, 0) end as short
      from q
  )
  select jsonb_build_object('today', today,
    'rows', coalesce((select jsonb_agg(jsonb_build_object('deposit_id', r.deposit_id, 'student_id', r.student_id, 'name', r.name, 'household_id', r.household_id,
              'household_name', r.household_name, 'source', r.source, 'mode', r.mode, 'percent_bp', r.percent_bp, 'first_month_cents', r.first_month_cents,
              'required_cents', r.required_cents, 'due_cents', r.due, 'held_cents', r.held, 'waived_cents', r.waived, 'short_cents', r.short, 'state', r.state, 'taxable', r.taxable,
              'period_start', r.period_start, 'invoice_id', r.invoice_id, 'invoice_number', r.number_text, 'invoice_status', r.istatus, 'due_date', r.due_date)
              order by r.name, r.student_id) from r), '[]'::jsonb),
    'totals', jsonb_build_object('held_cents', coalesce((select sum(held) from r), 0), 'taxable_held_cents', coalesce((select sum(taxable_held) from r), 0),
              'students_holding', (select count(*) from r where held > 0), 'required_cents', coalesce((select sum(required_cents) from r where state <> 'waived'), 0),
              'short_cents', coalesce((select sum(short) from r), 0), 'deposits', (select count(*) from r)))
    into res;
  return res;
end $$;

-- the "Deposits held" report: money held for families, per student and in total. NEVER part of a revenue figure.
create or replace function public.centre_deposits_held(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_deposit_gate(p_org, 'view'); res jsonb;
begin
  select jsonb_build_object('today', today,
    'total_held_cents', coalesce(sum(x.held), 0), 'taxable_held_cents', coalesce(sum(x.taxable_held), 0), 'students_holding', count(*),
    'rows', coalesce(jsonb_agg(jsonb_build_object('student_id', x.student_id, 'name', x.name, 'household_name', x.hname, 'held_cents', x.held,
              'required_cents', x.required, 'since', x.since) order by x.name, x.student_id), '[]'::jsonb))
    into res
    from (select l.student_id, st.name, h.name as hname, d.required_cents as required, min(l.entry_date) as since,
                 sum(l.cents) filter (where l.kind <> 'waived') as held, coalesce(sum(l.cents) filter (where l.kind <> 'waived' and l.taxable), 0) as taxable_held
            from centre_deposit_ledger l
            join centre_deposits d on d.id = l.deposit_id and d.org_id = l.org_id
            join students st on st.id = l.student_id and st.org_id = l.org_id
            left join households h on h.id = d.household_id and h.org_id = d.org_id
           where l.org_id = p_org group by l.student_id, st.name, h.name, d.required_cents
          having coalesce(sum(l.cents) filter (where l.kind <> 'waived'), 0) > 0) x;
  return res;
end $$;

-- one student's ledger, oldest first, with the balance after each row
create or replace function public.centre_deposit_ledger_get(p_org uuid, p_student uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_deposit_gate(p_org, 'view'); nm text;
begin
  select st.name into nm from students st where st.id = p_student and st.org_id = p_org;
  if nm is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  return jsonb_build_object('today', today, 'student_id', p_student, 'name', nm,
    'status', (centre_deposit_status(p_org, p_student)->'rows'->0),
    'entries', coalesce((select jsonb_agg(jsonb_build_object('id', e.id, 'date', e.entry_date, 'kind', e.kind, 'cents', e.cents, 'taxable', e.taxable,
                'invoice_number', e.number_text, 'reason', e.reason, 'balance_cents', e.bal) order by e.entry_date, e.created_at, e.id)
              from (select l.*, i.number_text, sum(l.cents) filter (where l.kind <> 'waived') over (order by l.entry_date, l.created_at, l.id) as bal
                      from centre_deposit_ledger l left join centre_invoices i on i.id = l.invoice_id and i.org_id = l.org_id
                     where l.org_id = p_org and l.student_id = p_student) e), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 8. WAIVE a deposit (a reason is always needed; who may is the centre's choice: billing.deposit.waived_by)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_deposit_waive(p_student uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; s jsonb; wb text; d centre_deposits; inv centre_invoices; b record; why text := nullif(trim(coalesce(p_reason, '')), ''); waived bigint; action text; cn jsonb;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select st.org_id into org from students st where st.id = p_student;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := centre_deposit_gate(org, 'member');                     -- any owner/staff passes the door; the waived_by rule below decides
  s := org_settings_on(org, today);
  wb := coalesce(s#>>'{billing,deposit,waived_by}', 'owner');
  if wb = 'nobody' then raise exception 'NOT_ALLOWED: this centre doesn''t allow deposits to be waived (see Centre settings)' using errcode = '42501'; end if;
  if wb = 'owner' and not org_can(org, 'owner') then raise exception 'NOT_ALLOWED: only the centre owner can waive a deposit' using errcode = '42501'; end if;
  if wb = 'issue_invoices' and not org_can(org, 'issue_invoices') then raise exception 'NOT_ALLOWED: only the owner or staff who issue invoices can waive a deposit' using errcode = '42501'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why this deposit is being waived' using errcode = 'P0001'; end if;
  if length(why) > 300 then raise exception 'TOO_LONG: keep the reason under 300 characters' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_student::text, 6));
  select * into d from centre_deposits where org_id = org and student_id = p_student;
  if d.id is null then raise exception 'NO_DEPOSIT: this student has no deposit to waive' using errcode = 'P0001'; end if;
  if exists (select 1 from centre_deposit_ledger where org_id = org and student_id = p_student and kind = 'waived') then
    raise exception 'ALREADY_WAIVED: this deposit has already been waived' using errcode = 'P0001'; end if;
  if d.source <> 'invoice_run' or d.invoice_id is null then
    raise exception 'NOT_ALLOWED: this deposit was collected before TutorDeck, so there is nothing left to waive' using errcode = '42501'; end if;
  select * into inv from centre_invoices where id = d.invoice_id and org_id = org for update;
  if inv.status = 'draft' then
    update centre_invoices set status = 'void', void_reason = 'Deposit waived: ' || why where id = inv.id;       -- never had a number, so no gap
    waived := d.required_cents; action := 'draft_discarded';
  elsif inv.status = 'issued' then
    select * into b from centre_balance_rows(org, array[inv.id]);
    if b.balance_cents <= 0 then raise exception 'NOT_ALLOWED: the deposit is already paid in full, so there is nothing to waive (it can be refunded later)' using errcode = '42501'; end if;
    cn := centre_issue_credit_note(inv.id, b.balance_cents, 'Deposit waived: ' || why);
    waived := b.balance_cents; action := 'credit_note';
  else
    raise exception 'NOT_ALLOWED: that deposit invoice was discarded, so there is nothing to waive' using errcode = '42501';
  end if;
  insert into centre_deposit_ledger(org_id, student_id, deposit_id, kind, cents, taxable, invoice_id, entry_date, reason)
  values (org, p_student, d.id, 'waived', waived, d.taxable, inv.id, today, why);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'centre_deposit_waive', 'centre_deposits', d.id::text, null, jsonb_build_object('waived_cents', waived, 'how', action, 'waived_by_rule', wb));
  return jsonb_build_object('student_id', p_student, 'waived_cents', waived, 'how', action, 'credit_note', cn);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 9. OPENING BALANCE: a deposit collected before TutorDeck (owner only; no invoice, no number, no revenue)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_deposit_opening_balance(p_student uuid, p_amount_cents bigint, p_date date, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; st students; did uuid; note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into st from students where id = p_student;
  if st.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  org := st.org_id;
  today := centre_deposit_gate(org, 'owner');
  if p_amount_cents is null or p_amount_cents <= 0 then raise exception 'BAD_VALUE: the amount must be more than S$0.00' using errcode = 'P0001'; end if;
  if p_amount_cents > 100000000 then raise exception 'BAD_VALUE: that amount is too large to be right (over S$1,000,000)' using errcode = 'P0001'; end if;
  if p_date is null then raise exception 'BAD_VALUE: say the date the deposit was collected' using errcode = 'P0001'; end if;
  if p_date > today then raise exception 'BAD_VALUE: the date can''t be in the future' using errcode = 'P0001'; end if;
  if p_date < today - 3650 then raise exception 'BAD_VALUE: that date is too far back (over 10 years)' using errcode = 'P0001'; end if;
  if length(coalesce(note, '')) > 300 then raise exception 'TOO_LONG: keep the note under 300 characters' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_student::text, 6));
  if exists (select 1 from centre_deposits where org_id = org and student_id = p_student) then
    raise exception 'ALREADY_HAS_DEPOSIT: this student already has a deposit record' using errcode = 'P0001'; end if;
  insert into centre_deposits(org_id, student_id, household_id, source, mode, required_cents, taxable, period_start)
  values (org, p_student, st.household_id, 'opening_balance', 'opening', p_amount_cents, false, date_trunc('month', p_date)::date) returning id into did;
  insert into centre_deposit_ledger(org_id, student_id, deposit_id, kind, cents, taxable, entry_date, reason)
  values (org, p_student, did, 'opening_balance', p_amount_cents, false, p_date, coalesce(note, 'Collected before TutorDeck'));
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'centre_deposit_opening_balance', 'centre_deposits', did::text, null, jsonb_build_object('amount_cents', p_amount_cents, 'date', p_date));
  return jsonb_build_object('deposit_id', did, 'student_id', p_student, 'held_cents', p_amount_cents);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 10. revenue totals that leave deposits OUT (replaces the S1 function; same keys, plus the deposit figures reported separately)
--     A deposit invoice, a credit note against one, and the cash that paid a deposit are not revenue. GST on a TAXABLE deposit is still counted,
--     because that is tax collected.
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_revenue_totals(p_org uuid, p_from date default null, p_to date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb; dep_in bigint; dep_held bigint;
begin
  if auth.uid() is null or not exists (select 1 from organisations o where o.id = p_org and o.kind = 'centre') or not org_can(p_org, 'view_revenue') then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  select jsonb_build_object(
    'invoiced_cents',  coalesce(sum(i.total_cents) filter (where i.kind not in ('credit_note', 'deposit')), 0),
    'gst_cents',       coalesce(sum(i.gst_cents) filter (where i.kind <> 'credit_note'), 0) - coalesce(sum(i.gst_cents) filter (where i.kind = 'credit_note'), 0),
    'credited_cents',  coalesce(sum(i.total_cents) filter (where i.kind = 'credit_note' and coalesce(ci.kind, '') <> 'deposit'), 0),
    'invoices',        count(*) filter (where i.kind not in ('credit_note', 'deposit')),
    'deposits_invoiced_cents', coalesce(sum(i.total_cents) filter (where i.kind = 'deposit'), 0))
    into r from centre_invoices i left join centre_invoices ci on ci.id = i.credits_invoice_id and ci.org_id = i.org_id
   where i.org_id = p_org and i.status = 'issued' and (p_from is null or i.issue_date >= p_from) and (p_to is null or i.issue_date <= p_to);
  select coalesce(sum(a.cents), 0) into dep_in
    from centre_payment_allocations a join centre_payments p on p.id = a.payment_id and p.org_id = a.org_id
    join centre_invoices i on i.id = a.invoice_id and i.org_id = a.org_id and i.kind = 'deposit'
   where a.org_id = p_org and (p_from is null or p.received_on >= p_from) and (p_to is null or p.received_on <= p_to);
  select coalesce(sum(cents) filter (where kind <> 'waived'), 0) into dep_held from centre_deposit_ledger where org_id = p_org;
  r := r || jsonb_build_object('received_cents', coalesce((select sum(case when p.kind = 'payment' then p.amount_cents else -p.amount_cents end)
       from centre_payments p where p.org_id = p_org and (p_from is null or p.received_on >= p_from) and (p_to is null or p.received_on <= p_to)), 0) - dep_in,
       'deposits_received_cents', dep_in, 'deposits_held_cents', dep_held);
  return r;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 11. function access
-- ---------------------------------------------------------------------------------------------------
revoke all on function public.centre_deposit_guard() from public, anon, authenticated;
revoke all on function public.centre_deposit_ledger_guard() from public, anon, authenticated;
revoke all on function public.centre_deposit_alloc_hook() from public, anon, authenticated;
revoke all on function public.centre_deposit_gate(uuid, text) from public, anon, authenticated;
revoke all on function public.centre_deposit_run_candidates(uuid, date, date) from public, anon, authenticated;
revoke all on function public.centre_deposit_make_invoice(uuid, uuid, uuid, bigint, boolean, text, int, bigint, date, date, date) from public, anon, authenticated;
revoke all on function public.centre_deposit_note(jsonb) from public, anon;
revoke all on function public.centre_deposit_status(uuid, uuid) from public, anon;
revoke all on function public.centre_deposits_held(uuid) from public, anon;
revoke all on function public.centre_deposit_ledger_get(uuid, uuid) from public, anon;
revoke all on function public.centre_deposit_waive(uuid, text) from public, anon;
revoke all on function public.centre_deposit_opening_balance(uuid, bigint, date, text) from public, anon;
revoke all on function public.centre_invoice_guard() from public, anon, authenticated;
revoke all on function public.centre_revenue_totals(uuid, date, date) from public, anon;
revoke all on function public.centre_invoice_run_preview(uuid, date) from public, anon;
revoke all on function public.centre_invoice_run_create_drafts(uuid, date) from public, anon;
revoke all on function public.centre_invoice_approve_all(uuid, date) from public, anon;
revoke all on function public.centre_invoice_list(uuid, date, text) from public, anon;
grant execute on function public.centre_deposit_note(jsonb), public.centre_deposit_status(uuid, uuid), public.centre_deposits_held(uuid), public.centre_deposit_ledger_get(uuid, uuid),
  public.centre_deposit_waive(uuid, text), public.centre_deposit_opening_balance(uuid, bigint, date, text), public.centre_revenue_totals(uuid, date, date),
  public.centre_invoice_run_preview(uuid, date), public.centre_invoice_run_create_drafts(uuid, date), public.centre_invoice_approve_all(uuid, date),
  public.centre_invoice_list(uuid, date, text) to authenticated, service_role;

-- #####################################################################################################
-- ### PART 4 of 9 — refunds + family credit (request, approve, pay, apply)
-- ### source branch: claude/t4-s5-refunds   file: db/migration_centre_refunds.sql   undo: db/migration_centre_refunds_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T4 step S5 — centre refunds and family credit: refund a deposit, refund family credit, apply credit to the next invoice, keep a deposit   undo: migration_centre_refunds_down.sql
-- =====================================================================================================
-- Run order everywhere: org_foundation → billing → attendance → tutor_access → org_delete → function_lockdown → org_separation →
--   staff_home → staff_students → staff_attendance → staff_charges → staff_trials → staff_timetable → money_settings →
--   centre_money → centre_invoice_run → centre_payments → centre_deposits → centre_refunds.
-- Needs migration_centre_deposits.sql (S4: the deposit ledger) and migration_centre_payments.sql (S3: payments, the family credit ledger).
-- Run on the DEV project first. LIVE only when the owner says ship: it reads no existing row and changes none (two new tables, three new nullable
-- columns, two widened checks, new functions; it REPLACES centre_refund_family_credit and centre_revenue_totals with versions that know about refunds).
-- Safe to run twice.
--
-- WHAT A REFUND IS HERE (owner-approved T4 decisions, 2026-11-26)
--   Money held for a family leaves in a TRACKED, APPROVED, RECORDED step, never in one click and never by editing a number:
--     requested  →  approved  →  paid        (or  cancelled  from the first two)
--   centre_refunds           one IMMUTABLE row per request: what is asked (cash to pay out, deposit kept as forfeit, deposit kept against unpaid invoices),
--                            the calculation it came from (held, notice, the centre's release rule), the GST share, who asked and when.
--   centre_refund_events     APPEND-ONLY: approved · paid · cancelled, each with who, when, how it was paid and a reference. The state of a refund is the
--                            last event. Nothing is ever edited or deleted (a mistake is a new row on the ledgers, as everywhere in centre money).
--   The two ledgers (deposit ledger S4, family credit S3) get their negative row ONLY when the refund is PAID: refunded · forfeited · applied (deposit)
--   and refund (credit). Until then the money is RESERVED: every request counts the open refunds, so nothing can be refunded twice or beyond what is held.
--
-- THE CENTRE'S SETTINGS THAT DECIDE THINGS (process rules: read as of the day of the action)
--   billing.deposit.refund_approved_by   owner     only the centre owner approves
--                                        staff     the owner, or staff who may act on that kind of refund (below)
--                                        four_eyes the same people, but never the person who asked
--   billing.deposit.release              refund_full         the system SUGGESTS refunding what is held (less any forfeit)
--                                        refund_less_unpaid  …minus the family's unpaid invoices, which the deposit is KEPT AGAINST (a GST-free deposit only)
--                                        admin_decides       no suggestion: the person types the three amounts
--   billing.deposit.forfeit_notice_days  0 = never forfeit. Otherwise leaving with LESS notice than this many days suggests keeping the deposit.
--                                        The notice date is typed when the refund is asked for (the day the family said they were leaving).
--   billing.deposit.taxable              (S4, frozen on each deposit) a taxable deposit already carried GST when received, so its refund also gives that
--                                        GST back (stored on the refund, counted by centre_revenue_totals); it can't be kept against invoices (that would tax it twice).
--   payments.overpayments                (S3) credit or refund: unchanged. Both kinds of family credit can be applied or refunded here.
--
-- WHO MAY CALL
--   family credit  request / pay / cancel: owner or staff with record_payments.   deposit  request / pay / cancel: owner or staff with issue_invoices
--   (owner decision: "waiving or refunding a deposit needs the owner or a staff member with issue_invoices"; waiving is S4, unchanged).
--   approve: as refund_approved_by says. Apply credit to an invoice: owner or staff with record_payments.
--   reading: owner or staff with record_payments, issue_invoices or view_revenue.
--   Tutors, parents, switched-off staff, solo organisations, strangers and anonymous callers get NOT_FOUND. No browser role can write either new table.
--
-- DOUBLE PRESS: a repeated request with the same request key, or a repeated approve / pay / cancel, answers "already" and writes nothing.
-- RULES THAT NEVER CHANGE: a refund can't be asked for more than is held less what is already reserved; a deposit refund waits until the student's last
--   lesson day has passed and their final invoice is issued; a reference can't hold a full bank or PayNow number (PDPA: "ending 1234" is enough).
-- AUDIT: both tables use the S1 audit trigger (payee, reference, reason and note replaced by "[redacted]"); each function adds a summary row with amounts only.
-- NOT BUILT HERE (still on the plan): moving a deposit between students, adjusting a deposit, a numbered refund statement document.
-- =====================================================================================================

-- ---------------------------------------------------------------------------------------------------
-- 1. the two tables
-- ---------------------------------------------------------------------------------------------------
create table if not exists public.centre_refunds (
  id             uuid primary key default gen_random_uuid(),
  org_id         uuid not null references public.organisations(id) on delete cascade,
  kind           text not null check (kind in ('deposit', 'family_credit')),
  student_id     uuid,                                      -- deposit refunds
  household_id   uuid,                                      -- the family (a snapshot for a deposit)
  deposit_id     uuid,
  refund_cents   bigint not null check (refund_cents >= 0), -- cash paid out to the family
  forfeit_cents  bigint not null default 0 check (forfeit_cents >= 0),   -- deposit kept by the centre (becomes income)
  set_off_cents  bigint not null default 0 check (set_off_cents >= 0),   -- deposit kept against the family's unpaid invoices
  held_cents     bigint not null check (held_cents >= 0),   -- what was held when it was asked (frozen, for the statement)
  taxable        boolean not null default false,
  gst_cents      bigint not null default 0 check (gst_cents >= 0),       -- GST given back with a taxable deposit's refund
  release_rule   text,                                      -- the centre's setting when it was asked
  notice_days    int,                                       -- forfeit_notice_days when it was asked
  notice_given_on date,
  lesson_end     date,
  payer_name     text,                                      -- the payee, free text (redacted in the audit copy)
  reason         text not null,
  request_key    text,
  requested_by   uuid default auth.uid(),
  requested_on   date not null,
  created_at     timestamptz not null default now(),
  unique (id, org_id),
  foreign key (student_id, org_id)   references public.students(id, org_id),
  foreign key (household_id, org_id) references public.households(id, org_id),
  foreign key (deposit_id, org_id)   references public.centre_deposits(id, org_id),
  check ((kind = 'deposit') = (student_id is not null and deposit_id is not null)),
  check (kind = 'deposit' or (household_id is not null and forfeit_cents = 0 and set_off_cents = 0 and refund_cents > 0 and gst_cents = 0)),
  check (kind = 'family_credit' or (refund_cents + forfeit_cents + set_off_cents > 0)),
  check (length(btrim(reason)) > 0)
);
create unique index if not exists centre_refunds_key on public.centre_refunds(org_id, request_key) where request_key is not null;
create index if not exists centre_refunds_student on public.centre_refunds(org_id, student_id) where student_id is not null;
create index if not exists centre_refunds_household on public.centre_refunds(org_id, household_id) where household_id is not null;

create table if not exists public.centre_refund_events (
  id             uuid primary key default gen_random_uuid(),
  org_id         uuid not null references public.organisations(id) on delete cascade,
  refund_id      uuid not null,
  kind           text not null check (kind in ('approved', 'paid', 'cancelled')),
  event_on       date not null,                              -- the centre's day it happened (for 'paid': the day the money went out)
  method         text check (method in ('manual_paynow', 'bank', 'cash', 'cheque', 'other')),
  reference      text,                                       -- free text, never a full account number; redacted in the audit copy
  reason         text,
  note           text,
  set_off_cents  bigint,                                     -- 'paid': how much was really kept against invoices (never more than was asked)
  actor          uuid default auth.uid(),
  created_at     timestamptz not null default clock_timestamp(),     -- not now(): approve and pay can happen in one transaction and must stay in order
  unique (id, org_id),
  foreign key (refund_id, org_id) references public.centre_refunds(id, org_id),
  check (kind <> 'cancelled' or length(btrim(coalesce(reason, ''))) > 0)
);
create unique index if not exists centre_refund_events_approved on public.centre_refund_events(refund_id) where kind = 'approved';
create unique index if not exists centre_refund_events_closed on public.centre_refund_events(refund_id) where kind in ('paid', 'cancelled');

-- the ledgers learn which refund wrote a row; the credit ledger learns "applied" and a key that makes applying idempotent; payments learn two internal methods
alter table public.centre_deposit_ledger add column if not exists refund_id uuid;
alter table public.centre_family_credit add column if not exists refund_id uuid;
alter table public.centre_family_credit add column if not exists request_key text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'centre_deposit_ledger_refund_fk') then
    alter table public.centre_deposit_ledger add constraint centre_deposit_ledger_refund_fk foreign key (refund_id, org_id) references public.centre_refunds(id, org_id);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'centre_family_credit_refund_fk') then
    alter table public.centre_family_credit add constraint centre_family_credit_refund_fk foreign key (refund_id, org_id) references public.centre_refunds(id, org_id);
  end if;
end $$;
create unique index if not exists centre_family_credit_applied_key on public.centre_family_credit(org_id, request_key) where request_key is not null;

do $$
declare c record;
begin
  -- family credit kinds gain 'applied' (credit used to pay an invoice)
  if not exists (select 1 from pg_constraint where conname = 'centre_family_credit_kind_s5') then
    for c in select conname from pg_constraint where conrelid = 'public.centre_family_credit'::regclass and contype = 'c'
              and pg_get_constraintdef(oid) like '%payment_reversal%' and pg_get_constraintdef(oid) like '%excess_release%' loop
      execute format('alter table public.centre_family_credit drop constraint %I', c.conname);
    end loop;
    alter table public.centre_family_credit add constraint centre_family_credit_kind_s5
      check (kind in ('overpayment', 'credit_note_excess', 'payment_reversal', 'excess_release', 'refund', 'applied'));
  end if;
  -- payments gain two internal methods: 'family_credit' and 'deposit' (money that is already held, moved onto an invoice; it is not new cash)
  if not exists (select 1 from pg_constraint where conname = 'centre_payments_method_s5') then
    for c in select conname from pg_constraint where conrelid = 'public.centre_payments'::regclass and contype = 'c'
              and pg_get_constraintdef(oid) like '%manual_paynow%' and pg_get_constraintdef(oid) like '%cheque%' loop
      execute format('alter table public.centre_payments drop constraint %I', c.conname);
    end loop;
    alter table public.centre_payments add constraint centre_payments_method_s5
      check (method in ('manual_paynow', 'bank', 'cash', 'cheque', 'other', 'family_credit', 'deposit'));
  end if;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 2. guards (same shape as S1/S4: centres only, append-only, the exception for deleting a whole organisation)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_refund_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if tg_op = 'DELETE' and centre_money_deleting(old.org_id) then return old; end if;
    raise exception 'A refund request is a money record and can''t be changed (cancel it and ask again)' using errcode = '42501';
  end if;
  return new;
end $$;

-- the state machine, enforced where it can't be bypassed: approved once (not after the end), paid only after approved, one ending
create or replace function public.centre_refund_event_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare ended text;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if tg_op = 'DELETE' and centre_money_deleting(old.org_id) then return old; end if;
    raise exception 'A refund''s history is append-only (nothing is edited or deleted)' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(new.refund_id::text, 7));
  select e.kind into ended from centre_refund_events e where e.refund_id = new.refund_id and e.org_id = new.org_id and e.kind in ('paid', 'cancelled');
  if ended is not null then raise exception 'That refund is already % and can''t change again', ended using errcode = '42501'; end if;
  if new.kind = 'paid' and not exists (select 1 from centre_refund_events e where e.refund_id = new.refund_id and e.org_id = new.org_id and e.kind = 'approved') then
    raise exception 'A refund can only be paid after it is approved' using errcode = '42501'; end if;
  return new;
end $$;

-- nobody types an internal method as a "reversal": a credit or deposit already applied to an invoice is undone with Undo (migration_centre_credit_undo.sql); a credit note cannot give it back
create or replace function public.centre_internal_method_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.kind = 'reversal' and new.method in ('family_credit', 'deposit') then
    raise exception 'NOT_ALLOWED: credit or deposit that was applied to an invoice can''t be reversed; issue a credit note on the invoice instead (any excess goes back to the family credit)' using errcode = '42501';
  end if;
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['centre_refunds', 'centre_refund_events'] loop
    execute format('drop trigger if exists centre_money_org_guard on public.%I', t);
    execute format('create trigger centre_money_org_guard before insert on public.%I for each row execute function public.centre_money_org_guard()', t);
    execute format('drop trigger if exists audit_row on public.%I', t);
    execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function public.centre_money_audit()', t);
  end loop;
end $$;
drop trigger if exists centre_refund_guard on public.centre_refunds;
create trigger centre_refund_guard before insert or update or delete on public.centre_refunds for each row execute function public.centre_refund_guard();
drop trigger if exists centre_refund_event_guard on public.centre_refund_events;
create trigger centre_refund_event_guard before insert or update or delete on public.centre_refund_events for each row execute function public.centre_refund_event_guard();
drop trigger if exists centre_internal_method_guard on public.centre_payments;
create trigger centre_internal_method_guard before insert on public.centre_payments for each row execute function public.centre_internal_method_guard();

alter table public.centre_refunds enable row level security;
alter table public.centre_refund_events enable row level security;
drop policy if exists money_read on public.centre_refunds;
create policy money_read on public.centre_refunds for select
  using ((org_can(org_id, 'record_payments') or org_can(org_id, 'issue_invoices') or org_can(org_id, 'view_revenue')) and not org_is_solo(org_id));
drop policy if exists money_read on public.centre_refund_events;
create policy money_read on public.centre_refund_events for select
  using ((org_can(org_id, 'record_payments') or org_can(org_id, 'issue_invoices') or org_can(org_id, 'view_revenue')) and not org_is_solo(org_id));
revoke all on public.centre_refunds, public.centre_refund_events from anon, authenticated;
grant select on public.centre_refunds, public.centre_refund_events to authenticated;

-- ---------------------------------------------------------------------------------------------------
-- 3. helpers (internal)
-- ---------------------------------------------------------------------------------------------------
-- who and when. p_kind: 'deposit' (owner / issue_invoices) · 'family_credit' (owner / record_payments) · 'view' (any money reader). Returns the centre's own "today".
create or replace function public.centre_refund_gate(p_org uuid, p_kind text) returns date
language plpgsql stable security definer set search_path = public as $$
declare tz text; ok boolean;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select o.timezone into tz from organisations o where o.id = p_org and o.kind = 'centre';
  if tz is null or not exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active' and m.role in ('owner', 'staff')) then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  ok := case p_kind when 'view' then org_can(p_org, 'record_payments') or org_can(p_org, 'issue_invoices') or org_can(p_org, 'view_revenue')
                    when 'deposit' then org_can(p_org, 'issue_invoices')
                    else org_can(p_org, 'record_payments') end;
  if not ok then
    raise exception 'NOT_ALLOWED: your account can''t % at this centre', case p_kind when 'view' then 'see refunds'
      when 'deposit' then 'refund or keep a deposit (the owner or a staff member who issues invoices can)' else 'refund family credit (the owner or a staff member who records payments can)' end using errcode = '42501';
  end if;
  return (now() at time zone tz)::date;
end $$;

-- may the caller approve? (the setting is read by the caller as of today)
create or replace function public.centre_refund_can_approve(p_org uuid, p_kind text, p_requested_by uuid, p_rule text) returns boolean
language sql stable security definer set search_path = public as $$
  select case coalesce(p_rule, 'owner')
    when 'staff'     then org_can(p_org, case p_kind when 'deposit' then 'issue_invoices' else 'record_payments' end)
    when 'four_eyes' then org_can(p_org, case p_kind when 'deposit' then 'issue_invoices' else 'record_payments' end) and auth.uid() is distinct from p_requested_by
    else org_can(p_org, 'owner') end
$$;

create or replace function public.centre_refund_rule(p_org uuid, p_today date) returns text
language sql stable security definer set search_path = public as $$
  select case coalesce(org_settings_on(p_org, p_today)#>>'{billing,deposit,refund_approved_by}', 'owner') when 'staff' then 'staff' when 'four_eyes' then 'four_eyes' else 'owner' end
$$;

create or replace function public.centre_refund_state(p_refund uuid) returns text
language sql security definer set search_path = public as $$
  select case when exists (select 1 from centre_refund_events where refund_id = p_refund and kind = 'paid') then 'paid'
              when exists (select 1 from centre_refund_events where refund_id = p_refund and kind = 'cancelled') then 'cancelled'
              when exists (select 1 from centre_refund_events where refund_id = p_refund and kind = 'approved') then 'approved'
              else 'requested' end
$$;

-- money asked for in refunds that are not finished (so nobody can ask for it twice)
create or replace function public.centre_deposit_reserved(p_org uuid, p_student uuid) returns bigint
language sql security definer set search_path = public as $$
  select coalesce(sum(r.refund_cents + r.forfeit_cents + r.set_off_cents), 0)::bigint from centre_refunds r
   where r.org_id = p_org and r.kind = 'deposit' and r.student_id = p_student and centre_refund_state(r.id) in ('requested', 'approved')
$$;
create or replace function public.centre_credit_reserved(p_org uuid, p_household uuid) returns bigint
language sql security definer set search_path = public as $$
  select coalesce(sum(r.refund_cents), 0)::bigint from centre_refunds r
   where r.org_id = p_org and r.kind = 'family_credit' and r.household_id = p_household and centre_refund_state(r.id) in ('requested', 'approved')
$$;
create or replace function public.centre_deposit_held_cents(p_org uuid, p_student uuid) returns bigint
language sql security definer set search_path = public as $$
  select coalesce(sum(cents) filter (where kind <> 'waived'), 0)::bigint from centre_deposit_ledger where org_id = p_org and student_id = p_student
$$;

create or replace function public.centre_person_name(p_org uuid, p_user uuid) returns text
language sql stable security definer set search_path = public as $$
  select coalesce((select m.display_name from memberships m where m.org_id = p_org and m.user_id = p_user limit 1), case when p_user is null then null else 'Former staff member' end)
$$;

-- a reference may say "DBS ending 6789" but never carry a whole account or PayNow number (PDPA)
create or replace function public.centre_clean_reference(p_ref text) returns text
language plpgsql immutable set search_path = public as $$
declare r text := nullif(btrim(coalesce(p_ref, '')), '');
begin
  if r is null then return null; end if;
  if length(r) > 120 then raise exception 'TOO_LONG: keep the reference under 120 characters' using errcode = 'P0001'; end if;
  if r ~ '\d{8,}' then raise exception 'BAD_VALUE: don''t type a full bank account or PayNow number here, only the last 4 digits (for example “DBS ending 6789”)' using errcode = 'P0001'; end if;
  return r;
end $$;

-- the GST share of an amount of a TAXABLE deposit, from the rules frozen on the deposit invoice (never more than was charged)
create or replace function public.centre_deposit_gst_share(p_deposit uuid, p_org uuid, p_cents bigint) returns bigint
language plpgsql stable security definer set search_path = public as $$
declare i centre_invoices; d centre_deposits;
begin
  select * into d from centre_deposits where id = p_deposit and org_id = p_org;
  if d.id is null or not d.taxable or d.invoice_id is null or p_cents <= 0 then return 0; end if;
  select * into i from centre_invoices where id = d.invoice_id and org_id = p_org;
  if i.id is null or not coalesce(i.gst_registered, false) or coalesce(i.gst_rate_bp, 0) <= 0 then return 0; end if;
  return greatest(p_cents - centre_div_round(p_cents * 10000, 10000 + i.gst_rate_bp), 0);
end $$;

-- put money that is ALREADY HELD onto the family's open invoices, oldest first (issue date, then number). Writes one internal payment (method 'family_credit'
-- or 'deposit') for what was really allocated and its allocations. Never touches a deposit invoice or a credit note. p_student narrows it to one student's invoices.
-- Returns {payment_id, allocated_cents, allocated:[{invoice_id, number, cents}]}; allocated_cents may be less than asked (or 0: nothing is written).
create or replace function public.centre_allocate_held(p_org uuid, p_household uuid, p_method text, p_cents bigint, p_invoice_ids uuid[], p_student uuid, p_today date, p_ref text)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare r record; remaining bigint := p_cents; take bigint; pid uuid := gen_random_uuid(); total bigint := 0; picks jsonb := '[]'::jsonb; a jsonb;
begin
  for r in
    select i.id, i.number_text, b.balance_cents
      from centre_invoices i, lateral centre_balance_rows(p_org, array[i.id]) b
     where i.org_id = p_org and i.status = 'issued' and i.kind not in ('credit_note', 'deposit') and b.balance_cents > 0
       and (case when p_student is not null then i.student_id = p_student
                 else (i.household_id = p_household or (i.household_id is null and i.student_id in (select s.id from students s where s.household_id = p_household and s.org_id = p_org))) end)
       and (p_invoice_ids is null or i.id = any(p_invoice_ids))
     order by i.issue_date, i.number_seq
  loop
    exit when remaining <= 0;
    take := least(remaining, r.balance_cents);
    picks := picks || jsonb_build_object('invoice_id', r.id, 'number', r.number_text, 'cents', take);
    remaining := remaining - take; total := total + take;
  end loop;
  if total <= 0 then return jsonb_build_object('payment_id', null, 'allocated_cents', 0, 'allocated', '[]'::jsonb); end if;
  insert into centre_payments(id, org_id, kind, household_id, method, amount_cents, received_on, reference)
  values (pid, p_org, 'payment', p_household, p_method, total, p_today, p_ref);
  for a in select * from jsonb_array_elements(picks) loop
    insert into centre_payment_allocations(org_id, payment_id, invoice_id, cents) values (p_org, pid, (a->>'invoice_id')::uuid, (a->>'cents')::bigint);
  end loop;
  return jsonb_build_object('payment_id', pid, 'allocated_cents', total, 'allocated', picks);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 4. one refund as the screens read it (internal; every caller has already passed a gate)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_refund_json(p_refund uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare r centre_refunds; st text; tz text; today date; rule text; perm text; appr boolean; own boolean; res jsonb;
begin
  select * into r from centre_refunds where id = p_refund;
  if r.id is null then return null; end if;
  st := centre_refund_state(r.id);
  select o.timezone into tz from organisations o where o.id = r.org_id; today := (now() at time zone coalesce(tz, 'Asia/Singapore'))::date;
  rule := centre_refund_rule(r.org_id, today);
  perm := case r.kind when 'deposit' then 'issue_invoices' else 'record_payments' end;
  own := org_can(r.org_id, 'owner');
  appr := st = 'requested' and centre_refund_can_approve(r.org_id, r.kind, r.requested_by, rule);
  res := jsonb_build_object('id', r.id, 'kind', r.kind, 'state', st, 'student_id', r.student_id, 'household_id', r.household_id,
    'student_name', (select s.name from students s where s.id = r.student_id and s.org_id = r.org_id),
    'household_name', (select h.name from households h where h.id = coalesce(r.household_id, (select s.household_id from students s where s.id = r.student_id and s.org_id = r.org_id)) and h.org_id = r.org_id),
    'refund_cents', r.refund_cents, 'forfeit_cents', r.forfeit_cents, 'set_off_cents', r.set_off_cents, 'held_cents', r.held_cents,
    'taxable', r.taxable, 'gst_cents', r.gst_cents, 'release_rule', r.release_rule, 'approver_rule', rule,
    'notice_days', r.notice_days, 'notice_given_on', r.notice_given_on, 'lesson_end', r.lesson_end,
    'payee', r.payer_name, 'reason', r.reason, 'requested_by_name', centre_person_name(r.org_id, r.requested_by), 'requested_on', r.requested_on,
    'can_approve', appr, 'can_pay', st = 'approved' and org_can(r.org_id, perm),
    'can_cancel', st in ('requested', 'approved') and (own or r.requested_by = auth.uid() or (rule <> 'owner' and org_can(r.org_id, perm))),
    'events', coalesce((select jsonb_agg(jsonb_build_object('kind', e.kind, 'on', e.event_on, 'by', centre_person_name(r.org_id, e.actor), 'method', e.method,
        'reference', e.reference, 'reason', e.reason, 'note', e.note, 'set_off_cents', e.set_off_cents) order by e.created_at, case e.kind when 'approved' then 1 when 'paid' then 2 else 3 end, e.id)
        from centre_refund_events e where e.refund_id = r.id and e.org_id = r.org_id), '[]'::jsonb));
  return res;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 5. FAMILY CREDIT: what the family holds, what is already being refunded, what is open to apply it to
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_family_credit_status(p_org uuid, p_household uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := centre_refund_gate(p_org, 'view'); bal bigint; res bigint; hn text;
begin
  select h.name into hn from households h where h.id = p_household and h.org_id = p_org;
  if hn is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  bal := centre_credit_balance(p_org, p_household); res := centre_credit_reserved(p_org, p_household);
  return jsonb_build_object('today', today, 'household_id', p_household, 'household_name', hn, 'balance_cents', bal, 'reserved_cents', res, 'available_cents', greatest(bal - res, 0),
    'handling', centre_overpay_mode(org_settings_on(p_org, today)), 'approver_rule', centre_refund_rule(p_org, today),
    'open_invoices', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'number', i.number_text, 'balance_cents', b.balance_cents, 'due_date', i.due_date, 'student_id', i.student_id) order by i.issue_date, i.number_seq)
        from centre_invoices i, lateral centre_balance_rows(p_org, array[i.id]) b
       where i.org_id = p_org and i.status = 'issued' and i.kind not in ('credit_note', 'deposit') and b.balance_cents > 0
         and (i.household_id = p_household or (i.household_id is null and i.student_id in (select s.id from students s where s.household_id = p_household and s.org_id = p_org)))), '[]'::jsonb),
    'refunds', coalesce((select jsonb_agg(centre_refund_json(r.id) order by r.created_at desc, r.id) from centre_refunds r
        where r.org_id = p_org and r.kind = 'family_credit' and r.household_id = p_household), '[]'::jsonb));
end $$;

-- APPLY: use the family's credit to pay their open invoice(s), so no cash needs to be refunded. Oldest invoice first unless some are chosen;
-- the whole credit (or the amount given) up to what the invoices still owe. A repeated request key does nothing.
create or replace function public.centre_apply_family_credit(p_org uuid, p_household uuid, p_invoice_ids uuid[] default null, p_cents bigint default null, p_request_key text default null)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_refund_gate(p_org, 'family_credit'); key text := nullif(btrim(coalesce(p_request_key, '')), ''); prior record; avail bigint; take bigint; al jsonb; got bigint;
  ids uuid[]; bad int;
begin
  if not exists (select 1 from households h where h.id = p_household and h.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if key is not null and length(key) > 80 then raise exception 'BAD_VALUE: that request key is too long' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_household::text, 4));
  if key is not null then
    select * into prior from centre_family_credit where org_id = p_org and request_key = key;
    if prior.id is not null then
      if prior.household_id is distinct from p_household then raise exception 'BAD_VALUE: that request key was used for something else' using errcode = 'P0001'; end if;
      return jsonb_build_object('already', true, 'applied_cents', -prior.cents, 'credit_balance_cents', centre_credit_balance(p_org, p_household), 'payment_id', prior.payment_id);
    end if;
  end if;
  avail := centre_credit_balance(p_org, p_household) - centre_credit_reserved(p_org, p_household);
  if avail <= 0 then raise exception 'CREDIT_SHORT: this family has no credit left to apply (credit already being refunded can''t be used too)' using errcode = '42501'; end if;
  if p_cents is not null and p_cents <= 0 then raise exception 'BAD_VALUE: the amount must be more than S$0.00' using errcode = 'P0001'; end if;
  take := coalesce(p_cents, avail);
  if take > avail then raise exception 'CREDIT_SHORT: this family has only % of credit available to apply', centre_fmt_money(avail) using errcode = '42501'; end if;
  if coalesce(cardinality(p_invoice_ids), 0) > 0 then
    select array(select distinct x from unnest(p_invoice_ids) x) into ids;
    select count(*) into bad from unnest(ids) x where not exists (
      select 1 from centre_invoices i, lateral centre_balance_rows(p_org, array[i.id]) b
       where i.id = x and i.org_id = p_org and i.status = 'issued' and i.kind not in ('credit_note', 'deposit') and b.balance_cents > 0
         and (i.household_id = p_household or (i.household_id is null and i.student_id in (select s.id from students s where s.household_id = p_household and s.org_id = p_org))));
    if bad > 0 then raise exception 'NOT_ALLOWED: credit can only pay an open invoice of this family (not a deposit invoice or one that is already paid)' using errcode = '42501'; end if;
  end if;
  al := centre_allocate_held(p_org, p_household, 'family_credit', take, ids, null, today, 'Family credit applied');
  got := (al->>'allocated_cents')::bigint;
  if got <= 0 then raise exception 'NOTHING_TO_APPLY: this family has no open invoice for the credit to pay' using errcode = 'P0001'; end if;
  insert into centre_family_credit(org_id, household_id, kind, cents, payment_id, request_key, reason)
  values (p_org, p_household, 'applied', -got, (al->>'payment_id')::uuid, key,
          'Applied to ' || (select string_agg(a->>'number', ', ') from jsonb_array_elements(al->'allocated') a));
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'centre_credit_apply', 'centre_family_credit', p_household::text, null,
          jsonb_build_object('applied_cents', got, 'invoices', jsonb_array_length(al->'allocated'), 'credit_after_cents', centre_credit_balance(p_org, p_household)));
  return jsonb_build_object('already', false, 'applied_cents', got, 'allocated', al->'allocated', 'payment_id', al->>'payment_id', 'credit_balance_cents', centre_credit_balance(p_org, p_household));
end $$;

-- ASK to refund family credit (it is paid out only after approval; the amount is reserved at once)
create or replace function public.centre_credit_refund_request(p_org uuid, p_household uuid, p_cents bigint, p_payee text, p_reason text, p_request_key text default null)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_refund_gate(p_org, 'family_credit'); key text := nullif(btrim(coalesce(p_request_key, '')), ''); why text := nullif(btrim(coalesce(p_reason, '')), '');
  payee text := nullif(btrim(coalesce(p_payee, '')), ''); prior centre_refunds; bal bigint; res bigint; rid uuid := gen_random_uuid(); s jsonb := org_settings_on(p_org, today);
begin
  if not exists (select 1 from households h where h.id = p_household and h.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_cents is null or p_cents <= 0 then raise exception 'BAD_VALUE: the refund must be more than S$0.00' using errcode = 'P0001'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why this is being refunded' using errcode = 'P0001'; end if;
  if length(why) > 300 or length(coalesce(payee, '')) > 120 or length(coalesce(key, '')) > 80 then raise exception 'TOO_LONG: keep the reason under 300 and the name under 120 characters' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_household::text, 4));
  if key is not null then
    select * into prior from centre_refunds where org_id = p_org and request_key = key;
    if prior.id is not null then
      if prior.kind <> 'family_credit' or prior.household_id is distinct from p_household or prior.refund_cents <> p_cents then raise exception 'BAD_VALUE: that request key was used for something else' using errcode = 'P0001'; end if;
      return centre_refund_json(prior.id) || jsonb_build_object('already', true);
    end if;
  end if;
  bal := centre_credit_balance(p_org, p_household); res := centre_credit_reserved(p_org, p_household);
  if p_cents > bal - res then
    raise exception 'CREDIT_SHORT: this family has only % available to refund (% is held, % is already being refunded)', centre_fmt_money(greatest(bal - res, 0)), centre_fmt_money(bal), centre_fmt_money(res) using errcode = '42501';
  end if;
  insert into centre_refunds(id, org_id, kind, household_id, refund_cents, held_cents, release_rule, payer_name, reason, request_key, requested_on)
  values (rid, p_org, 'family_credit', p_household, p_cents, bal, centre_overpay_mode(s), payee, why, key, today);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'centre_refund_request', 'centre_refunds', rid::text, null, jsonb_build_object('kind', 'family_credit', 'refund_cents', p_cents, 'credit_held_cents', bal));
  return centre_refund_json(rid) || jsonb_build_object('already', false);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 6. DEPOSIT RELEASE: what the centre's rules suggest when a student has left (read-only; nothing is written)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_deposit_release_proposal(p_student uuid, p_notice_given_on date default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare org uuid; today date; st students; d centre_deposits; s jsonb; rule text; rel text; notice_days int; held bigint; resv bigint; avail bigint; endd date; hh uuid;
  grp text; reasons text[] := '{}'; n int; short boolean; unpaid bigint := 0; unpaid_list jsonb := '[]'::jsonb; sug_f bigint := 0; sug_s bigint := 0; sug_r bigint := 0;
  open_id uuid; state text; note text; scope_student uuid;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into st from students where id = p_student;
  if st.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  org := st.org_id; today := centre_refund_gate(org, 'view');
  s := org_settings_on(org, today);
  rule := centre_refund_rule(org, today);
  rel := coalesce(s#>>'{billing,deposit,release}', 'admin_decides');
  notice_days := coalesce((s#>>'{billing,deposit,forfeit_notice_days}')::int, 0);
  grp := coalesce(s#>>'{invoicing,grouping}', 'family');
  hh := st.household_id; endd := st.end_date;
  select * into d from centre_deposits where org_id = org and student_id = p_student;
  if d.id is null then return jsonb_build_object('state', 'no_deposit', 'student_id', p_student, 'name', st.name, 'waiting', '[]'::jsonb, 'today', today); end if;
  if p_notice_given_on is not null and p_notice_given_on > today then raise exception 'BAD_VALUE: the day notice was given can''t be in the future' using errcode = 'P0001'; end if;
  held := centre_deposit_held_cents(org, p_student); resv := centre_deposit_reserved(org, p_student); avail := greatest(held - resv, 0);
  select r.id into open_id from centre_refunds r where r.org_id = org and r.kind = 'deposit' and r.student_id = p_student and centre_refund_state(r.id) in ('requested', 'approved') limit 1;
  scope_student := case when grp = 'student' then p_student end;

  -- the final invoice: the proposal waits until it is issued
  if endd is null then reasons := array_append(reasons, 'The student hasn''t been ended yet. Set the day lessons run until in their profile.');
  elsif endd >= today then reasons := array_append(reasons, 'Lessons run until ' || to_char(endd, 'DD Mon YYYY') || '. A refund can be asked for after that day.'); end if;
  if endd is not null then
    select count(*) into n from centre_invoices i where i.org_id = org and i.status = 'draft' and i.kind in ('lesson', 'late_fee', 'opening')
       and (i.student_id = p_student or (grp <> 'student' and i.household_id = hh));
    if n > 0 then reasons := array_append(reasons, 'An invoice for this family is still a draft. Issue it first.'); end if;
    select count(*) into n from lessons l where l.org_id = org and l.student_id = p_student and l.lesson_date <= endd and coalesce(l.trial, false) = false
       and ((l.status = 'done' and coalesce(l.amount, 0) > 0) or (l.status = 'cancelled' and coalesce(l.compensation, 0) > 0))
       and not exists (select 1 from centre_invoice_lines x join centre_invoices i on i.id = x.invoice_id and i.org_id = x.org_id where x.lesson_id = l.id and i.status <> 'void');
    if n > 0 then reasons := array_append(reasons, n || case when n = 1 then ' lesson hasn''t' else ' lessons haven''t' end || ' been invoiced yet. Run the invoice run first.'); end if;
    select count(*) into n from lessons l where l.org_id = org and l.student_id = p_student and l.lesson_date <= endd and l.status = 'cancelled' and l.compensation is null;
    if n > 0 then reasons := array_append(reasons, 'A cancelled lesson is still waiting for its charge.'); end if;
  end if;

  -- what the family still owes (the deposit may be kept against it)
  select coalesce(sum(b.balance_cents), 0)::bigint,
         coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'number', i.number_text, 'balance_cents', b.balance_cents) order by i.issue_date, i.number_seq), '[]'::jsonb)
    into unpaid, unpaid_list
    from centre_invoices i, lateral centre_balance_rows(org, array[i.id]) b
   where i.org_id = org and i.status = 'issued' and i.kind not in ('credit_note', 'deposit') and b.balance_cents > 0
     and (case when scope_student is not null then i.student_id = scope_student
               else (i.household_id = hh or (i.household_id is null and i.student_id in (select s2.id from students s2 where s2.household_id = hh and s2.org_id = org))) end);

  short := case when notice_days > 0 and p_notice_given_on is not null and endd is not null then (endd - p_notice_given_on) < notice_days end;
  state := case when held <= 0 and open_id is null then 'nothing_held' when open_id is not null then 'open_refund' when cardinality(reasons) > 0 then 'waiting' when avail <= 0 then 'nothing_held' else 'ready' end;
  if rel <> 'admin_decides' then
    sug_f := case when coalesce(short, false) then avail else 0 end;
    sug_s := case when rel = 'refund_less_unpaid' and not d.taxable then least(avail - sug_f, unpaid) else 0 end;
    sug_r := avail - sug_f - sug_s;
  end if;
  note := case when d.taxable and rel = 'refund_less_unpaid' and unpaid > 0 then 'This deposit carried GST, so it can''t be kept against invoices: refund it and let the family pay the invoices.'
               when notice_days > 0 and p_notice_given_on is null then 'Type the day the family gave notice to see whether the deposit is kept.'
               when coalesce(short, false) then 'Less than ' || notice_days || ' days’ notice was given, so the centre''s rule suggests keeping the deposit. A kept deposit becomes income: ask your accountant whether GST applies.' end;
  return jsonb_build_object('today', today, 'student_id', p_student, 'name', st.name, 'household_id', hh, 'state', state, 'waiting', to_jsonb(reasons),
    'held_cents', held, 'reserved_cents', resv, 'available_cents', avail, 'taxable', d.taxable, 'unpaid_cents', unpaid, 'unpaid_invoices', unpaid_list,
    'release_rule', rel, 'approver_rule', rule, 'notice_days', notice_days, 'notice_given_on', p_notice_given_on, 'notice_needed', notice_days > 0 and p_notice_given_on is null,
    'notice_short', short, 'lesson_end', endd, 'open_refund_id', open_id, 'note', note,
    'suggest', case when rel = 'admin_decides' then null else jsonb_build_object('refund_cents', sug_r, 'forfeit_cents', sug_f, 'set_off_cents', sug_s) end,
    'can_request', state = 'ready' and org_can(org, 'issue_invoices'));
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 7. ASK to release a deposit: refund + keep (forfeit) + keep against unpaid invoices. Needs the proposal to be "ready".
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_deposit_refund_request(p_student uuid, p_refund_cents bigint, p_forfeit_cents bigint, p_set_off_cents bigint,
  p_notice_given_on date, p_payee text, p_reason text, p_request_key text default null)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; st students; d centre_deposits; pr jsonb; why text := nullif(btrim(coalesce(p_reason, '')), ''); payee text := nullif(btrim(coalesce(p_payee, '')), '');
  key text := nullif(btrim(coalesce(p_request_key, '')), ''); f bigint := coalesce(p_forfeit_cents, 0); so bigint := coalesce(p_set_off_cents, 0); rf bigint := coalesce(p_refund_cents, 0);
  prior centre_refunds; rid uuid := gen_random_uuid(); gst bigint; s jsonb;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into st from students where id = p_student;
  if st.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  org := st.org_id; today := centre_refund_gate(org, 'deposit');
  if rf < 0 or f < 0 or so < 0 then raise exception 'BAD_VALUE: amounts can''t be negative' using errcode = 'P0001'; end if;
  if rf + f + so <= 0 then raise exception 'BAD_VALUE: choose how much to refund, keep or set off' using errcode = 'P0001'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why (kept in the record)' using errcode = 'P0001'; end if;
  if length(why) > 300 or length(coalesce(payee, '')) > 120 or length(coalesce(key, '')) > 80 then raise exception 'TOO_LONG: keep the reason under 300 and the name under 120 characters' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_student::text, 6));
  if key is not null then
    select * into prior from centre_refunds where org_id = org and request_key = key;
    if prior.id is not null then
      if prior.kind <> 'deposit' or prior.student_id is distinct from p_student or prior.refund_cents <> rf or prior.forfeit_cents <> f or prior.set_off_cents <> so then
        raise exception 'BAD_VALUE: that request key was used for something else' using errcode = 'P0001'; end if;
      return centre_refund_json(prior.id) || jsonb_build_object('already', true);
    end if;
  end if;
  pr := centre_deposit_release_proposal(p_student, p_notice_given_on);
  if pr->>'state' = 'no_deposit' then raise exception 'NO_DEPOSIT: this student has no deposit' using errcode = 'P0001'; end if;
  if pr->>'state' = 'open_refund' then
    -- a second press of the same request (no key) must do nothing twice: answer with the refund that is already open when it is the same
    select * into prior from centre_refunds where id = (pr->>'open_refund_id')::uuid;
    if prior.refund_cents = rf and prior.forfeit_cents = f and prior.set_off_cents = so then return centre_refund_json(prior.id) || jsonb_build_object('already', true); end if;
    raise exception 'OPEN_REFUND: a refund for this deposit is already in progress; finish or cancel it first' using errcode = 'P0001';
  end if;
  if pr->>'state' = 'nothing_held' then raise exception 'DEPOSIT_SHORT: nothing is held for this student, so there is nothing to refund' using errcode = '23514'; end if;
  if pr->>'state' = 'waiting' then raise exception 'NOT_READY: %', (pr->'waiting'->>0) using errcode = '42501'; end if;
  if rf + f + so > (pr->>'available_cents')::bigint then
    raise exception 'DEPOSIT_SHORT: only % is held and free to release (you asked for %)', centre_fmt_money((pr->>'available_cents')::bigint), centre_fmt_money(rf + f + so) using errcode = '23514'; end if;
  select * into d from centre_deposits where org_id = org and student_id = p_student;
  if so > 0 and d.taxable then raise exception 'NOT_ALLOWED: this deposit carried GST, so it can''t be kept against invoices. Refund it and let the family pay the invoices.' using errcode = '42501'; end if;
  if so > (pr->>'unpaid_cents')::bigint then
    raise exception 'NOT_ALLOWED: the family owes only % on open invoices, so you can''t keep % against them', centre_fmt_money((pr->>'unpaid_cents')::bigint), centre_fmt_money(so) using errcode = '42501'; end if;
  s := org_settings_on(org, today);
  gst := centre_deposit_gst_share(d.id, org, rf);
  insert into centre_refunds(id, org_id, kind, student_id, household_id, deposit_id, refund_cents, forfeit_cents, set_off_cents, held_cents, taxable, gst_cents, release_rule,
                             notice_days, notice_given_on, lesson_end, payer_name, reason, request_key, requested_on)
  values (rid, org, 'deposit', p_student, st.household_id, d.id, rf, f, so, (pr->>'held_cents')::bigint, d.taxable, gst, pr->>'release_rule',
          nullif((pr->>'notice_days')::int, 0), p_notice_given_on, st.end_date, payee, why, key, today);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'centre_refund_request', 'centre_refunds', rid::text, null,
          jsonb_build_object('kind', 'deposit', 'refund_cents', rf, 'forfeit_cents', f, 'set_off_cents', so, 'held_cents', (pr->>'held_cents')::bigint, 'gst_cents', gst));
  return centre_refund_json(rid) || jsonb_build_object('already', false);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 8. APPROVE · PAY · CANCEL
-- ---------------------------------------------------------------------------------------------------
-- the moment money moves on the ledgers: called once, when the refund is paid (or approved, when there is no cash to pay out)
create or replace function public.centre_refund_settle(r centre_refunds, p_today date, p_method text, p_paid_on date, p_reference text, p_note text)
returns bigint language plpgsql security definer set search_path = public, pg_temp as $$
declare d centre_deposits; hh uuid; al jsonb; got bigint := 0; nums text;
begin
  if r.kind = 'family_credit' then
    insert into centre_family_credit(org_id, household_id, kind, cents, method, reference, reason, refund_id)
    values (r.org_id, r.household_id, 'refund', -r.refund_cents, p_method, p_reference, r.reason, r.id);
  else
    perform pg_advisory_xact_lock(hashtextextended(r.student_id::text, 6));
    select * into d from centre_deposits where id = r.deposit_id and org_id = r.org_id;
    select s.household_id into hh from students s where s.id = r.student_id and s.org_id = r.org_id;
    if r.set_off_cents > 0 and hh is not null then
      perform pg_advisory_xact_lock(hashtextextended(hh::text, 4));
      al := centre_allocate_held(r.org_id, hh, 'deposit', r.set_off_cents, null,
                                 case when coalesce(org_settings_on(r.org_id, p_today)#>>'{invoicing,grouping}', 'family') = 'student' then r.student_id end, p_today, 'Deposit kept against invoices');
      got := (al->>'allocated_cents')::bigint;
      if got > 0 then
        select string_agg(a->>'number', ', ') into nums from jsonb_array_elements(al->'allocated') a;
        insert into centre_deposit_ledger(org_id, student_id, deposit_id, kind, cents, taxable, payment_id, entry_date, reason, refund_id)
        values (r.org_id, r.student_id, d.id, 'applied', -got, d.taxable, (al->>'payment_id')::uuid, p_today, 'Kept against ' || nums, r.id);
      end if;
    end if;
    if r.forfeit_cents > 0 then
      insert into centre_deposit_ledger(org_id, student_id, deposit_id, kind, cents, taxable, entry_date, reason, refund_id)
      values (r.org_id, r.student_id, d.id, 'forfeited', -r.forfeit_cents, d.taxable, p_today, 'Kept by the centre: ' || r.reason, r.id);
    end if;
    if r.refund_cents > 0 then
      insert into centre_deposit_ledger(org_id, student_id, deposit_id, kind, cents, taxable, entry_date, reason, refund_id)
      values (r.org_id, r.student_id, d.id, 'refunded', -r.refund_cents, d.taxable, coalesce(p_paid_on, p_today), 'Refunded to the family', r.id);
    end if;
  end if;
  insert into centre_refund_events(org_id, refund_id, kind, event_on, method, reference, note, set_off_cents)
  values (r.org_id, r.id, 'paid', coalesce(p_paid_on, p_today), p_method, p_reference, p_note, case when r.kind = 'deposit' then got end);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (r.org_id, auth.uid(), 'centre_refund_paid', 'centre_refunds', r.id::text, null,
          jsonb_build_object('kind', r.kind, 'refund_cents', r.refund_cents, 'forfeit_cents', r.forfeit_cents, 'set_off_asked_cents', r.set_off_cents, 'set_off_done_cents', got, 'gst_cents', r.gst_cents));
  return got;
end $$;

create or replace function public.centre_refund_approve(p_refund uuid, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare r centre_refunds; today date; st text; rule text; note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into r from centre_refunds where id = p_refund;
  if r.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := centre_refund_gate(r.org_id, r.kind);
  if length(coalesce(note, '')) > 300 then raise exception 'TOO_LONG: keep the note under 300 characters' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_refund::text, 7));
  st := centre_refund_state(p_refund);
  if st in ('approved', 'paid') then return centre_refund_json(p_refund) || jsonb_build_object('already', true); end if;
  if st = 'cancelled' then raise exception 'ALREADY_CANCELLED: that refund was cancelled' using errcode = 'P0001'; end if;
  rule := centre_refund_rule(r.org_id, today);
  if not centre_refund_can_approve(r.org_id, r.kind, r.requested_by, rule) then
    raise exception 'NOT_ALLOWED: %', case rule
      when 'owner' then 'this centre lets only the owner approve refunds (see Centre settings)'
      when 'four_eyes' then case when auth.uid() is not distinct from r.requested_by then 'a refund has to be approved by someone other than the person who asked for it'
                                 else 'your account can''t approve this kind of refund' end
      else 'your account can''t approve this kind of refund' end using errcode = '42501';
  end if;
  insert into centre_refund_events(org_id, refund_id, kind, event_on, note) values (r.org_id, r.id, 'approved', today, note);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (r.org_id, auth.uid(), 'centre_refund_approve', 'centre_refunds', r.id::text, null, jsonb_build_object('kind', r.kind, 'rule', rule, 'refund_cents', r.refund_cents));
  if r.refund_cents = 0 then perform centre_refund_settle(r, today, null, today, null, null); end if;     -- nothing to pay out: keeping a deposit is complete on approval
  return centre_refund_json(p_refund) || jsonb_build_object('already', false);
end $$;

create or replace function public.centre_refund_pay(p_refund uuid, p_method text, p_paid_on date, p_reference text default null, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare r centre_refunds; today date; st text; ref text; note text := nullif(btrim(coalesce(p_note, '')), ''); got bigint;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into r from centre_refunds where id = p_refund;
  if r.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := centre_refund_gate(r.org_id, r.kind);
  perform pg_advisory_xact_lock(hashtextextended(p_refund::text, 7));
  st := centre_refund_state(p_refund);
  if st = 'paid' then return centre_refund_json(p_refund) || jsonb_build_object('already', true); end if;
  if st = 'cancelled' then raise exception 'ALREADY_CANCELLED: that refund was cancelled' using errcode = 'P0001'; end if;
  if st <> 'approved' then raise exception 'NOT_APPROVED: the refund has to be approved before it is marked paid' using errcode = '42501'; end if;
  if p_method is null or p_method not in ('manual_paynow', 'bank', 'cash', 'cheque', 'other') then raise exception 'BAD_VALUE: choose how it was paid back' using errcode = 'P0001'; end if;
  if p_paid_on is null then raise exception 'BAD_VALUE: say the day it was paid' using errcode = 'P0001'; end if;
  if p_paid_on > today then raise exception 'BAD_VALUE: the day it was paid can''t be in the future' using errcode = 'P0001'; end if;
  if p_paid_on < r.requested_on then raise exception 'BAD_VALUE: it can''t have been paid before it was asked for (%).', to_char(r.requested_on, 'DD Mon YYYY') using errcode = 'P0001'; end if;
  if length(coalesce(note, '')) > 300 then raise exception 'TOO_LONG: keep the note under 300 characters' using errcode = 'P0001'; end if;
  ref := centre_clean_reference(p_reference);
  got := centre_refund_settle(r, today, p_method, p_paid_on, ref, note);
  return centre_refund_json(p_refund) || jsonb_build_object('already', false, 'set_off_done_cents', got);
end $$;

create or replace function public.centre_refund_cancel(p_refund uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare r centre_refunds; today date; st text; why text := nullif(btrim(coalesce(p_reason, '')), ''); rule text; perm text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into r from centre_refunds where id = p_refund;
  if r.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := centre_refund_gate(r.org_id, r.kind);
  perform pg_advisory_xact_lock(hashtextextended(p_refund::text, 7));
  st := centre_refund_state(p_refund);
  if st = 'cancelled' then return centre_refund_json(p_refund) || jsonb_build_object('already', true); end if;
  if st = 'paid' then raise exception 'ALREADY_PAID: that refund was already paid, so it can''t be cancelled' using errcode = 'P0001'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why this refund is being cancelled' using errcode = 'P0001'; end if;
  if length(why) > 300 then raise exception 'TOO_LONG: keep the reason under 300 characters' using errcode = 'P0001'; end if;
  rule := centre_refund_rule(r.org_id, today);
  perm := case r.kind when 'deposit' then 'issue_invoices' else 'record_payments' end;
  if not (org_can(r.org_id, 'owner') or r.requested_by = auth.uid() or (rule <> 'owner' and org_can(r.org_id, perm))) then
    raise exception 'NOT_ALLOWED: only the person who asked, an approver or the owner can cancel this refund' using errcode = '42501'; end if;
  insert into centre_refund_events(org_id, refund_id, kind, event_on, reason) values (r.org_id, r.id, 'cancelled', today, why);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (r.org_id, auth.uid(), 'centre_refund_cancel', 'centre_refunds', r.id::text, null, jsonb_build_object('kind', r.kind, 'refund_cents', r.refund_cents));
  return centre_refund_json(p_refund) || jsonb_build_object('already', false);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 9. WHAT THE SCREENS READ: the list and one refund's statement
-- ---------------------------------------------------------------------------------------------------
-- p_state: null = everything, 'open' = requested or approved, 'closed' = paid or cancelled. Open ones first, then newest.
create or replace function public.centre_refund_list(p_org uuid, p_state text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := centre_refund_gate(p_org, 'view');
begin
  if p_state is not null and p_state not in ('open', 'closed') then raise exception 'BAD_VALUE: unknown filter' using errcode = 'P0001'; end if;
  return jsonb_build_object('today', today, 'approver_rule', centre_refund_rule(p_org, today),
    'rows', coalesce((select jsonb_agg(x.j order by x.open desc, x.created_at desc, x.id)
      from (select centre_refund_json(r.id) as j, centre_refund_state(r.id) in ('requested', 'approved') as open, r.created_at, r.id
              from centre_refunds r where r.org_id = p_org) x
     where p_state is null or (p_state = 'open' and x.open) or (p_state = 'closed' and not x.open)), '[]'::jsonb));
end $$;

-- the trail of one refund: what was asked and why, who approved, who paid and how, and what the ledgers did
create or replace function public.centre_refund_statement(p_refund uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare r centre_refunds; nm text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into r from centre_refunds where id = p_refund;
  if r.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform centre_refund_gate(r.org_id, 'view');
  select o.trading_name into nm from organisations o where o.id = r.org_id;
  return centre_refund_json(p_refund) || jsonb_build_object('centre', nm);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 10. the old owner-only "refund family credit" now goes through the same request → approve → pay steps (so no setting can be bypassed)
--     Same name and arguments as S3. Owner only, as before. If the centre's rule needs somebody else to approve, the refund waits as "requested".
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_refund_family_credit(p_org uuid, p_household uuid, p_cents bigint, p_method text, p_reference text, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_money_gate(p_org, 'owner'); ref text; j jsonb; rid uuid;
begin
  if p_method is null or p_method not in ('manual_paynow', 'bank', 'cash', 'cheque', 'other') then raise exception 'BAD_VALUE: choose how it was paid back' using errcode = 'P0001'; end if;
  ref := centre_clean_reference(p_reference);
  j := centre_credit_refund_request(p_org, p_household, p_cents, null, p_reason);
  rid := (j->>'id')::uuid;
  if (j->>'can_approve')::boolean then
    j := centre_refund_approve(rid);
    j := centre_refund_pay(rid, p_method, today, ref, null);
  end if;
  return jsonb_build_object('refund_id', rid, 'state', j->>'state', 'refunded_cents', case when j->>'state' = 'paid' then p_cents else 0 end,
                            'balance_cents', centre_credit_balance(p_org, p_household));
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 11. revenue totals that know about refunds (replaces the S4 function; same keys plus the refund figures)
--     received_cents leaves out credit that was merely moved onto an invoice (the cash was counted when it first came in). A deposit KEPT against an
--     invoice does count as received (it has become fees). refund_gst_cents is GST given back with refunded taxable deposits (already taken off gst_cents).
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_revenue_totals(p_org uuid, p_from date default null, p_to date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb; dep_in bigint; dep_held bigint; rf_dep bigint; rf_cred bigint; forf bigint; rf_gst bigint;
begin
  if auth.uid() is null or not exists (select 1 from organisations o where o.id = p_org and o.kind = 'centre') or not org_can(p_org, 'view_revenue') then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  select coalesce(sum(r2.refund_cents) filter (where r2.kind = 'deposit'), 0), coalesce(sum(r2.refund_cents) filter (where r2.kind = 'family_credit'), 0),
         coalesce(sum(r2.forfeit_cents), 0), coalesce(sum(r2.gst_cents), 0)
    into rf_dep, rf_cred, forf, rf_gst
    from centre_refunds r2 join centre_refund_events e on e.refund_id = r2.id and e.org_id = r2.org_id and e.kind = 'paid'
   where r2.org_id = p_org and (p_from is null or e.event_on >= p_from) and (p_to is null or e.event_on <= p_to);
  select jsonb_build_object(
    'invoiced_cents',  coalesce(sum(i.total_cents) filter (where i.kind not in ('credit_note', 'deposit')), 0),
    'gst_cents',       coalesce(sum(i.gst_cents) filter (where i.kind <> 'credit_note'), 0) - coalesce(sum(i.gst_cents) filter (where i.kind = 'credit_note'), 0) - rf_gst,
    'credited_cents',  coalesce(sum(i.total_cents) filter (where i.kind = 'credit_note' and coalesce(ci.kind, '') <> 'deposit'), 0),
    'invoices',        count(*) filter (where i.kind not in ('credit_note', 'deposit')),
    'deposits_invoiced_cents', coalesce(sum(i.total_cents) filter (where i.kind = 'deposit'), 0))
    into r from centre_invoices i left join centre_invoices ci on ci.id = i.credits_invoice_id and ci.org_id = i.org_id
   where i.org_id = p_org and i.status = 'issued' and (p_from is null or i.issue_date >= p_from) and (p_to is null or i.issue_date <= p_to);
  select coalesce(sum(a.cents), 0) into dep_in
    from centre_payment_allocations a join centre_payments p on p.id = a.payment_id and p.org_id = a.org_id
    join centre_invoices i on i.id = a.invoice_id and i.org_id = a.org_id and i.kind = 'deposit'
   where a.org_id = p_org and (p_from is null or p.received_on >= p_from) and (p_to is null or p.received_on <= p_to);
  select coalesce(sum(cents) filter (where kind <> 'waived'), 0) into dep_held from centre_deposit_ledger where org_id = p_org;
  r := r || jsonb_build_object('received_cents', coalesce((select sum(case when p.method = 'family_credit' then 0 when p.kind = 'payment' then p.amount_cents else -p.amount_cents end)
       from centre_payments p where p.org_id = p_org and (p_from is null or p.received_on >= p_from) and (p_to is null or p.received_on <= p_to)), 0) - dep_in,
       'deposits_received_cents', dep_in, 'deposits_held_cents', dep_held,
       'deposits_refunded_cents', rf_dep, 'deposits_forfeited_cents', forf, 'credit_refunded_cents', rf_cred, 'refund_gst_cents', rf_gst);
  return r;
end $$;

