-- #####################################################################################################
-- ### PART 5 of 9 — late fee proposals (approve / waive, monthly repeat)
-- ### source branch: claude/t4-s6-late-fees   file: db/migration_centre_late_fees.sql   undo: db/migration_centre_late_fees_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T4 step S6 — centre late fees: proposals a person approves or waives, recurring each month an invoice stays unpaid   undo: migration_centre_late_fees_down.sql
-- =====================================================================================================
-- Run order everywhere: org_foundation → billing → attendance → tutor_access → org_delete → function_lockdown → org_separation →
--   staff_home → staff_students → staff_attendance → staff_charges → staff_trials → staff_timetable → money_settings →
--   centre_money → centre_invoice_run → centre_payments → centre_deposits → centre_refunds → centre_late_fees.
-- Needs migration_money_settings.sql (S0: the late-fee options), migration_centre_money.sql (S1), migration_centre_invoice_run.sql (S2: issuing),
-- migration_centre_payments.sql (S3: balances). Run on the DEV project first. LIVE only when the owner says ship: this migration reads and changes
-- no existing row (one new table, one widened check on invoice lines, new functions). Safe to run twice.
--
-- WHAT A LATE FEE IS HERE (owner-approved T4 decisions)
--   A late fee is a PROPOSAL first. TutorDeck lists "late fee due" items; a person with issue_invoices (or the owner) APPROVES each one, or WAIVES it
--   with a reason. Nothing is ever added to a family's bill silently, and nothing changes an issued invoice. An approved fee becomes its OWN document
--   (invoice kind 'late_fee', S1), numbered from the one shared invoice series, issued with the usual due days, GST frozen on it per the centre's GST
--   settings of the day it is approved. Because it is an ordinary issued invoice of the family, a payment pays it (oldest first, like any invoice) and it
--   counts in the family's balance, the Money > Invoices list and the revenue totals.
--
-- THE RULES (every value of every late-fee setting is built; money rules read the settings IN FORCE ON THE INVOICE'S DUE DATE, process rules as of TODAY)
--   billing.late_fee.enabled      false → no proposals are made (proposals made earlier stay).
--   billing.late_fee.repeat       none → never · once → one fee per invoice · monthly → AGAIN each month the invoice stays unpaid, on the same day of
--                                 the month as the first fee (the 31st clamps to the last day of shorter months, never drifts: month n is the first
--                                 fee date plus n−1 whole months).
--   billing.late_fee.after_days   the GRACE period. Paying on the due date, or within this many days after it, is on time. The first fee falls due on the
--                                 day AFTER the grace ends (due date + grace + 1). It is unpaid "on" a fee date when nothing had been paid or credited to
--                                 clear it by the END OF THE DAY BEFORE (payments count by the date they were received, credit notes by their issue date).
--   billing.late_fee.type         fixed   → amount_cents, flat, even when the invoice is part-paid.
--                                 percent → percent_bp of the UNPAID BALANCE of that invoice on that date (a part-paid invoice is charged on what is still
--                                           unpaid; half up to the cent).
--   billing.late_fee.cap_cents    0 = no limit; otherwise the most late fees ONE invoice can collect: a fee that would go over is cut to what is left,
--                                 and no more are proposed once it is used up. Waived fees don't count (nothing was collected).
--   billing.late_fee.show_as      own_invoice is built. next_invoice_line (a line on the family's next invoice) is `soon`: until it is built the fee is
--                                 still its own small invoice, and the screen says so.
--   billing.late_fee.waived_by    owner → only the centre owner can waive · issue_invoices → the owner and staff who issue invoices. A reason is always required.
--   FIXED (integrity, not process): lesson invoices only (a deposit, opening, late-fee or credit-note document never gets a late fee, so no compounding);
--   a fee is never proposed on an invoice that is paid, credited in full, or still a draft; a pending proposal STOPS when the invoice is settled
--   (paid or credited) and comes back if a payment is reversed; one fee per invoice per month number (unique), so scanning twice or pressing approve
--   twice never creates twice; an approved or waived fee never changes (a mistake in an approved fee is a credit note on its document).
--
-- HOW: there is no cron. Opening Money > Late fees (centre_late_fee_list) first SCANS the centre (centre_late_fee_scan, idempotent) and then lists what
--   is waiting. The fee amount is frozen on the proposal the day it is first proposed (with a snapshot of the rule) so later settings changes never rewrite it.
--
-- WHO MAY CALL: list / approve / approve all / waive / one invoice's fees: the centre OWNER or STAFF with issue_invoices (waive: see waived_by).
--   Tutors, parents, switched-off staff, staff without issue_invoices, solo owners, strangers and anonymous callers get NOT_FOUND / NOT_ALLOWED. The
--   table can be READ by the same people and has NO write policy: browsers never write a late fee. The scan is server-only.
-- AUDIT: the S1 audit trigger copies every row (free text, i.e. the waive reason, replaced by "[redacted]"); each function adds a summary row with amounts and counts only.
-- =====================================================================================================

-- ---------------------------------------------------------------------------------------------------
-- 1. lines of a late-fee document may say what they are
-- ---------------------------------------------------------------------------------------------------
do $$
declare c record;
begin
  for c in select conname from pg_constraint where conrelid = 'public.centre_invoice_lines'::regclass and contype = 'c'
            and pg_get_constraintdef(oid) like '%fee_kind%' and pg_get_constraintdef(oid) not like '%late_fee%' loop
    execute format('alter table public.centre_invoice_lines drop constraint %I', c.conname);
  end loop;
  if not exists (select 1 from pg_constraint where conrelid = 'public.centre_invoice_lines'::regclass and contype = 'c'
                  and pg_get_constraintdef(oid) like '%fee_kind%' and pg_get_constraintdef(oid) like '%late_fee%') then
    alter table public.centre_invoice_lines add constraint centre_invoice_lines_fee_kind_check
      check (fee_kind is null or fee_kind in ('registration', 'materials', 'sibling_discount', 'late_fee'));
  end if;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 2. the table: one row per (lesson invoice, month number)
-- ---------------------------------------------------------------------------------------------------
create table if not exists public.centre_late_fees (
  id           uuid primary key default gen_random_uuid(),
  org_id       uuid not null references public.organisations(id) on delete cascade,
  invoice_id   uuid not null,                                -- the lesson invoice that is late
  month_no     int  not null check (month_no between 1 and 120),
  fee_date     date not null,                                -- the day this fee fell due: first fee = due date + grace + 1 day, then +1 month each
  status       text not null default 'proposed' check (status in ('proposed', 'approved', 'waived', 'stopped')),
  fee_cents    bigint not null check (fee_cents > 0),        -- frozen when first proposed (before GST handling: GST is worked out when it is approved)
  base_cents   bigint,                                       -- percent fees: the unpaid balance the percentage was taken on (null for a fixed fee)
  rule         jsonb not null,                               -- snapshot of the rule used (repeat, type, amount, percent, grace, cap, show_as)
  household_id uuid,
  student_id   uuid,
  document_id  uuid,                                         -- the late-fee document, once approved
  decided_by   uuid,
  decided_at   timestamptz,
  reason       text,                                         -- waive reason (free text: redacted in the audit copy)
  created_at   timestamptz not null default now(),
  unique (id, org_id),
  unique (invoice_id, month_no),
  unique (document_id),
  foreign key (invoice_id, org_id)  references public.centre_invoices(id, org_id),
  foreign key (document_id, org_id) references public.centre_invoices(id, org_id),
  foreign key (household_id, org_id) references public.households(id, org_id),
  foreign key (student_id, org_id)   references public.students(id, org_id),
  check ((status = 'approved') = (document_id is not null)),
  check (status <> 'waived' or (reason is not null and length(trim(reason)) > 0 and decided_at is not null)),
  check (status not in ('approved', 'waived') or decided_at is not null)
);
create index if not exists centre_late_fees_org on public.centre_late_fees(org_id, status, fee_date);

-- ---------------------------------------------------------------------------------------------------
-- 3. guard: what may change
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_late_fee_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare inv record;
begin
  if tg_op = 'DELETE' then
    if centre_money_deleting(old.org_id) then return old; end if;
    raise exception 'A late fee can''t be deleted (waive it instead)' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'proposed' or new.document_id is not null or new.decided_at is not null then
      raise exception 'A late fee starts as a proposal' using errcode = '42501';
    end if;
    select * into inv from centre_invoices where id = new.invoice_id and org_id = new.org_id;
    if inv.id is null or inv.kind <> 'lesson' or inv.status <> 'issued' then
      raise exception 'A late fee can only be proposed on an issued lesson invoice' using errcode = '42501';
    end if;
    return new;
  end if;
  -- UPDATE
  if new.org_id <> old.org_id or new.invoice_id <> old.invoice_id or new.month_no <> old.month_no or new.fee_date <> old.fee_date
     or new.fee_cents <> old.fee_cents or new.base_cents is distinct from old.base_cents or new.rule <> old.rule
     or new.household_id is distinct from old.household_id or new.student_id is distinct from old.student_id then
    raise exception 'A late fee''s amount and invoice never change' using errcode = '42501';
  end if;
  if old.status in ('approved', 'waived') then
    raise exception 'A % late fee can''t be changed (a mistake is corrected with a credit note)', old.status using errcode = '42501';
  end if;
  if new.status = old.status then return new; end if;          -- (a no-op update)
  if old.status = 'proposed' and new.status in ('approved', 'waived', 'stopped') then return new; end if;
  if old.status = 'stopped' and new.status = 'proposed' then return new; end if;
  raise exception 'A late fee can''t go from % to %', old.status, new.status using errcode = '42501';
end $$;

-- the S1 triggers: centres only, audit with redaction
drop trigger if exists centre_money_org_guard on public.centre_late_fees;
create trigger centre_money_org_guard before insert on public.centre_late_fees for each row execute function public.centre_money_org_guard();
drop trigger if exists audit_row on public.centre_late_fees;
create trigger audit_row after insert or update or delete on public.centre_late_fees for each row execute function public.centre_money_audit();
drop trigger if exists centre_late_fee_guard on public.centre_late_fees;
create trigger centre_late_fee_guard before insert or update or delete on public.centre_late_fees for each row execute function public.centre_late_fee_guard();

alter table public.centre_late_fees enable row level security;
drop policy if exists money_read on public.centre_late_fees;
create policy money_read on public.centre_late_fees for select using (org_can(org_id, 'issue_invoices') and not org_is_solo(org_id));
revoke all on public.centre_late_fees from anon, authenticated;
grant select on public.centre_late_fees to authenticated;

-- ---------------------------------------------------------------------------------------------------
-- 4. internal helpers
-- ---------------------------------------------------------------------------------------------------
-- What an invoice still owes at the END of a given day: total − credit notes issued by then − payments received by then (reversals count by their own
-- date). Never below zero. INTERNAL.
create or replace function public.centre_invoice_balance_on(p_invoice uuid, p_day date) returns bigint
language sql stable security definer set search_path = public as $$
  select greatest(i.total_cents
    - coalesce((select sum(n.total_cents) from centre_invoices n where n.credits_invoice_id = i.id and n.status = 'issued' and n.issue_date <= p_day), 0)
    - coalesce((select sum(a.cents) from centre_payment_allocations a join centre_payments p on p.id = a.payment_id and p.org_id = a.org_id
                 where a.invoice_id = i.id and p.received_on <= p_day), 0), 0)::bigint
    from centre_invoices i where i.id = p_invoice
$$;

-- The scan. For every issued lesson invoice that is STILL UNPAID, makes the proposals that have fallen due by p_today and are not made yet, in month
-- order (so the cap is used up in order), then stops proposals whose invoice has been settled and revives them if it is owed again. Returns how many
-- proposals it made. INTERNAL (the list function calls it with the centre's own today; tests call it with any day). Safe to run twice and concurrently.
create or replace function public.centre_late_fee_scan(p_org uuid, p_today date) returns int
language plpgsql security definer set search_path = public as $$
declare inv record; s jsonb; lf jsonb; lastd date := null; rep text; typ text; grace int; amt bigint; bp int; cap bigint; f1 date; fn date; n int; maxn int;
        bal bigint; fee bigint; used bigint; made int := 0; skip boolean := false; rl jsonb; hh uuid;
begin
  if not exists (select 1 from organisations o where o.id = p_org and o.kind = 'centre') then return 0; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_org::text, 11));
  for inv in
    select i.id, i.number_text, i.due_date, i.household_id, i.student_id, i.total_cents
      from centre_invoices i
     where i.org_id = p_org and i.kind = 'lesson' and i.status = 'issued' and i.due_date is not null and i.due_date < p_today
       and centre_invoice_balance_on(i.id, p_today) > 0
     order by i.due_date, i.number_seq
  loop
    if lastd is distinct from inv.due_date then          -- the settings in force on the day the invoice fell due (cached: the loop is ordered by due date)
      s := org_settings_on(p_org, inv.due_date); lf := s #> '{billing,late_fee}'; lastd := inv.due_date;
      rep := coalesce(lf->>'repeat', 'once'); typ := coalesce(lf->>'type', 'fixed'); grace := coalesce((lf->>'after_days')::int, 7);
      amt := coalesce((lf->>'amount_cents')::bigint, 0); bp := coalesce((lf->>'percent_bp')::int, 0); cap := coalesce((lf->>'cap_cents')::bigint, 0);
      skip := not coalesce((lf->>'enabled')::boolean, false) or rep not in ('once', 'monthly');
      rl := jsonb_build_object('repeat', rep, 'type', typ, 'amount_cents', amt, 'percent_bp', bp, 'after_days', grace, 'cap_cents', cap,
                               'show_as', coalesce(lf->>'show_as', 'own_invoice'));
    end if;
    if skip then continue; end if;
    f1 := inv.due_date + grace + 1;
    maxn := case rep when 'once' then 1 else 120 end;
    hh := coalesce(inv.household_id, centre_invoice_household(inv.id));
    for n in 1 .. maxn loop
      fn := (f1 + make_interval(months => n - 1))::date;
      exit when fn > p_today;
      continue when exists (select 1 from centre_late_fees f where f.invoice_id = inv.id and f.month_no = n);
      bal := centre_invoice_balance_on(inv.id, fn - 1);        -- unpaid at the end of the day before the fee date
      continue when bal <= 0;
      fee := case typ when 'percent' then centre_div_round(bal * bp, 10000) else amt end;
      if cap > 0 then
        select coalesce(sum(f.fee_cents), 0) into used from centre_late_fees f where f.invoice_id = inv.id and f.status in ('proposed', 'approved');
        fee := least(fee, cap - used);
      end if;
      continue when fee <= 0;
      insert into centre_late_fees(org_id, invoice_id, month_no, fee_date, fee_cents, base_cents, rule, household_id, student_id)
      values (p_org, inv.id, n, fn, fee, case when typ = 'percent' then bal end, rl, hh, inv.student_id)
      on conflict (invoice_id, month_no) do nothing;
      if found then made := made + 1; end if;
    end loop;
  end loop;
  -- stop / revive: a proposal waits only while its invoice is still owed
  update centre_late_fees f set status = case when b.balance_cents > 0 then 'proposed' else 'stopped' end
    from centre_balance_rows(p_org, (select coalesce(array_agg(distinct x.invoice_id), '{}') from centre_late_fees x where x.org_id = p_org and x.status in ('proposed', 'stopped'))) b
   where f.org_id = p_org and f.invoice_id = b.invoice_id and f.status in ('proposed', 'stopped')
     and f.status <> case when b.balance_cents > 0 then 'proposed' else 'stopped' end;
  return made;
end $$;

-- "who and when" for the screens: owner or staff with issue_invoices; returns the centre's own today
create or replace function public.centre_late_fee_gate(p_org uuid) returns date
language plpgsql stable security definer set search_path = public as $$
begin
  return centre_money_gate(p_org, 'issue_invoices');
end $$;

-- plain words when the centre's option can't be fully acted on (null = nothing to say)
create or replace function public.centre_late_fee_note(p_settings jsonb) returns text
language sql immutable set search_path = public as $$
  select case
    when not coalesce((p_settings #>> '{billing,late_fee,enabled}')::boolean, false) then 'Late fees are switched off for this centre (Centre settings). Proposals made earlier still wait here.'
    when coalesce(p_settings #>> '{billing,late_fee,repeat}', 'once') = 'none' then 'Late fees are set to "never" (Centre settings). Proposals made earlier still wait here.'
    when p_settings #>> '{billing,late_fee,show_as}' = 'next_invoice_line' then 'Your settings ask for a line on the family''s next invoice. That is not built yet: each late fee is its own small invoice for now.'
    end
$$;

-- ---------------------------------------------------------------------------------------------------
-- 5. APPROVE: the fee becomes its own issued document (idempotent)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_late_fee_approve(p_fee uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; f centre_late_fees; inv centre_invoices; b record; g record; doc uuid := gen_random_uuid(); d centre_invoices; txt text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select x.org_id into org from centre_late_fees x where x.id = p_fee;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := centre_late_fee_gate(org);
  perform pg_advisory_xact_lock(hashtextextended(p_fee::text, 12));
  select * into f from centre_late_fees where id = p_fee and org_id = org for update;
  if f.status = 'approved' then                                          -- pressed twice: the same document, nothing new
    select * into d from centre_invoices where id = f.document_id;
    return jsonb_build_object('id', f.id, 'status', 'approved', 'already', true, 'document_id', d.id, 'number', d.number_text, 'total_cents', d.total_cents);
  end if;
  if f.status = 'waived' then raise exception 'NOT_ALLOWED: this late fee was waived' using errcode = '42501'; end if;
  if f.status <> 'proposed' then raise exception 'INVOICE_SETTLED: that invoice has been paid or credited, so no late fee is due' using errcode = 'P0001'; end if;
  select * into inv from centre_invoices where id = f.invoice_id and org_id = org for update;
  select * into b from centre_balance_rows(org, array[f.invoice_id]);
  if b.balance_cents <= 0 then raise exception 'INVOICE_SETTLED: that invoice has been paid or credited, so no late fee is due' using errcode = 'P0001'; end if;
  select * into g from centre_invoice_gst(org, f.fee_cents, today);       -- GST per the centre's settings today, frozen on the document
  txt := 'Late fee: invoice ' || inv.number_text || case when (f.rule->>'repeat') = 'monthly' then ' (month ' || f.month_no || ')' else '' end;
  insert into centre_invoices(id, org_id, kind, household_id, student_id, period_start, period_end, gst_registered, gst_rate_bp, gst_inclusive, net_cents, gst_cents, total_cents)
  values (doc, org, 'late_fee', coalesce(f.household_id, inv.household_id), f.student_id, inv.period_start, inv.period_end, g.gst_registered, g.gst_rate_bp, g.gst_inclusive,
          g.net_cents, g.gst_cents, g.total_cents);
  insert into centre_invoice_lines(org_id, invoice_id, position, student_id, fee_kind, description, qty, unit_cents)
  values (org, doc, 1, f.student_id, 'late_fee', txt, 1, f.fee_cents);
  d := centre_invoice_issue_draft(doc, today);
  update centre_late_fees set status = 'approved', document_id = doc, decided_by = auth.uid(), decided_at = now() where id = f.id;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'centre_late_fee_approve', 'centre_late_fees', f.id::text, null,
          jsonb_build_object('fee_cents', f.fee_cents, 'total_cents', d.total_cents, 'gst_cents', d.gst_cents, 'month_no', f.month_no));
  return jsonb_build_object('id', f.id, 'status', 'approved', 'already', false, 'document_id', d.id, 'number', d.number_text, 'total_cents', d.total_cents,
                            'gst_cents', d.gst_cents, 'due_date', d.due_date);
end $$;

-- approve everything that is waiting (each one exactly as above; one that can't be approved is skipped and counted)
create or replace function public.centre_late_fee_approve_all(p_org uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date; r record; ok int := 0; skipped int := 0; cents bigint := 0; res jsonb;
begin
  today := centre_late_fee_gate(p_org);
  perform centre_late_fee_scan(p_org, today);
  for r in select f.id from centre_late_fees f where f.org_id = p_org and f.status = 'proposed' order by f.fee_date, f.created_at, f.id loop
    begin
      res := centre_late_fee_approve(r.id);
      if not coalesce((res->>'already')::boolean, false) then ok := ok + 1; cents := cents + (res->>'total_cents')::bigint; end if;
    exception when others then skipped := skipped + 1; end;
  end loop;
  return jsonb_build_object('approved', ok, 'skipped', skipped, 'total_cents', cents);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 6. WAIVE: needs a reason; who may is the centre's setting
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_late_fee_waive(p_fee uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; f centre_late_fees; wb text; why text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select x.org_id into org from centre_late_fees x where x.id = p_fee;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := centre_late_fee_gate(org);
  wb := coalesce(org_settings_on(org, today) #>> '{billing,late_fee,waived_by}', 'owner');
  if wb = 'owner' and not org_can(org, 'owner') then raise exception 'NOT_ALLOWED: only the centre owner can waive a late fee' using errcode = '42501'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why this late fee is being waived' using errcode = 'P0001'; end if;
  if length(why) > 300 then raise exception 'TOO_LONG: keep the reason under 300 characters' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_fee::text, 12));
  select * into f from centre_late_fees where id = p_fee and org_id = org for update;
  if f.status = 'waived' then return jsonb_build_object('id', f.id, 'status', 'waived', 'already', true); end if;
  if f.status = 'approved' then raise exception 'NOT_ALLOWED: this late fee is already on the family''s account; to take it off, issue a credit note on its invoice' using errcode = '42501'; end if;
  if f.status <> 'proposed' then raise exception 'INVOICE_SETTLED: that invoice has been paid or credited, so there is nothing to waive' using errcode = 'P0001'; end if;
  update centre_late_fees set status = 'waived', reason = why, decided_by = auth.uid(), decided_at = now() where id = f.id;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'centre_late_fee_waive', 'centre_late_fees', f.id::text, null, jsonb_build_object('fee_cents', f.fee_cents, 'month_no', f.month_no, 'waived_by_rule', wb));
  return jsonb_build_object('id', f.id, 'status', 'waived', 'already', false, 'fee_cents', f.fee_cents);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 7. WHAT THE SCREENS READ
-- ---------------------------------------------------------------------------------------------------
-- Money > Late fees: scans, then lists "Late fees waiting for you" and the recent decisions.
create or replace function public.centre_late_fee_list(p_org uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_late_fee_gate(p_org); s jsonb := org_settings_on(p_org, today); wb text := coalesce(s #>> '{billing,late_fee,waived_by}', 'owner'); r jsonb;
begin
  perform centre_late_fee_scan(p_org, today);
  with fee as (
    select f.*, i.number_text as inv_number, i.due_date as inv_due, i.total_cents as inv_total, coalesce(h.name, st.name) as nm,
           (select b.balance_cents from centre_balance_rows(p_org, array[f.invoice_id]) b) as bal,
           (select d.number_text from centre_invoices d where d.id = f.document_id) as doc_number
      from centre_late_fees f join centre_invoices i on i.id = f.invoice_id and i.org_id = f.org_id
      left join households h on h.id = coalesce(f.household_id, i.household_id) and h.org_id = f.org_id
      left join students st on st.id = f.student_id and st.org_id = f.org_id
     where f.org_id = p_org
  )
  select jsonb_build_object(
    'today', today, 'enabled', coalesce((s #>> '{billing,late_fee,enabled}')::boolean, false), 'note', centre_late_fee_note(s),
    'repeat', coalesce(s #>> '{billing,late_fee,repeat}', 'once'),
    'can', jsonb_build_object('approve', true, 'waive', wb <> 'owner' or org_can(p_org, 'owner'), 'waived_by', wb),
    'waiting_count', (select count(*) from fee where status = 'proposed'),
    'waiting_cents', (select coalesce(sum(fee_cents), 0) from fee where status = 'proposed'),
    'waiting', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'invoice_id', x.invoice_id, 'invoice_number', x.inv_number, 'name', x.nm, 'household_id', x.household_id,
                 'student_id', x.student_id, 'month_no', x.month_no, 'fee_date', x.fee_date, 'fee_cents', x.fee_cents, 'base_cents', x.base_cents, 'type', x.rule->>'type',
                 'repeat', x.rule->>'repeat', 'invoice_due_date', x.inv_due, 'invoice_total_cents', x.inv_total, 'balance_cents', x.bal, 'days_late', today - x.inv_due,
                 'gst_cents', (select g.gst_cents from centre_invoice_gst(p_org, x.fee_cents, today) g), 'total_cents', (select g.total_cents from centre_invoice_gst(p_org, x.fee_cents, today) g))
                 order by x.fee_date, x.inv_number, x.month_no), '[]'::jsonb) from fee x where x.status = 'proposed'),
    'recent', (select coalesce(jsonb_agg(jsonb_build_object('id', y.id, 'invoice_number', y.inv_number, 'name', y.nm, 'month_no', y.month_no, 'status', y.status, 'fee_cents', y.fee_cents,
                 'decided_at', y.decided_at, 'document_id', y.document_id, 'document_number', y.doc_number, 'reason', y.reason) order by y.decided_at desc), '[]'::jsonb)
                 from (select * from fee where status in ('approved', 'waived') order by decided_at desc limit 50) y))
    into r;
  return r;
end $$;

-- the late fees of ONE invoice (for its detail sheet): waiting, approved (with the document), waived
create or replace function public.centre_late_fee_invoice_get(p_invoice uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; r jsonb;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select i.org_id into org from centre_invoices i where i.id = p_invoice;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform centre_late_fee_gate(org);
  select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'month_no', f.month_no, 'fee_date', f.fee_date, 'status', f.status, 'fee_cents', f.fee_cents,
         'document_id', f.document_id, 'document_number', d.number_text, 'reason', f.reason) order by f.month_no), '[]'::jsonb) into r
    from centre_late_fees f left join centre_invoices d on d.id = f.document_id where f.invoice_id = p_invoice and f.org_id = org and f.status <> 'stopped';
  return r;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 8. function access: signed-in users call the public ones (each starts with the gate); helpers are server-only
-- ---------------------------------------------------------------------------------------------------
revoke all on function public.centre_late_fee_guard() from public, anon, authenticated;
revoke all on function public.centre_invoice_balance_on(uuid, date) from public, anon, authenticated;
revoke all on function public.centre_late_fee_scan(uuid, date) from public, anon, authenticated;
revoke all on function public.centre_late_fee_gate(uuid) from public, anon, authenticated;
revoke all on function public.centre_late_fee_note(jsonb) from public, anon;
revoke all on function public.centre_late_fee_list(uuid) from public, anon;
revoke all on function public.centre_late_fee_approve(uuid) from public, anon;
revoke all on function public.centre_late_fee_approve_all(uuid) from public, anon;
revoke all on function public.centre_late_fee_waive(uuid, text) from public, anon;
revoke all on function public.centre_late_fee_invoice_get(uuid) from public, anon;
grant execute on function public.centre_late_fee_note(jsonb), public.centre_late_fee_list(uuid), public.centre_late_fee_approve(uuid), public.centre_late_fee_approve_all(uuid),
  public.centre_late_fee_waive(uuid, text), public.centre_late_fee_invoice_get(uuid) to authenticated, service_role;
grant execute on function public.centre_invoice_balance_on(uuid, date), public.centre_late_fee_scan(uuid, date) to service_role;

-- #####################################################################################################
-- ### PART 6 of 9 — undo of applied credit / deposit, four-eyes guard, notices
-- ### source branch: claude/t4-s5b-credit-undo   file: db/migration_centre_credit_undo.sql   undo: db/migration_centre_credit_undo_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T4 step S5b — undo of credit / deposit applied to an invoice, and the four-eyes guard for refund approval          undo: migration_centre_credit_undo_down.sql
-- =====================================================================================================
-- Run order everywhere: org_foundation → billing → attendance → tutor_access → org_delete → function_lockdown → org_separation →
--   staff_home → staff_students → staff_attendance → staff_charges → staff_trials → staff_timetable → money_settings →
--   centre_money → centre_invoice_run → centre_payments → centre_deposits → centre_refunds → centre_late_fees → centre_credit_undo.
-- Needs migration_centre_refunds.sql (S5) AND migration_fee_050.sql (org_create_centre below reads org_default_centre_plan(): bundle 5 fix, the first
-- version hard-coded 40c and would have undone the fee change). Run on the DEV project first. LIVE only when the owner says ship: it reads no existing row and changes none
-- (one new table, two widened checks, two re-created functions, new functions, one trigger on memberships). Safe to run twice.
--
-- PART A. UNDO OF AN APPLICATION (owner decision, 2026-11-27)
--   Credit (or a deposit kept against invoices) that was applied to an invoice is still never EDITED, but it can now be UNDONE as a NEW entry, the same
--   append-only pattern as reversing a payment:  a reversal payment row (method family_credit / deposit, pointing at the application), negative allocations
--   that reopen the invoice(s), and one new ledger row (kind 'application_undone') that gives the money back to the family credit / the deposit held.
--   Nothing is edited or deleted. A credit note only SUBTRACTS from an invoice, so it can never undo an application (that is why this exists).
--   WHO       the owner or staff with issue_invoices.   A REASON is required.   Audited (amounts only; the reason stays in the record, redacted in the copy).
--   ONCE      one reversal per application (unique index since S1): pressing twice answers {already:true} and writes nothing.
--   WHAT BLOCKS IT (stated in plain words on the screen; the application is one payment and can touch several invoices, so EVERY invoice must pass):
--     · the invoice is no longer an open issued invoice (defensive: an issued invoice is never cancelled; fully credited = the credit-note rule below)
--     · a credit note was issued on the invoice after the credit was used (the invoice's figures now depend on it)
--     · money was recorded or reversed on the invoice after the credit was used (a payment that was worked out assuming the credit)
--     · deposit only: the student's deposit changed after the set-off (another refund, adjustment ...)
--     An invoice that the credit itself paid in full CAN be undone: that is the mistake this fixes. (Owner to confirm this reading of "not paid".)
--   NEVER NEGATIVE  undoing only adds back: the invoice's balance goes up, the family credit / deposit held go up. The S1 / S3 / S4 guards still apply.
--   centre_reverse_payment (the cash-payment reversal) still refuses an applied credit / deposit; it now points to Undo instead of a credit note.
--
-- PART B. FOUR-EYES GUARD (owner decision, 2026-11-27)
--   "Refunds are approved by: someone other than the person who asked" (billing.deposit.refund_approved_by = four_eyes) only works when a SECOND person
--   exists. It can now be chosen ONLY while the centre has: the owner, an active staff member who issues invoices (needed for deposit refunds) AND an
--   active staff member who records payments (needed for family-credit refunds; may be the same person). The database enforces it:
--     · org_validate_settings(org, settings) refuses four_eyes when it can't be satisfied; org_save_settings and org_create_centre use it.
--     · if that staff member is later removed, switched off, or loses the permission, a trigger on memberships puts the setting back to the default
--       (owner approves) as a NEW effective-dated settings row (today; and the same day of any future-dated row that says four_eyes), tells every owner
--       in-app (org_notifications; the e-mail comes with the email provider: SOON), and writes the audit log. centre_refund_rule() also reads an
--       unsatisfiable four_eyes as 'owner', so a request that was waiting for a second person becomes approvable by the owner at once, even in the gap.
-- =====================================================================================================

-- ---------------------------------------------------------------------------------------------------
-- 1. the two ledgers learn "application_undone" (a positive row: the money is the family's / the deposit's again)
-- ---------------------------------------------------------------------------------------------------
do $$
declare c record;
begin
  if not exists (select 1 from pg_constraint where conname = 'centre_family_credit_kind_s5b') then
    alter table public.centre_family_credit drop constraint if exists centre_family_credit_kind_s5;
    alter table public.centre_family_credit add constraint centre_family_credit_kind_s5b
      check (kind in ('overpayment', 'credit_note_excess', 'payment_reversal', 'excess_release', 'refund', 'applied', 'application_undone'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'centre_family_credit_sign_s5b') then
    for c in select conname from pg_constraint where conrelid = 'public.centre_family_credit'::regclass and contype = 'c'
              and pg_get_constraintdef(oid) like '%credit_note_excess%' and pg_get_constraintdef(oid) like '%cents > 0%' and pg_get_constraintdef(oid) not like '%payment_reversal%' loop
      execute format('alter table public.centre_family_credit drop constraint %I', c.conname);
    end loop;
    alter table public.centre_family_credit add constraint centre_family_credit_sign_s5b
      check ((kind in ('overpayment', 'credit_note_excess', 'application_undone')) = (cents > 0));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'centre_deposit_ledger_kind_s5b') then
    for c in select conname from pg_constraint where conrelid = 'public.centre_deposit_ledger'::regclass and contype = 'c'
              and pg_get_constraintdef(oid) like '%opening_balance%' and pg_get_constraintdef(oid) like '%transferred_out%' and pg_get_constraintdef(oid) not like '%CASE%' loop
      execute format('alter table public.centre_deposit_ledger drop constraint %I', c.conname);
    end loop;
    alter table public.centre_deposit_ledger add constraint centre_deposit_ledger_kind_s5b
      check (kind in ('received', 'reversal', 'waived', 'adjusted', 'applied', 'forfeited', 'refunded', 'transferred_out', 'transferred_in', 'opening_balance', 'application_undone'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'centre_deposit_ledger_sign_s5b') then
    for c in select conname from pg_constraint where conrelid = 'public.centre_deposit_ledger'::regclass and contype = 'c'
              and pg_get_constraintdef(oid) like '%CASE%' and pg_get_constraintdef(oid) like '%transferred_out%' loop
      execute format('alter table public.centre_deposit_ledger drop constraint %I', c.conname);
    end loop;
    alter table public.centre_deposit_ledger add constraint centre_deposit_ledger_sign_s5b
      check (case kind when 'received' then cents > 0 when 'opening_balance' then cents > 0 when 'transferred_in' then cents > 0 when 'waived' then cents > 0
                       when 'application_undone' then cents > 0
                       when 'reversal' then cents < 0 when 'applied' then cents < 0 when 'forfeited' then cents < 0 when 'refunded' then cents < 0
                       when 'transferred_out' then cents < 0 else true end);
  end if;
end $$;

-- the S5 guard on "internal" reversals: only Undo (which switches the flag on for its own transaction) may write one
create or replace function public.centre_internal_method_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.kind = 'reversal' and new.method in ('family_credit', 'deposit') and coalesce(current_setting('td.undo_application', true), '') <> '1' then
    raise exception 'NOT_ALLOWED: credit or deposit that was applied to an invoice can''t be reversed like a payment; use Undo on the invoice instead (a credit note can''t give it back)' using errcode = '42501';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 2. what blocks an undo (internal; plain words, one entry per problem)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_undo_blockers(p_org uuid, p_payment uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare p centre_payments; r record; out jsonb := '[]'::jsonb; sid uuid; led centre_deposit_ledger;
begin
  select * into p from centre_payments where id = p_payment and org_id = p_org;
  if p.id is null then return out; end if;
  for r in
    select i.id, i.number_text, i.status
      from centre_invoices i
     where i.org_id = p_org and i.id in (select a.invoice_id from centre_payment_allocations a where a.org_id = p_org and a.payment_id = p.id group by a.invoice_id having sum(a.cents) > 0)
     order by i.issue_date, i.number_seq
  loop
    if r.status <> 'issued' then
      out := out || jsonb_build_object('code', 'invoice_closed', 'invoice_id', r.id, 'text', 'Invoice ' || r.number_text || ' is cancelled, so the money can''t be taken back from it.');
    elsif exists (select 1 from centre_invoices n where n.org_id = p_org and n.credits_invoice_id = r.id and n.status = 'issued') then
      out := out || jsonb_build_object('code', 'credit_note', 'invoice_id', r.id, 'text', 'Invoice ' || r.number_text || ' has a credit note, issued after the credit was used. Its figures now depend on it.');
    elsif (select coalesce(sum(x.cents), 0) from centre_payment_allocations x where x.org_id = p_org and x.invoice_id = r.id and x.payment_id <> p.id and x.created_at > p.created_at) <> 0 then
      out := out || jsonb_build_object('code', 'later_payment', 'invoice_id', r.id, 'text', 'Money was recorded on invoice ' || r.number_text || ' after the credit was used. Reverse that payment first.');
    end if;
  end loop;
  if p.method = 'deposit' then
    select * into led from centre_deposit_ledger where org_id = p_org and payment_id = p.id and kind = 'applied';
    if led.id is not null and exists (select 1 from centre_deposit_ledger d where d.org_id = p_org and d.student_id = led.student_id and d.created_at > led.created_at
                                         and d.refund_id is distinct from led.refund_id and d.kind <> 'application_undone') then
      out := out || jsonb_build_object('code', 'deposit_changed', 'invoice_id', null, 'text', 'The student''s deposit changed after it was kept against the invoice (another refund or adjustment), so this can''t be undone.');
    end if;
  end if;
  return out;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 3. UNDO an application (one payment of method family_credit / deposit) — owner or staff with issue_invoices
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_undo_application(p_payment uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; p centre_payments; why text := nullif(btrim(coalesce(p_reason, '')), ''); rid uuid := gen_random_uuid(); a record; bl jsonb; led record;
  nums text; sid uuid;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select org_id into org from centre_payments where id = p_payment;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := centre_money_gate(org, 'issue_invoices');
  select * into p from centre_payments where id = p_payment and org_id = org;
  if p.kind <> 'payment' or p.method not in ('family_credit', 'deposit') then
    raise exception 'NOT_ALLOWED: only credit or a deposit that was applied to an invoice can be undone here' using errcode = '42501'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why this is being undone' using errcode = 'P0001'; end if;
  if length(why) > 300 then raise exception 'TOO_LONG: keep the reason under 300 characters' using errcode = 'P0001'; end if;
  if p.method = 'deposit' then
    select * into led from centre_deposit_ledger where org_id = org and payment_id = p.id and kind = 'applied';
    if led.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
    sid := led.student_id;
    perform pg_advisory_xact_lock(hashtextextended(sid::text, 6));
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p.household_id::text, 4));
  if exists (select 1 from centre_payments where reverses_payment_id = p.id and org_id = org) then
    return jsonb_build_object('already', true, 'payment_id', p.id, 'credit_balance_cents', centre_credit_balance(org, p.household_id));
  end if;
  bl := centre_undo_blockers(org, p.id);
  if jsonb_array_length(bl) > 0 then raise exception 'UNDO_BLOCKED: %', bl->0->>'text' using errcode = '42501'; end if;
  perform set_config('td.undo_application', '1', true);
  insert into centre_payments(id, org_id, kind, reverses_payment_id, household_id, method, amount_cents, received_on, note)
  values (rid, org, 'reversal', p.id, p.household_id, p.method, p.amount_cents, greatest(today, p.received_on), why);
  perform set_config('td.undo_application', '', true);
  for a in select invoice_id, sum(cents) as c from centre_payment_allocations where payment_id = p.id and org_id = org group by invoice_id having sum(cents) > 0 loop
    insert into centre_payment_allocations(org_id, payment_id, invoice_id, cents) values (org, rid, a.invoice_id, -a.c);
  end loop;
  select string_agg(i.number_text, ', ' order by i.issue_date, i.number_seq) into nums from centre_invoices i
   where i.org_id = org and i.id in (select invoice_id from centre_payment_allocations where payment_id = rid);
  if p.method = 'family_credit' then
    insert into centre_family_credit(org_id, household_id, kind, cents, payment_id, reason)
    values (org, p.household_id, 'application_undone', p.amount_cents, p.id, 'Undone: ' || why);
  else
    insert into centre_deposit_ledger(org_id, student_id, deposit_id, kind, cents, taxable, payment_id, entry_date, reason, refund_id)
    values (org, led.student_id, led.deposit_id, 'application_undone', p.amount_cents, led.taxable, p.id, today, 'Undone: ' || why, led.refund_id);
  end if;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'centre_application_undo', 'centre_payments', p.id::text, jsonb_build_object('method', p.method, 'amount_cents', p.amount_cents),
          jsonb_build_object('reversal_id', rid, 'undone_cents', p.amount_cents, 'invoices', (select count(distinct invoice_id) from centre_payment_allocations where payment_id = rid)));
  return jsonb_build_object('already', false, 'reversal_id', rid, 'payment_id', p.id, 'undone_cents', p.amount_cents, 'invoices', nums,
                            'credit_balance_cents', centre_credit_balance(org, p.household_id));
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 4. what the invoice sheet reads: the applications on one invoice, each with "can it be undone, and if not, why"
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_invoice_applications(p_invoice uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare org uuid; today date; role_ok boolean; res jsonb;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select org_id into org from centre_invoices where id = p_invoice;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := centre_money_gate(org, 'either');
  role_ok := org_can(org, 'issue_invoices');
  select coalesce(jsonb_agg(x.j order by x.d, x.id), '[]'::jsonb) into res from (
    select p.id, p.received_on as d, jsonb_build_object(
      'payment_id', p.id, 'method', p.method, 'cents', p.amount_cents, 'date', p.received_on,
      'on_this_invoice_cents', (select coalesce(sum(a.cents), 0) from centre_payment_allocations a where a.org_id = org and a.payment_id = p.id and a.invoice_id = p_invoice),
      'also_invoices', coalesce((select jsonb_agg(i.number_text order by i.issue_date, i.number_seq) from centre_invoices i where i.org_id = org and i.id <> p_invoice
                                   and i.id in (select a.invoice_id from centre_payment_allocations a where a.org_id = org and a.payment_id = p.id)), '[]'::jsonb),
      'by', centre_person_name(org, p.recorded_by),
      'state', case when u.id is null then 'active' else 'undone' end,
      'undone_on', u.received_on, 'undone_by', centre_person_name(org, u.recorded_by), 'undone_reason', case when role_ok then u.note end,
      'blockers', case when u.id is null then centre_undo_blockers(org, p.id) else '[]'::jsonb end,
      'can_undo', role_ok and u.id is null and jsonb_array_length(centre_undo_blockers(org, p.id)) = 0) as j
      from centre_payments p left join centre_payments u on u.reverses_payment_id = p.id and u.org_id = p.org_id
     where p.org_id = org and p.kind = 'payment' and p.method in ('family_credit', 'deposit')
       and exists (select 1 from centre_payment_allocations a where a.org_id = org and a.payment_id = p.id and a.invoice_id = p_invoice)) x;
  return jsonb_build_object('today', today, 'can_undo_role', role_ok, 'rows', res);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 5. FOUR EYES. Is a second approver possible? (internal)
-- ---------------------------------------------------------------------------------------------------
-- the owner, a staff member who issues invoices (deposit refunds) and a staff member who records payments (family-credit refunds), all active
create or replace function public.org_four_eyes_status(p_org uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'owner',   exists (select 1 from memberships m where m.org_id = p_org and m.role = 'owner' and m.status = 'active' and m.user_id is not null),
    'deposit', exists (select 1 from memberships m where m.org_id = p_org and m.role = 'staff' and m.status = 'active' and m.user_id is not null and 'issue_invoices' = any(m.permissions)),
    'credit',  exists (select 1 from memberships m where m.org_id = p_org and m.role = 'staff' and m.status = 'active' and m.user_id is not null and 'record_payments' = any(m.permissions)))
$$;
create or replace function public.org_four_eyes_ready(p_org uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(bool_and(v::boolean), false) from jsonb_each_text(public.org_four_eyes_status(p_org)) as t(k, v)
$$;

-- the settings check that knows which organisation it is for (the 1-argument org_validate_settings can't: it only sees the JSON)
create or replace function public.org_validate_settings(p_org uuid, s jsonb) returns void language plpgsql stable security definer set search_path = public as $$
declare st jsonb;
begin
  perform public.org_validate_settings(s);
  if s #>> '{billing,deposit,refund_approved_by}' = 'four_eyes' then
    st := case when p_org is null then jsonb_build_object('owner', true, 'deposit', false, 'credit', false) else public.org_four_eyes_status(p_org) end;
    if not (coalesce((st->>'owner')::boolean, false) and coalesce((st->>'deposit')::boolean, false) and coalesce((st->>'credit')::boolean, false)) then
      raise exception 'FOUR_EYES_UNAVAILABLE: "someone other than the person who asked" needs a second approver: the owner, a staff member who issues invoices (for deposit refunds) and a staff member who records payments (for credit refunds), all active. Add them first, or pick another approver.' using errcode = '42501';
    end if;
  end if;
end $$;

-- same bodies as the foundation versions, with the organisation-aware check
create or replace function public.org_save_settings(p_org uuid, p_settings jsonb, p_effective_from date) returns int
language plpgsql security definer set search_path = public as $$
declare v int; st text;
begin
  if not org_can(p_org, 'owner') then raise exception 'Only the owner can change settings' using errcode = '42501'; end if;
  perform org_validate_settings(p_org, p_settings);
  select status into st from organisations where id = p_org;
  if st <> 'setup' and p_effective_from < current_date then raise exception 'Settings can''t be back-dated'; end if;
  select coalesce(max(version), 0) + 1 into v from org_settings where org_id = p_org;
  insert into org_settings(org_id, version, schema_version, effective_from, settings, created_by)
  values (p_org, v, 1, case when st = 'setup' then least(p_effective_from, current_date) else p_effective_from end, p_settings, auth.uid());
  return v;
end $$;

create or replace function public.org_create_centre(p_name text, p_settings jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare o uuid; nm text;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  perform org_validate_settings(null::uuid, p_settings);
  insert into organisations(kind, preset, status, trading_name, created_by) values ('centre', 'centre', 'setup', trim(p_name), auth.uid()) returning id into o;
  select coalesce(nullif(p.full_name, ''), split_part(u.email, '@', 1)) into nm from auth.users u left join profiles p on p.id = u.id where u.id = auth.uid();
  insert into memberships(org_id, user_id, display_name, role) values (o, auth.uid(), coalesce(nm, 'Owner'), 'owner');
  insert into org_settings(org_id, version, schema_version, effective_from, settings, created_by) values (o, 1, 1, current_date, p_settings, auth.uid());
  insert into org_plans(org_id, plan_code, base_cents, per_student_cents, effective_from)
    select o, 'centre', d.base_cents, d.per_student_cents, current_date from org_default_centre_plan() d;   -- bundle 5: the fee_050 body (never a hard-coded 40c)
  return o;
end $$;

-- the rule read by the refund screens: four_eyes that can't be satisfied is read as "owner" (so nothing is ever stuck waiting for nobody)
create or replace function public.centre_refund_rule(p_org uuid, p_today date) returns text
language sql stable security definer set search_path = public as $$
  select case coalesce(org_settings_on(p_org, p_today)#>>'{billing,deposit,refund_approved_by}', 'owner')
           when 'staff' then 'staff'
           when 'four_eyes' then case when org_four_eyes_ready(p_org) then 'four_eyes' else 'owner' end
           else 'owner' end
$$;

-- ---------------------------------------------------------------------------------------------------
-- 6. in-app notices (the e-mail copy is SOON: it needs the email provider)
-- ---------------------------------------------------------------------------------------------------
create table if not exists public.org_notifications (
  id         uuid primary key default gen_random_uuid(),
  org_id     uuid not null references public.organisations(id) on delete cascade,
  user_id    uuid not null,                                   -- who it is for (an owner)
  kind       text not null,
  title      text not null,
  body       text not null,
  created_at timestamptz not null default now(),
  read_at    timestamptz
);
create index if not exists org_notifications_user on public.org_notifications(user_id, created_at desc);
alter table public.org_notifications enable row level security;
drop policy if exists own_read on public.org_notifications;
create policy own_read on public.org_notifications for select using (user_id = auth.uid());
revoke all on public.org_notifications from anon, authenticated;
grant select on public.org_notifications to authenticated;

create or replace function public.org_notification_dismiss(p_id uuid) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  update org_notifications set read_at = now() where id = p_id and user_id = auth.uid() and read_at is null;
  return found;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 7. the fall-back: when four_eyes stops being possible, the setting goes back to "owner approves" (internal)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.org_four_eyes_enforce(p_org uuid, p_cause text) returns boolean
language plpgsql security definer set search_path = public as $$
declare o record; today date; d date; cur record; changed int := 0; ow record; why text;
begin
  select id, kind, timezone into o from organisations where id = p_org;
  if o.id is null or o.kind <> 'centre' or coalesce(current_setting('td.deleting_org', true), '') = p_org::text then return false; end if;
  if org_four_eyes_ready(p_org) then return false; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_org::text, 11));
  today := (now() at time zone coalesce(o.timezone, 'Asia/Singapore'))::date;
  -- today, then every later day a settings row starts on: whatever is in force that day and still says four_eyes is replaced
  for d in select today union select distinct s.effective_from from org_settings s where s.org_id = p_org and s.effective_from > today order by 1 loop
    select s.* into cur from org_settings s where s.org_id = p_org and s.effective_from <= d order by s.effective_from desc, s.version desc limit 1;
    if cur.id is not null and cur.settings #>> '{billing,deposit,refund_approved_by}' = 'four_eyes' then
      insert into org_settings(org_id, version, schema_version, effective_from, settings, created_by)
      values (p_org, (select max(version) + 1 from org_settings where org_id = p_org), cur.schema_version, d,
              jsonb_set(cur.settings, '{billing,deposit,refund_approved_by}', '"owner"', true), auth.uid());
      changed := changed + 1;
    end if;
  end loop;
  if changed = 0 then return false; end if;
  why := case p_cause when 'removed' then 'a staff member was removed' when 'disabled' then 'a staff member was switched off'
                      when 'permission' then 'a staff member lost the permission it needs' else 'the second approver is no longer available' end;
  for ow in select m.user_id from memberships m where m.org_id = p_org and m.role = 'owner' and m.status = 'active' and m.user_id is not null loop
    insert into org_notifications(org_id, user_id, kind, title, body)
    values (p_org, ow.user_id, 'four_eyes_fallback', 'Refund approval is back to “the owner approves”',
            'The setting “someone other than the person who asked” needs a second approver, and ' || why || '. It has been changed back to “the owner approves”. '
            || 'Refund requests that were waiting for a second person can now be approved by you. Add a staff member who issues invoices and one who records payments, then choose the setting again.');
  end loop;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'org_four_eyes_fallback', 'org_settings', p_org::text, jsonb_build_object('refund_approved_by', 'four_eyes'),
          jsonb_build_object('refund_approved_by', 'owner', 'cause', coalesce(p_cause, 'unknown'), 'rows_written', changed));
  return true;
end $$;

create or replace function public.org_four_eyes_watch() returns trigger
language plpgsql security definer set search_path = public as $$
declare cause text;
begin
  if tg_op = 'DELETE' then
    if old.role = 'staff' then perform org_four_eyes_enforce(old.org_id, 'removed'); end if;
    return null;
  end if;
  if old.role = 'staff' then
    cause := case when new.role <> 'staff' or new.user_id is distinct from old.user_id then 'removed'
                  when new.status <> 'active' and old.status = 'active' then 'disabled'
                  when new.permissions is distinct from old.permissions then 'permission' end;
    if cause is not null then perform org_four_eyes_enforce(new.org_id, cause); end if;
  elsif old.role = 'owner' and (new.role <> 'owner' or new.status <> 'active') then
    perform org_four_eyes_enforce(new.org_id, 'removed');
  end if;
  return null;
end $$;
drop trigger if exists org_four_eyes_watch on public.memberships;
create trigger org_four_eyes_watch after update or delete on public.memberships for each row execute function public.org_four_eyes_watch();

-- ---------------------------------------------------------------------------------------------------
-- 8. function access
-- ---------------------------------------------------------------------------------------------------
revoke all on function public.centre_undo_blockers(uuid, uuid) from public, anon, authenticated;
revoke all on function public.org_four_eyes_status(uuid) from public, anon, authenticated;
revoke all on function public.org_four_eyes_ready(uuid) from public, anon, authenticated;
revoke all on function public.org_validate_settings(uuid, jsonb) from public, anon, authenticated;
revoke all on function public.org_four_eyes_enforce(uuid, text) from public, anon, authenticated;
revoke all on function public.org_four_eyes_watch() from public, anon, authenticated;
revoke all on function public.centre_undo_application(uuid, text) from public, anon;
revoke all on function public.centre_invoice_applications(uuid) from public, anon;
revoke all on function public.org_notification_dismiss(uuid) from public, anon;
grant execute on function public.centre_undo_application(uuid, text), public.centre_invoice_applications(uuid), public.org_notification_dismiss(uuid) to authenticated, service_role;

-- #####################################################################################################
-- ### PART 7 of 9 — slot stop dates, class members, 26-week lessons, holiday cancel, People list
-- ### source branch: claude/t3-9-timetable-nav   file: db/migration_slot_changes.sql   undo: db/migration_slot_changes_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T3.9 — timetable changes and the People list                                           undo: migration_slot_changes_down.sql
-- =====================================================================================================
-- Needs everything before it, in this order: ... staff_slots, staff_reassign, tutor_schedule, centre_money (centre_invoice_lines), invites (the
-- invite send log), payout_permission. Run it LAST of the current migrations. Safe to run twice. DEV first; never on LIVE before the code ships.
--
-- WHAT IT ADDS
--   recurring_slots.starts_on / stopped_from   a weekly slot can start on, and stop from, a chosen day (null = no limit). The slot's `active` flag
--                                              stays true while its stop day is still to come, and the generator and every list honour the dates.
--   lesson_change_blocker(lesson)              internal: why a lesson must not be touched (MARKED, CANCELLED, PAID, INVOICED), null = free to change.
--                                              "Invoiced" means listed on a current solo invoice OR on any centre invoice line (draft, issued or void: a
--                                              lesson that has ever been put on a document is left alone).
--   staff_stop_slot_from(...)                  stop a weekly slot (or the whole class) FROM a day; optionally also remove its later lessons that are not
--                                              marked, paid or invoiced. p_dry = true only COUNTS, so the screen can show the number before confirming.
--   staff_slot_student(...)                    add a student to / remove a student from an existing weekly slot, from a day (p_dry = count only).
--   staff_holiday_cancel(...)                  cancel the lessons already on a holiday's days (not marked, paid or invoiced), no charge (p_dry = count only).
--   staff_people(org)                          the centre's people for the People tab: owner/staff/tutors with role, status and invite state. No money.
--   staff_generate_lessons                     replaced (same arguments): now up to 26 weeks (182 days) at a time instead of 62 days, and the answer
--                                              says how many `days`. Internally split: staff_generate_core does the work for all slots or for a few.
--   staff_slots / staff_save_slot / tutor_my_slots   replaced (same arguments): they leave out a slot once its stop day has come, and saving a slot
--                                              with a tutor now ADDS that tutor to each student's assigned tutors (never removes anyone), and says so.
--
-- WHO MAY CALL (the same words as the rest of the staff screens)
--   writing   an active OWNER or STAFF member of this centre with manage_timetable (owners always)
--   People    the owner (everyone), or staff with manage_tutors (the tutors). Staff without it get NOT_ALLOWED. Never an email, a phone, pay or any money.
--   a tutor / a parent / switched-off staff / a stranger / a solo organisation / an unknown id  →  NOT_FOUND (same words, so ids can't be probed)
--
-- THE RULE FOR EVERY "REMOVE" OR "CANCEL" HERE
--   A lesson that has been MARKED (attendance set), is PAID, or sits on an INVOICE (solo or centre) is never touched. A lesson already cancelled stays
--   as it is. Only lessons nobody has acted on are removed or cancelled. Every call is idempotent: pressing it twice changes nothing the second time.
--   Every real change is written to the audit log with the counts. Lessons in the past are never changed (the days start today at the earliest).
--
-- CENTRE SETTING (product principle: two centres could want this differently)
--   lessons.auto_assign_tutors   boolean, default ON (missing = on). When a weekly slot with a tutor is saved, the tutor is added to the student's
--                                assigned tutors. A centre that wants to assign tutors by hand switches it off in the wizard (assets/js/org-settings.js).
--                                Read as of TODAY (a process rule). Not validated by org_validate_settings (a missing or non-boolean value = on).
-- =====================================================================================================

alter table public.recurring_slots add column if not exists starts_on date;          -- first day the slot runs (null = from the start)
alter table public.recurring_slots add column if not exists stopped_from date;       -- first day it no longer runs (null = until stopped)

-- ---------------------------------------------------------------- why a lesson must be left alone (null = free to change)
create or replace function public.lesson_change_blocker(p_lesson uuid) returns text
language sql stable security definer set search_path = public as $$
  select coalesce(lesson_locked_reason(l.id),
                  case when exists (select 1 from centre_invoice_lines cl where cl.lesson_id = l.id and cl.org_id = l.org_id) then 'INVOICED' end)
    from lessons l where l.id = p_lesson $$;
revoke all on function public.lesson_change_blocker(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------- 3. the weekly slots (read): leaves out slots whose stop day has come, and says when one stops

create or replace function public.staff_slots(p_org uuid, p_tutor uuid default null, p_q text default null, p_page int default 1, p_size int default 25)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, false); can_edit boolean := org_can(p_org, 'manage_timetable');
        q text := nullif(trim(coalesce(p_q, '')), ''); pat text; pg int := coalesce(p_page, 1); sz int := coalesce(p_size, 25);
        rows jsonb; tutors jsonb; total int; gen date;
begin
  if q is not null and length(q) > 100 then raise exception 'BAD_SEARCH: search for at most 100 characters' using errcode = 'P0001'; end if;
  if pg < 1 or pg > 100000 then raise exception 'BAD_PAGE: no such page' using errcode = 'P0001'; end if;
  if sz < 1 or sz > 100 then raise exception 'BAD_PAGE: ask for 1 to 100 slots at a time' using errcode = 'P0001'; end if;
  if p_tutor is not null and not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if q is not null then pat := '%' || replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_') || '%'; end if;

  with g as (
    select coalesce(sl.session_key, sl.id) as gk, min(sl.id::text)::uuid as first_id, count(*)::int as n,
           min(sl.weekday) as weekday, min(sl.start_time) as start_time, min(sl.end_time) as end_time, min(sl.subject) as subject, min(sl.rate) as rate, case when bool_and(sl.stopped_from is not null) then max(sl.stopped_from) end as stops_on,
           (array_agg(sl.taught_by))[1] as taught_by, bool_or(sl.session_key is not null) as is_group,
           jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'level', s.level,
                       'ended', (s.end_date is not null and s.end_date < today), 'slot_id', sl.id, 'starts_on', sl.starts_on, 'stops_on', sl.stopped_from) order by s.name, s.id) as studs
      from recurring_slots sl join students s on s.id = sl.student_id and s.org_id = sl.org_id
     where sl.org_id = p_org and sl.active and (sl.stopped_from is null or sl.stopped_from > today) and (p_tutor is null or sl.taught_by = p_tutor)
       and (q is null or sl.subject ilike pat or s.name ilike pat)
     group by coalesce(sl.session_key, sl.id)),
  paged as (select * from g order by weekday, start_time, (studs->0->>'name'), gk limit sz offset (pg - 1) * sz)
  select (select count(*) from g)::int,
         coalesce((select jsonb_agg(jsonb_build_object(
           'key', p.gk, 'slot_id', p.first_id, 'weekday', p.weekday, 'start_time', p.start_time, 'end_time', p.end_time,
           'minutes', (extract(epoch from (p.end_time - p.start_time)) / 60)::int, 'subject', p.subject,
           'rate', case when can_edit then p.rate end, 'stops_on', p.stops_on,
           'tutor_id', p.taught_by,
           'tutor_name', case when p.taught_by is null then null when t.status is null or t.status = 'disabled' then 'Former tutor' else coalesce(t.display_name, 'Tutor') end,
           'no_tutor', (p.taught_by is null or t.status is null or t.status = 'disabled'),
           'is_group', p.is_group, 'students', p.studs)
           order by p.weekday, p.start_time, (p.studs->0->>'name'), p.gk)
           from paged p left join memberships t on t.id = p.taught_by and t.org_id = p_org), '[]'::jsonb)
    into total, rows;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.display_name) order by m.display_name, m.id), '[]'::jsonb) into tutors
    from memberships m where m.org_id = p_org and m.role = 'tutor' and m.status in ('active', 'invited');
  select max(l.lesson_date) into gen from lessons l where l.org_id = p_org and l.slot_id is not null;
  return jsonb_build_object('today', today, 'can_edit', can_edit, 'page', pg, 'size', sz, 'total', total, 'generated_until', gen,
                            'tutors', tutors, 'rows', rows);
end $$;
revoke all on function public.staff_slots(uuid, uuid, text, int, int) from public, anon;
grant execute on function public.staff_slots(uuid, uuid, text, int, int) to authenticated;

-- ---------------------------------------------------------------- 4. staff_save_slot: skips ended slots in its clash checks, and adds the tutor to the student's assigned tutors
create or replace function public.staff_save_slot(p_org uuid, p_slot uuid, p_students uuid[], p_weekday int, p_start time, p_end time,
                                                  p_tutor uuid default null, p_subject text default null, p_rate numeric default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); subj text := nullif(trim(coalesce(p_subject, '')), ''); mins int;
        sids uuid[]; sid uuid; sl recurring_slots; key uuid; owner_uid uuid; ids uuid[] := '{}'; sr students; clash text; new_id uuid; made int; r numeric(8,2);
        auto boolean; assigned jsonb := '[]'::jsonb; sname text; tname text;
begin
  if p_weekday is null or p_weekday < 0 or p_weekday > 6 then raise exception 'BAD_SLOT: pick a day of the week' using errcode = 'P0001'; end if;
  if p_start is null or p_end is null then raise exception 'BAD_TIME: give a start and an end time' using errcode = 'P0001'; end if;
  mins := (extract(epoch from (p_end - p_start)) / 60)::int;
  if mins <= 0 then raise exception 'BAD_TIME: the lesson must end after it starts' using errcode = 'P0001'; end if;
  if mins < 15 or mins > 480 then raise exception 'BAD_TIME: a lesson lasts 15 minutes to 8 hours' using errcode = 'P0001'; end if;
  if subj is not null and length(subj) > 60 then raise exception 'BAD_SLOT: the subject is too long (60 characters at most)' using errcode = 'P0001'; end if;
  if p_rate is not null and (p_rate < 0 or p_rate > 1000) then raise exception 'BAD_RATE: the rate per hour must be between 0 and 1000' using errcode = 'P0001'; end if;
  r := round(p_rate, 2);
  if p_tutor is not null and not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org and m.role in ('tutor', 'staff', 'owner') and m.status in ('active', 'invited')) then
    raise exception 'NOT_AVAILABLE: that person can''t be given lessons at this centre' using errcode = 'P0001'; end if;

  if p_slot is null then
    if p_rate is null then raise exception 'BAD_RATE: type the rate per hour' using errcode = 'P0001'; end if;
    select coalesce(array_agg(distinct x), '{}') into sids from unnest(coalesce(p_students, '{}')) x where x is not null;
    if coalesce(array_length(sids, 1), 0) < 1 then raise exception 'BAD_STUDENTS: pick at least one student' using errcode = 'P0001'; end if;
    if array_length(sids, 1) > 30 then raise exception 'BAD_STUDENTS: a class has at most 30 students' using errcode = 'P0001'; end if;
    select m.user_id into owner_uid from memberships m where m.org_id = p_org and m.role = 'owner' and m.status = 'active' and m.user_id is not null order by m.created_at limit 1;
    if owner_uid is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
    key := case when array_length(sids, 1) > 1 then gen_random_uuid() end;
    foreach sid in array sids loop
      select * into sr from students where id = sid and org_id = p_org;
      if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
      if sr.end_date is not null and sr.end_date < today then raise exception 'STUDENT_ENDED: %''s lessons have ended', sr.name using errcode = 'P0001'; end if;
      select s2.name into clash from recurring_slots x join students s2 on s2.id = x.student_id
       where x.org_id = p_org and x.active and (x.stopped_from is null or x.stopped_from > today) and x.student_id = sid and x.weekday = p_weekday and x.start_time < p_end and x.end_time > p_start limit 1;
      if found then raise exception 'SLOT_CLASH: % already has a weekly lesson at that time', clash using errcode = 'P0001'; end if;
    end loop;
    foreach sid in array sids loop
      insert into recurring_slots(tutor_id, org_id, student_id, weekday, start_time, end_time, subject, rate, level, split, taught_by, session_key)
      select owner_uid, p_org, s.id, p_weekday, p_start, p_end, subj, r, s.level, 1, p_tutor, key from students s where s.id = sid and s.org_id = p_org
      returning id into new_id;
      ids := ids || new_id;
    end loop;
    insert into audit_log(org_id, actor, action, table_name, row_id, after)
    values (p_org, auth.uid(), 'staff_save_slot', 'recurring_slots', ids[1]::text,
            jsonb_build_object('added', true, 'slot_ids', ids, 'weekday', p_weekday, 'start', p_start, 'end', p_end, 'tutor', p_tutor, 'students', sids));
    -- THE TUTOR JOINS THE STUDENT'S ASSIGNED TUTORS (the centre can switch this off: lessons.auto_assign_tutors, default on, read as of today).
    -- Only ever ADDS: nobody is removed, and a tutor who is already assigned is left alone. The answer lists who was added so staff are told.
    auto := case when jsonb_typeof(org_settings_on(p_org, today) #> '{lessons,auto_assign_tutors}') = 'boolean'
                 then (org_settings_on(p_org, today) #>> '{lessons,auto_assign_tutors}')::boolean else true end;
    if p_tutor is not null and auto then
      select coalesce(m.display_name, 'Tutor') into tname from memberships m where m.id = p_tutor and m.org_id = p_org;
      foreach sid in array sids loop
        if not exists (select 1 from student_tutors x where x.org_id = p_org and x.student_id = sid and x.membership_id = p_tutor and x.active) then
          insert into student_tutors(org_id, student_id, membership_id, since, created_by) values (p_org, sid, p_tutor, today, auth.uid());
          select s.name into sname from students s where s.id = sid;
          assigned := assigned || jsonb_build_object('student_id', sid, 'student_name', sname, 'tutor_name', tname);
        end if;
      end loop;
      if jsonb_array_length(assigned) > 0 then
        insert into audit_log(org_id, actor, action, table_name, row_id, after)
        values (p_org, auth.uid(), 'staff_auto_assign_tutor', 'student_tutors', ids[1]::text, jsonb_build_object('tutor', p_tutor, 'assigned', assigned));
      end if;
    end if;
    return jsonb_build_object('slot_ids', ids, 'added', array_length(ids, 1), 'lessons_left', 0, 'assigned', assigned);
  end if;

  -- change
  if p_students is not null then raise exception 'BAD_STUDENTS: to change who is in a slot, stop it and add a new one' using errcode = 'P0001'; end if;
  select * into sl from recurring_slots where id = p_slot and org_id = p_org and active and (stopped_from is null or stopped_from > today);
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select coalesce(array_agg(x.id), '{}') into ids from recurring_slots x
   where x.org_id = p_org and x.active and (x.stopped_from is null or x.stopped_from > today) and (x.id = sl.id or (sl.session_key is not null and x.session_key = sl.session_key));
  for sid in select x.student_id from recurring_slots x where x.id = any(ids) loop
    select s2.name into clash from recurring_slots x join students s2 on s2.id = x.student_id
     where x.org_id = p_org and x.active and (x.stopped_from is null or x.stopped_from > today) and x.student_id = sid and not (x.id = any(ids)) and x.weekday = p_weekday and x.start_time < p_end and x.end_time > p_start limit 1;
    if found then raise exception 'SLOT_CLASH: % already has a weekly lesson at that time', clash using errcode = 'P0001'; end if;
  end loop;
  update recurring_slots set weekday = p_weekday, start_time = p_start, end_time = p_end, subject = subj, rate = coalesce(r, rate), taught_by = p_tutor
   where id = any(ids);
  select count(*) into made from lessons l where l.org_id = p_org and l.slot_id = any(ids) and l.lesson_date >= today and l.attendance is null and l.status <> 'cancelled';
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'staff_save_slot', 'recurring_slots', sl.id::text,
          jsonb_build_object('weekday', sl.weekday, 'start', sl.start_time, 'end', sl.end_time, 'tutor', sl.taught_by),
          jsonb_build_object('slot_ids', ids, 'weekday', p_weekday, 'start', p_start, 'end', p_end, 'tutor', p_tutor, 'rate_changed', p_rate is not null));
  return jsonb_build_object('slot_ids', ids, 'added', 0, 'lessons_left', made);
end $$;
revoke all on function public.staff_save_slot(uuid, uuid, uuid[], int, time, time, uuid, text, numeric) from public, anon;
grant execute on function public.staff_save_slot(uuid, uuid, uuid[], int, time, time, uuid, text, numeric) to authenticated;

-- ---------------------------------------------------------------- 5. the tutor's own weekly slots no longer list a slot once its stop date has come
create or replace function public.tutor_my_slots()
returns table(slot_id uuid, org_id uuid, org_name text, weekday int, start_time time, end_time time, subject text,
              student_id uuid, student_name text, student_level text, session_key uuid, timetable_editing text)
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if not exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active') then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  return query
    select sl.id, sl.org_id, o.trading_name, sl.weekday::int, sl.start_time, sl.end_time, sl.subject,
           s.id, s.name, s.level, sl.session_key,
           coalesce(org_settings_on(sl.org_id, current_date) #>> '{lessons,timetable_editing}', 'admin_only')
      from recurring_slots sl
      join memberships m on m.id = sl.taught_by and m.org_id = sl.org_id and m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active'
      join organisations o on o.id = sl.org_id and o.kind = 'centre'
      join students s on s.id = sl.student_id and s.org_id = sl.org_id
     where sl.active and (sl.stopped_from is null or sl.stopped_from > (now() at time zone o.timezone)::date)
       and (s.end_date is null or s.end_date >= (now() at time zone o.timezone)::date)
     order by sl.weekday, sl.start_time, s.name, sl.id;
end $$;

-- ---------------------------------------------------------------- 6. the lesson generator: one core, 26 weeks at a time, honours each slot's own start / stop date
create or replace function public.staff_generate_core(p_org uuid, f date, t date, skip boolean, p_slots uuid[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare res jsonb;
begin
  with days as (select d::date as d from generate_series(f, t, interval '1 day') d),
  cand as (
    select sl.id as slot_id, sl.session_key, sl.tutor_id, sl.student_id, sl.start_time, sl.end_time, sl.subject, sl.level, sl.rate, sl.split,
           days.d, st.end_date,
           (select m.id from memberships m where m.id = sl.taught_by and m.org_id = p_org and m.status <> 'disabled') as ok_tutor,
           exists (select 1 from holidays h where h.org_id = p_org and h.branch_id is null and days.d between h.starts_on and h.ends_on) as is_hol,
           exists (select 1 from lessons l where l.org_id = p_org
                    and ((l.slot_id = sl.id and l.slot_date = days.d)
                      or (l.student_id = sl.student_id and l.lesson_date = days.d and l.start_time = sl.start_time))) as there
      from recurring_slots sl
      join students st on st.id = sl.student_id and st.org_id = sl.org_id
      join days on (extract(isodow from days.d)::int - 1) = sl.weekday
     where sl.org_id = p_org and sl.active and (p_slots is null or sl.id = any(p_slots))
       and (sl.starts_on is null or days.d >= sl.starts_on) and (sl.stopped_from is null or days.d < sl.stopped_from)),
  cls as (
    select cand.*, case when end_date is not null and d > end_date then 'ended'
                        when there then 'there'
                        when is_hol and skip then 'holiday'
                        else 'new' end as kind
      from cand),
  ins as (
    insert into lessons(tutor_id, org_id, student_id, slot_id, lesson_date, slot_date, start_time, end_time, subject, level, rate, split, amount,
                        status, paid, one_off, taught_by, session_id)
    select tutor_id, p_org, student_id, slot_id, d, d, start_time, end_time, subject, level, rate, coalesce(split, 1),
           round(round(rate * (extract(epoch from (end_time - start_time)) / 3600)::numeric, 2) / greatest(coalesce(split, 1), 1), 2),
           'scheduled', false, false, ok_tutor,
           case when session_key is null then null else md5(session_key::text || d::text)::uuid end     -- the same for every student of the class on that day
      from cls where kind = 'new'
    returning id)
  select jsonb_build_object(
           'from', f, 'to', t,
           'created', (select count(*) from ins),
           'skipped', count(*) filter (where kind = 'there'),
           'holidays', count(distinct d) filter (where kind = 'holiday'),
           'ended', count(*) filter (where kind = 'ended'),
           'no_tutor', count(*) filter (where kind = 'new' and ok_tutor is null),
           'on_holiday', count(*) filter (where kind = 'new' and is_hol),
           'slots', (select count(*) from recurring_slots x where x.org_id = p_org and x.active and (x.stopped_from is null or x.stopped_from > f)))
    into res from cls;
  return res;
end $$;
revoke all on function public.staff_generate_core(uuid, date, date, boolean, uuid[]) from public, anon, authenticated;

create or replace function public.staff_generate_lessons(p_org uuid, p_from date default null, p_to date default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); f date := coalesce(p_from, today); t date; skip boolean; res jsonb;
begin
  t := coalesce(p_to, f + 27);
  if f < today then raise exception 'BAD_RANGE: lessons can''t be created for days that have passed' using errcode = 'P0001'; end if;
  if t < f or t - f > 181 then raise exception 'BAD_RANGE: create at most 26 weeks (182 days) at a time' using errcode = 'P0001'; end if;
  skip := case when jsonb_typeof(org_settings_on(p_org, today) #> '{calendar,skip_holidays}') = 'boolean'
                then (org_settings_on(p_org, today) #>> '{calendar,skip_holidays}')::boolean else true end;      -- missing = on (the default)
  perform pg_advisory_xact_lock(hashtextextended('staff_generate_lessons:' || p_org::text, 0));        -- two people pressing together: one waits, then finds nothing to add
  res := staff_generate_core(p_org, f, t, skip, null) || jsonb_build_object('days', t - f + 1);
  insert into audit_log(org_id, actor, action, table_name, row_id, after) values (p_org, auth.uid(), 'staff_generate_lessons', 'lessons', null, res);
  return res;
end $$;
revoke all on function public.staff_generate_lessons(uuid, date, date) from public, anon;
grant execute on function public.staff_generate_lessons(uuid, date, date) to authenticated;

-- ---------------------------------------------------------------- 7. stop a weekly slot FROM a chosen day (the whole class if it is one)
-- p_from: today or a day to come (three years at most). The slot (and every student of its class) stops on that day: no lesson is made for it from
-- that day on. With p_remove_future the lessons already made for those days are removed too, but ONLY those nobody has marked, paid or invoiced.
-- p_dry = true changes nothing and answers the counts: removable (not marked, paid or invoiced: what the tick-box would remove), kept (marked, paid or
-- invoiced: always stay), lessons_left (lessons from that day that would remain).
create or replace function public.staff_stop_slot_from(p_org uuid, p_slot uuid, p_from date, p_remove_future boolean default false, p_dry boolean default false)
returns jsonb language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); sl recurring_slots; ids uuid[]; allids uuid[]; rm boolean := coalesce(p_remove_future, false);
        n_free int; n_kept int; changed int := 0; removed int := 0; n_left int;
begin
  if p_from is null or p_from < today or p_from > today + 1095 then
    raise exception 'BAD_DATE: pick today or a day to come (within three years)' using errcode = 'P0001'; end if;
  select * into sl from recurring_slots where id = p_slot and org_id = p_org;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('staff_generate_lessons:' || p_org::text, 0));        -- the generator's lock: a stop and a "create lessons" never interleave
  select coalesce(array_agg(x.id), '{}') into allids from recurring_slots x
   where x.org_id = p_org and (x.id = sl.id or (sl.session_key is not null and x.session_key = sl.session_key));
  select coalesce(array_agg(x.id), '{}') into ids from recurring_slots x
   where x.id = any(allids) and x.active and (x.stopped_from is null or x.stopped_from > today);

  select count(*) filter (where b is null), count(*) filter (where b in ('MARKED', 'PAID', 'INVOICED')) into n_free, n_kept
    from (select lesson_change_blocker(l.id) as b from lessons l
           where l.org_id = p_org and l.slot_id = any(allids) and l.lesson_date >= p_from) z;
  select count(*) into n_left from lessons l where l.org_id = p_org and l.slot_id = any(allids) and l.lesson_date >= p_from;
  if p_dry then
    return jsonb_build_object('dry', true, 'stop_from', p_from, 'stopped', coalesce(array_length(ids, 1), 0), 'removable', n_free, 'kept', n_kept,
                              'lessons_left', n_left - case when rm then n_free else 0 end);
  end if;

  update recurring_slots set stopped_from = p_from, active = (p_from > today)
   where id = any(ids) and (stopped_from is distinct from p_from or active <> (p_from > today));
  get diagnostics changed = row_count;
  if rm then
    with gone as (delete from lessons l where l.org_id = p_org and l.slot_id = any(allids) and l.lesson_date >= p_from and lesson_change_blocker(l.id) is null returning l.id)
    select count(*) into removed from gone;
  end if;
  select count(*) into n_left from lessons l where l.org_id = p_org and l.slot_id = any(allids) and l.lesson_date >= p_from;
  if changed + removed > 0 then
    insert into audit_log(org_id, actor, action, table_name, row_id, after)
    values (p_org, auth.uid(), 'staff_stop_slot_from', 'recurring_slots', sl.id::text,
            jsonb_build_object('slot_ids', allids, 'stop_from', p_from, 'removed_future_lessons', rm, 'lessons_removed', removed, 'lessons_kept', n_kept));
  end if;
  return jsonb_build_object('dry', false, 'stop_from', p_from, 'stopped', changed, 'removed', removed, 'kept', n_kept, 'lessons_left', n_left);
end $$;
revoke all on function public.staff_stop_slot_from(uuid, uuid, date, boolean, boolean) from public, anon;
grant execute on function public.staff_stop_slot_from(uuid, uuid, date, boolean, boolean) to authenticated;

-- ---------------------------------------------------------------- 8. add a student to / remove a student from an existing weekly slot, from a chosen day
-- p_action 'add': the student gets their own weekly row (same day, time, tutor, subject and rate), tied to the class by the slot's session_key (a
--   single slot becomes a class of two). Lessons ALREADY made for the class from that day get a lesson for the student too (through the same last day
--   the class already has), and the class's unmarked lessons share one session_id; marked, paid or invoiced lessons are never changed. The tutor of
--   the slot joins the student's assigned tutors (lessons.auto_assign_tutors). A student already in the class = nothing happens (answered, not an error).
-- p_action 'remove': that student's row stops from the day, and their later lessons nobody has marked, paid or invoiced are removed. The last student of
--   a slot can't be removed (stop the slot instead). Nobody is taken off the assigned tutors.
-- p_dry = true changes nothing and answers the counts for the confirmation. p_from default = today; never earlier than today.
create or replace function public.staff_slot_student(p_org uuid, p_slot uuid, p_student uuid, p_action text, p_from date default null, p_dry boolean default false)
returns jsonb language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); f date := coalesce(p_from, today); sl recurring_slots; mine recurring_slots; st students;
        ids uuid[]; key uuid; clash text; new_id uuid; last_d date; skip boolean; auto boolean; assigned jsonb := '[]'::jsonb; tname text;
        n_free int := 0; n_kept int := 0; removed int := 0; made jsonb; n_dates int; owner_uid uuid;
begin
  if p_action is null or p_action not in ('add', 'remove') then raise exception 'BAD_ACTION: choose add or remove' using errcode = 'P0001'; end if;
  if f < today or f > today + 1095 then raise exception 'BAD_DATE: pick today or a day to come (within three years)' using errcode = 'P0001'; end if;
  select * into sl from recurring_slots where id = p_slot and org_id = p_org and active and (stopped_from is null or stopped_from > today);
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('staff_generate_lessons:' || p_org::text, 0));
  select coalesce(array_agg(x.id), '{}') into ids from recurring_slots x
   where x.org_id = p_org and x.active and (x.stopped_from is null or x.stopped_from > today)
     and (x.id = sl.id or (sl.session_key is not null and x.session_key = sl.session_key));

  if p_action = 'add' then
    select * into st from students where id = p_student and org_id = p_org;
    if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
    if st.end_date is not null and st.end_date < today then raise exception 'STUDENT_ENDED: %''s lessons have ended', st.name using errcode = 'P0001'; end if;
    if exists (select 1 from recurring_slots x where x.id = any(ids) and x.student_id = p_student) then
      return jsonb_build_object('dry', coalesce(p_dry, false), 'added', 0, 'already', true, 'created', 0, 'assigned', assigned, 'students', array_length(ids, 1));
    end if;
    if array_length(ids, 1) >= 30 then raise exception 'BAD_STUDENTS: a class has at most 30 students' using errcode = 'P0001'; end if;
    select s2.name into clash from recurring_slots x join students s2 on s2.id = x.student_id
     where x.org_id = p_org and x.active and (x.stopped_from is null or x.stopped_from > today) and x.student_id = p_student
       and x.weekday = sl.weekday and x.start_time < sl.end_time and x.end_time > sl.start_time limit 1;
    if found then raise exception 'SLOT_CLASH: % already has a weekly lesson at that time', clash using errcode = 'P0001'; end if;
    select max(l.lesson_date) into last_d from lessons l where l.org_id = p_org and l.slot_id = any(ids) and l.lesson_date >= f;
    last_d := least(last_d, f + 181);
    select count(distinct l.slot_date) into n_dates from lessons l
     where l.org_id = p_org and l.slot_id = any(ids) and l.lesson_date >= f and l.lesson_date <= coalesce(last_d, f) and l.status <> 'cancelled';
    if p_dry is not false then
      return jsonb_build_object('dry', true, 'added', 0, 'would_create', n_dates, 'students', array_length(ids, 1) + 1);
    end if;
    select m.user_id into owner_uid from memberships m where m.org_id = p_org and m.role = 'owner' and m.status = 'active' and m.user_id is not null order by m.created_at limit 1;
    key := coalesce(sl.session_key, gen_random_uuid());
    if sl.session_key is null then update recurring_slots set session_key = key where id = sl.id; end if;
    insert into recurring_slots(tutor_id, org_id, student_id, weekday, start_time, end_time, subject, rate, level, split, taught_by, session_key, starts_on)
    values (coalesce(owner_uid, sl.tutor_id), p_org, p_student, sl.weekday, sl.start_time, sl.end_time, sl.subject, sl.rate, st.level, 1, sl.taught_by, key,
            case when f > today then f end)
    returning id into new_id;
    -- the lessons already made for the class: the untouched ones share one session id from now on (marked / paid / invoiced ones are left as they are)
    update lessons l set session_id = md5(key::text || l.slot_date::text)::uuid
     where l.org_id = p_org and l.slot_id = any(ids) and l.lesson_date >= f and l.slot_date = l.lesson_date and l.session_id is null
       and lesson_change_blocker(l.id) is null;
    made := jsonb_build_object('created', 0);
    if last_d is not null then
      skip := case when jsonb_typeof(org_settings_on(p_org, today) #> '{calendar,skip_holidays}') = 'boolean'
                   then (org_settings_on(p_org, today) #>> '{calendar,skip_holidays}')::boolean else true end;
      made := staff_generate_core(p_org, f, last_d, skip, array[new_id]);
    end if;
    auto := case when jsonb_typeof(org_settings_on(p_org, today) #> '{lessons,auto_assign_tutors}') = 'boolean'
                 then (org_settings_on(p_org, today) #>> '{lessons,auto_assign_tutors}')::boolean else true end;
    if sl.taught_by is not null and auto
       and not exists (select 1 from student_tutors x where x.org_id = p_org and x.student_id = p_student and x.membership_id = sl.taught_by and x.active)
       and exists (select 1 from memberships m where m.id = sl.taught_by and m.org_id = p_org and m.status in ('active', 'invited')) then
      insert into student_tutors(org_id, student_id, membership_id, since, created_by) values (p_org, p_student, sl.taught_by, today, auth.uid());
      select coalesce(m.display_name, 'Tutor') into tname from memberships m where m.id = sl.taught_by;
      assigned := jsonb_build_array(jsonb_build_object('student_id', p_student, 'student_name', st.name, 'tutor_name', tname));
    end if;
    insert into audit_log(org_id, actor, action, table_name, row_id, after)
    values (p_org, auth.uid(), 'staff_slot_student_add', 'recurring_slots', new_id::text,
            jsonb_build_object('slot_ids', ids, 'student', p_student, 'from', f, 'lessons_created', (made->>'created')::int, 'assigned', assigned));
    return jsonb_build_object('dry', false, 'added', 1, 'slot_id', new_id, 'created', (made->>'created')::int, 'assigned', assigned, 'students', array_length(ids, 1) + 1);
  end if;

  -- remove
  select * into mine from recurring_slots x where x.id = any(ids) and x.student_id = p_student;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if array_length(ids, 1) < 2 then
    raise exception 'BAD_STUDENTS: this is the only student in the slot; stop the slot instead' using errcode = 'P0001'; end if;
  select count(*) filter (where b is null), count(*) filter (where b in ('MARKED', 'PAID', 'INVOICED')) into n_free, n_kept
    from (select lesson_change_blocker(l.id) as b from lessons l where l.org_id = p_org and l.slot_id = mine.id and l.lesson_date >= f) z;
  if p_dry is not false then
    return jsonb_build_object('dry', true, 'removed', 0, 'removable', n_free, 'kept', n_kept, 'students', array_length(ids, 1) - 1);
  end if;
  update recurring_slots set stopped_from = f, active = (f > today) where id = mine.id;
  with gone as (delete from lessons l where l.org_id = p_org and l.slot_id = mine.id and l.lesson_date >= f and lesson_change_blocker(l.id) is null returning l.id)
  select count(*) into removed from gone;
  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (p_org, auth.uid(), 'staff_slot_student_remove', 'recurring_slots', mine.id::text,
          jsonb_build_object('slot_ids', ids, 'student', p_student, 'from', f, 'lessons_removed', removed, 'lessons_kept', n_kept));
  return jsonb_build_object('dry', false, 'removed', 1, 'lessons_removed', removed, 'kept', n_kept, 'students', array_length(ids, 1) - 1);
end $$;
revoke all on function public.staff_slot_student(uuid, uuid, uuid, text, date, boolean) from public, anon;
grant execute on function public.staff_slot_student(uuid, uuid, uuid, text, date, boolean) to authenticated;

-- ---------------------------------------------------------------- 9. cancel the lessons already on a holiday's days
-- Whole-centre holidays only (lessons and students carry no branch). p_from..p_to up to a year; days before today are never touched. A lesson that
-- is free (not marked, paid or invoiced, not already cancelled) becomes CANCELLED with a charge of 0 (compensation 0, amount 0: nobody is billed) and the
-- note "Holiday: <name>". Marked, paid, invoiced and already cancelled lessons stay. p_dry (the DEFAULT) only counts: cancel = lessons that would be
-- cancelled, kept = marked / paid / invoiced ones left alone, earlier = free lessons before today that are not touched.
create or replace function public.staff_holiday_cancel(p_org uuid, p_from date, p_to date, p_name text default null, p_dry boolean default true)
returns jsonb language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); nm text := left(nullif(trim(coalesce(p_name, '')), ''), 60);
        n_free int; n_kept int; n_early int; ids uuid[]; done int := 0;
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 366 then
    raise exception 'BAD_RANGE: give a start and an end day, a year at most' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('staff_generate_lessons:' || p_org::text, 0));
  select count(*) filter (where b is null and d >= today), count(*) filter (where b in ('MARKED', 'PAID', 'INVOICED') and d >= today),
         count(*) filter (where b is null and d < today),
         coalesce(array_agg(id) filter (where b is null and d >= today), '{}')
    into n_free, n_kept, n_early, ids
    from (select l.id, l.lesson_date as d, lesson_change_blocker(l.id) as b from lessons l
           where l.org_id = p_org and l.lesson_date between p_from and p_to) z;
  if p_dry is not false then
    return jsonb_build_object('dry', true, 'cancel', n_free, 'kept', n_kept, 'earlier', n_early);
  end if;
  with c as (update lessons set status = 'cancelled', compensation = 0, amount = 0, charge_note = 'Holiday' || coalesce(': ' || nm, '')
              where id = any(ids) and attendance is null and status <> 'cancelled' and not paid returning id)
  select count(*) into done from c;
  if done > 0 then
    insert into audit_log(org_id, actor, action, table_name, row_id, after)
    values (p_org, auth.uid(), 'staff_holiday_cancel', 'lessons', null,
            jsonb_build_object('from', p_from, 'to', p_to, 'holiday', nm, 'lessons_cancelled', done, 'lessons_kept', n_kept));
  end if;
  return jsonb_build_object('dry', false, 'cancel', done, 'kept', n_kept, 'earlier', n_early);
end $$;
revoke all on function public.staff_holiday_cancel(uuid, date, date, text, boolean) from public, anon;
grant execute on function public.staff_holiday_cancel(uuid, date, date, text, boolean) to authenticated;

-- ---------------------------------------------------------------- 10. the People list (read)
-- The owner sees every owner, staff member and tutor; staff with manage_tutors see the tutors. `invited` = invited and not signed in yet; last_emailed_at
-- is when the last invite email went out (never the address). No email, phone, pay, payout or money of any kind. can_users = may open Users and
-- permissions to change things (owners).
create or replace function public.staff_people(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, false); me uuid := auth.uid(); is_owner boolean; rows jsonb; cname text;
begin
  is_owner := exists (select 1 from memberships m where m.org_id = p_org and m.user_id = me and m.status = 'active' and m.role = 'owner');
  if not (is_owner or org_can(p_org, 'manage_tutors')) then
    raise exception 'NOT_ALLOWED: your account can''t see the people at this centre' using errcode = '42501'; end if;
  select o.trading_name into cname from organisations o where o.id = p_org;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', m.id, 'name', coalesce(nullif(trim(m.display_name), ''), 'Unnamed'), 'role', m.role, 'status', m.status,
           'invited', (m.status = 'invited' and m.user_id is null), 'invited_at', case when m.status = 'invited' and m.user_id is null then m.created_at end,
           'last_emailed_at', case when m.status = 'invited' and m.user_id is null then l.last_sent end, 'you', (m.user_id = me))
         order by case m.role when 'owner' then 0 when 'staff' then 1 else 2 end, case m.status when 'active' then 0 when 'invited' then 1 else 2 end,
                  lower(coalesce(m.display_name, '')), m.id), '[]'::jsonb) into rows
    from memberships m
    left join lateral (select max(x.sent_at) filter (where x.status = 'sent') as last_sent from org_invite_mail_log x where x.membership_id = m.id) l on true
   where m.org_id = p_org and m.role in ('owner', 'staff', 'tutor') and (is_owner or m.role = 'tutor');
  return jsonb_build_object('today', today, 'centre', cname, 'can_users', is_owner, 'rows', rows);
end $$;
revoke all on function public.staff_people(uuid) from public, anon;
grant execute on function public.staff_people(uuid) to authenticated;

-- #####################################################################################################
-- ### PART 8 of 9 — tutors move, put back and cancel their own lessons (centre option)
-- ### source branch: claude/t6-2-tutor-moves   file: db/migration_tutor_moves.sql   undo: db/migration_tutor_moves_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T6 step 2 — tutors MOVE, REVERT and CANCEL their own lessons (centre option)             undo: migration_tutor_moves_down.sql
-- =====================================================================================================
-- Needs migration_tutor_schedule.sql (T6.1) and, through it, staff_reassign (lesson_locked_reason), staff_slots (student_tutors, recurring_slots.taught_by),
-- staff_attendance (staff_attendance_gate) and money_settings (the settings validator this file replaces). Run on the DEV project first. Safe to run twice.
--
-- THE CENTRE'S CHOICE (owner decisions 2026-11-26, T6 plan sections 1-2). All read as of the centre's TODAY (a process rule), saved under settings.lessons:
--   timetable_editing        admin_only (default, nothing changes) | tutors_direct (BUILT here) | tutors_propose (still "soon": a tutor gets NOT_ALLOWED)
--                            (the old unbuilt key tutors_own is renamed tutors_direct; no saved setting could hold it)
--   tutors_edit.postpone     yes (default) = a tutor may move a lesson and put it back          BUILT
--   tutors_edit.cancel       no  (default) = a tutor may cancel one of their lessons in advance  BUILT
--   tutors_edit.weekly_slots / generate / one_off / link     still "soon" (T6 steps 3-5); validated here so a later step needs no new validator
--   min_notice_hours         0-168, default 24: nothing changes closer than this to its start
--   max_changes_per_month    0-500, default 0 (= no limit): per tutor, per centre month; a move, a revert and a cancel each count as one change
--   notify_family            off | list_for_admin (default): staff see "tell the family" on the Home list. Sending emails is T7, still soon.
--
-- WHAT A TUTOR CAN DO (functions only; tutors still have NO table access, no policy is added anywhere):
--   tutor_postpone_lesson(lesson, date, start, reason)   move one lesson (or its whole class) to another day / start time. THE LENGTH STAYS THE SAME,
--                                                        so the lesson's price never changes and the tutor never touches money. Marks it postponed and
--                                                        keeps slot_date, exactly like the solo Calendar, so no "not logged" lesson appears at the old slot.
--   tutor_revert_lesson(lesson, reason)                  put a moved lesson back to its usual slot (the slot's weekday and time in the lesson's week)
--   tutor_cancel_lesson(lesson, reason)                  cancel in advance with NO CHARGE to the family: status cancelled, charge 0 (= "not charged"; staff
--                                                        may change it later). No make-up credit is created. Staff see an amber "changed by tutor" flag.
--
-- THE RULES (the tutor's function checks them in this order; every refusal says why in plain words, the code before the colon is for the screen):
--   NOT_FOUND       not a lesson of yours, not a student assigned to you, a solo organisation, a parent, a switched-off tutor, an unknown id: all the SAME word,
--                   so ids can't be probed (same as tutor_mark_attendance)
--   NOT_ALLOWED     the centre's setting is admin_only (or tutors_propose, not built yet)
--   SWITCH_OFF      the centre has not switched on this kind of change
--   ALREADY_MARKED / CANCELLED / LOCKED   the lesson is marked, cancelled, or closed by the centre (paid or on a current invoice: ONE word, so a tutor is never
--                   told which; staff keep their own screens for those)
--   NOT_MOVED       revert on a lesson that is at its usual time; NO_SLOT / SLOT_CHANGED: the usual slot is gone or changed (ask an admin)
--   PAST            the lesson has started or is over; TOO_LATE: closer to its start than min_notice_hours
--   LIMIT           max_changes_per_month reached
--   REASON_REQUIRED a reason (3-300 characters) is kept on record with every change
--   BAD_DATE / BAD_TIME / HOLIDAY / CLASH / NO_CHANGE   the NEW time must be in the future, within a year, inside one day, not on a centre holiday,
--                   not overlapping another of YOUR lessons, and not the time it already has (so pressing twice changes nothing twice)
--   GROUP_NOT_YOURS a class (lessons sharing a session_id) moves or cancels together, all or nothing; every lesson of it must be yours and assigned to you
-- Days and times are the centre's own (organisations.timezone), never the server's.
--
-- WHAT IS KEPT: lessons.changed_by_tutor_at / changed_by_tutor (membership) / changed_by_tutor_what (moved | reverted | cancelled) / changed_by_tutor_reason,
-- changed_from_date / changed_from_start (what it was before); one audit_log row per action (action tutor_postpone_lesson | tutor_revert_lesson |
-- tutor_cancel_lesson, with the reason); the lessons table's own audit trigger logs the row change as well. The monthly limit counts those audit rows.
--
-- STAFF SIDE: staff_tutor_changes(org) lists the last 7 days of tutor changes (needs manage_timetable): the amber "changed by tutor" chips on the
-- Timetable and the "Tutor changes" list on Home. No money in it.
-- NO MONEY anywhere a tutor can read: no returned type or key holds rate, amount, paid, compensation or *_cents (tests/sql/tutor_moves_test.sql).
-- The Supabase API refuses a DELETE / UPDATE without WHERE (pg-safeupdate): every statement below has one.
-- =====================================================================================================

-- ---------------------------------------------------------------- 1. the columns
alter table public.lessons add column if not exists changed_by_tutor_at     timestamptz;
alter table public.lessons add column if not exists changed_by_tutor        uuid;
alter table public.lessons add column if not exists changed_by_tutor_what   text;
alter table public.lessons add column if not exists changed_by_tutor_reason text;
alter table public.lessons add column if not exists changed_from_date       date;
alter table public.lessons add column if not exists changed_from_start      time;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'lessons_changed_by_tutor_what_ok') then
    alter table public.lessons add constraint lessons_changed_by_tutor_what_ok check (changed_by_tutor_what is null or changed_by_tutor_what in ('moved', 'reverted', 'cancelled'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'lessons_changed_by_tutor_same_org') then
    alter table public.lessons add constraint lessons_changed_by_tutor_same_org
      foreign key (changed_by_tutor, org_id) references public.memberships(id, org_id) on delete set null (changed_by_tutor);
  end if;
end $$;
create index if not exists lessons_changed_by_tutor on public.lessons(org_id, changed_by_tutor_at desc) where changed_by_tutor_at is not null;

-- ---------------------------------------------------------------- 2. the settings validator (money_settings' version, plus the new keys)
-- Every earlier check is kept word for word; the new block is at the end. Settings saved before this still pass (every new key is optional).
create or replace function public.org_validate_settings(s jsonb) returns void language plpgsql immutable set search_path = public as $$
declare k text; v jsonb; r record;
begin
  if coalesce((s->>'schema_version')::int, 0) <> 1 then raise exception 'Unknown settings schema_version'; end if;
  foreach k in array array['profile','calendar','billing','invoicing','payments','lessons','tutor_pay','data'] loop
    if jsonb_typeof(s->k) is distinct from 'object' then raise exception 'Settings section "%" is missing', k; end if;
  end loop;
  if (s#>>'{profile,gst_registered}')::boolean and not ((s#>>'{profile,gst_rate_bp}')::int between 0 and 5000) then
    raise exception 'GST rate must be between 0%% and 50%%'; end if;
  if s#>>'{billing,model}' not in ('prepaid_packages','fixed_in_advance','postpaid_lessons','pay_per_lesson') then
    raise exception 'Unknown billing model'; end if;
  if s#>>'{tutor_pay,mode}' not in ('off','report','full') then raise exception 'Unknown tutor pay mode'; end if;
  if s#>>'{tutor_pay,payable_when}' not in ('taught','parent_paid') then raise exception 'Unknown payable rule'; end if;
  if s#>>'{invoicing,grouping}' not in ('family','student') then raise exception 'Unknown invoice grouping'; end if;
  if s#>>'{lessons,attendance_by}' not in ('tutor','admin') then raise exception 'Unknown attendance setting'; end if;
  if s#>>'{lessons,cancellations_marked_by}' not in ('admin','tutor') then raise exception 'Unknown cancellation setting'; end if;
  if s#>>'{lessons,compensation_entered_by}' not in ('admin','tutor') then raise exception 'Unknown compensation setting'; end if;
  if s#>>'{lessons,trials_flagged_by}' not in ('admin','tutor') then raise exception 'Unknown trial setting'; end if;
  if s#>>'{lessons,attendance_window_days}' is not null and (s#>>'{lessons,attendance_window_days}' !~ '^[0-9]{1,3}$'
     or (s#>>'{lessons,attendance_window_days}')::int not between 1 and 60) then raise exception 'Attendance window must be 1-60 days'; end if;
  if not (s#>'{payments,modes}' ?| array['manual_paynow','statement_matching','hitpay','stripe']) then
    raise exception 'Pick at least one way for parents to pay'; end if;
  -- T4 S0 (centre money options). Every new key is optional, so settings saved before this migration stay valid;
  -- a key that is present must be right. assets/js/org-settings.js holds the labels and defaults (tests/org-settings.test.js compares the enums).
  if s#>>'{tutor_pay,rate_model}' is not null and s#>>'{tutor_pay,rate_model}' not in ('per_lesson','per_hour','per_student_lesson','monthly_fixed','percent_of_fee') then raise exception 'Unknown tutor pay rate'; end if;
  if s#>>'{tutor_pay,percent_base}' is not null and s#>>'{tutor_pay,percent_base}' not in ('billed_after_discounts','list_price') then raise exception 'Unknown percentage pay base'; end if;
  if s#>>'{tutor_pay,part_payments}' is not null and s#>>'{tutor_pay,part_payments}' not in ('after_full','pro_rata') then raise exception 'Unknown part-payment pay rule'; end if;
  if s#>>'{tutor_pay,cancelled_lessons}' is not null and s#>>'{tutor_pay,cancelled_lessons}' not in ('pay_if_charged','pay_rate','pay_nothing') then raise exception 'Unknown cancelled-lesson pay rule'; end if;
  if s#>>'{tutor_pay,group_count}' is not null and s#>>'{tutor_pay,group_count}' not in ('attended','enrolled') then raise exception 'Unknown group pay count'; end if;
  if s#>>'{billing,deposit,mode}' is not null and s#>>'{billing,deposit,mode}' not in ('none','fixed','percent_first_month') then raise exception 'Unknown deposit mode'; end if;
  if s#>>'{billing,deposit,due}' is not null and s#>>'{billing,deposit,due}' not in ('with_first_invoice','before_first_lesson') then raise exception 'Unknown deposit due rule'; end if;
  if s#>>'{billing,deposit,waived_by}' is not null and s#>>'{billing,deposit,waived_by}' not in ('owner','issue_invoices','nobody') then raise exception 'Unknown deposit waiver rule'; end if;
  if s#>>'{billing,deposit,release}' is not null and s#>>'{billing,deposit,release}' not in ('refund_full','refund_less_unpaid','admin_decides') then raise exception 'Unknown deposit release rule'; end if;
  if s#>>'{billing,deposit,refund_approved_by}' is not null and s#>>'{billing,deposit,refund_approved_by}' not in ('owner','staff','four_eyes') then raise exception 'Unknown deposit refund approver'; end if;
  if s#>>'{billing,late_fee,repeat}' is not null and s#>>'{billing,late_fee,repeat}' not in ('none','once','monthly') then raise exception 'Unknown late fee repeat'; end if;
  if s#>>'{billing,late_fee,type}' is not null and s#>>'{billing,late_fee,type}' not in ('fixed','percent') then raise exception 'Unknown late fee type'; end if;
  if s#>>'{billing,late_fee,show_as}' is not null and s#>>'{billing,late_fee,show_as}' not in ('next_invoice_line','own_invoice') then raise exception 'Unknown late fee placement'; end if;
  if s#>>'{billing,late_fee,waived_by}' is not null and s#>>'{billing,late_fee,waived_by}' not in ('owner','issue_invoices') then raise exception 'Unknown late fee waiver rule'; end if;
  if s#>>'{lessons,class_type}' is not null and s#>>'{lessons,class_type}' not in ('one_to_one','group','both') then raise exception 'Unknown class type'; end if;
  foreach k in array array['{billing,deposit,taxable}','{billing,deposit,top_up}','{billing,deposit,set_off_unpaid}','{billing,deposit,final_month}','{billing,trials,charged}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{billing,deposit,percent_bp}', 0, 10000, 'Deposit percentage must be between 0% and 100%'),
    ('{billing,deposit,forfeit_notice_days}', 0, 90, 'Deposit notice must be 0-90 days'),
    ('{billing,late_fee,percent_bp}', 0, 10000, 'Late fee percentage must be between 0% and 100%'),
    ('{billing,late_fee,after_days}', 0, 365, 'Late fee grace period must be 0-365 days'),
    ('{billing,late_fee,cap_cents}', 0, 100000000, 'Late fee limit must be a whole number of cents, 0 to 100000000'),
    ('{billing,late_fee,amount_cents}', 0, 100000000, 'Late fee amount must be a whole number of cents, 0 to 100000000'),
    ('{billing,one_off_fees,deposit_cents}', 0, 100000000, 'Deposit amount must be a whole number of cents, 0 to 100000000'),
    ('{profile,next_invoice_number}', 1, 999999999, 'Next invoice number must be a whole number, 1 or more')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,12}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- a percentage mode needs a real percentage (1 = 0.01%)
  if s#>>'{billing,deposit,mode}' = 'percent_first_month' and coalesce((s#>>'{billing,deposit,percent_bp}')::int, 0) < 1 then
    raise exception 'Deposit percentage must be between 0.01%% and 100%%'; end if;
  if s#>>'{billing,late_fee,type}' = 'percent' and coalesce((s#>>'{billing,late_fee,percent_bp}')::int, 0) < 1 then
    raise exception 'Late fee percentage must be between 0.01%% and 100%%'; end if;
  -- T6 step 2 (tutors change their own lessons). Every key is optional; a key that is present must be right. assets/js/org-settings.js has the labels and defaults.
  if s#>>'{lessons,timetable_editing}' is not null and s#>>'{lessons,timetable_editing}' not in ('admin_only','tutors_direct','tutors_propose') then raise exception 'Unknown timetable editing setting'; end if;
  if s#>>'{lessons,notify_family}' is not null and s#>>'{lessons,notify_family}' not in ('off','list_for_admin') then raise exception 'Unknown family notice setting'; end if;
  if s#>'{lessons,tutors_edit}' is not null and jsonb_typeof(s#>'{lessons,tutors_edit}') not in ('object','null') then raise exception 'Tutor editing switches are malformed'; end if;
  foreach k in array array['{lessons,tutors_edit,postpone}','{lessons,tutors_edit,cancel}','{lessons,tutors_edit,weekly_slots}','{lessons,tutors_edit,generate}','{lessons,tutors_edit,one_off}','{lessons,tutors_edit,link}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{lessons,min_notice_hours}', 0, 168, 'Notice before a change must be 0-168 hours'),
    ('{lessons,max_changes_per_month}', 0, 500, 'Changes per tutor per month must be 0-500 (0 = no limit)')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,4}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
end $$;

-- ---------------------------------------------------------------- 3. the one rulebook: why a lesson can't be changed by ITS tutor (null = it can)
-- Internal (the browser can't call it); the three tutor functions and tutor_my_schedule all ask it, so the screen's buttons and the database always agree.
-- p_what: 'postpone' | 'revert' | 'cancel'. Looks at auth.uid() itself. The first word is the code; 'NOT_FOUND' alone = not yours / not assigned / not a centre / unknown.
create or replace function public.tutor_change_block(p_lesson uuid, p_what text) returns text
language plpgsql stable security definer set search_path = public as $$
declare me uuid := auth.uid(); l lessons; tz text; today date; cfg jsonb; mode text; sw boolean; notice int; mx int; used int; start_ts timestamptz; lk text;
        sl recurring_slots; tdate date;
begin
  if me is null or p_what not in ('postpone', 'revert', 'cancel') then return 'NOT_FOUND'; end if;
  select * into l from lessons where id = p_lesson;
  if not found or l.taught_by is null then return 'NOT_FOUND'; end if;
  select o.timezone into tz from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
   where m.id = l.taught_by and m.org_id = l.org_id and m.user_id = me and m.role = 'tutor' and m.status = 'active';
  if tz is null then return 'NOT_FOUND'; end if;
  if not exists (select 1 from student_tutors st where st.org_id = l.org_id and st.student_id = l.student_id and st.membership_id = l.taught_by and st.active) then
    return 'NOT_FOUND'; end if;
  today := (now() at time zone tz)::date;
  cfg := org_settings_on(l.org_id, today);
  mode := coalesce(cfg #>> '{lessons,timetable_editing}', 'admin_only');
  if mode <> 'tutors_direct' then
    return 'NOT_ALLOWED: at this centre the admins change the timetable. Ask them to change this lesson'; end if;
  sw := case when p_what = 'cancel' then coalesce((cfg #>> '{lessons,tutors_edit,cancel}')::boolean, false)
             else coalesce((cfg #>> '{lessons,tutors_edit,postpone}')::boolean, true) end;
  if not sw then
    return 'SWITCH_OFF: this centre doesn''t let tutors ' || case when p_what = 'cancel' then 'cancel' else 'move' end || ' lessons. Ask an admin'; end if;
  lk := lesson_locked_reason(l.id);
  if lk is not null then
    return case lk when 'MARKED'    then 'ALREADY_MARKED: this lesson is already marked, so it can''t be changed here. Ask an admin'
                   when 'CANCELLED' then 'CANCELLED: this lesson was cancelled'
                   else                  'LOCKED: your centre has already closed this lesson, so it can''t be changed here. Ask an admin' end;   -- one word for every closed reason: a tutor is never told which
  end if;
  if p_what = 'revert' then
    if not l.postponed then return 'NOT_MOVED: this lesson is already at its usual time'; end if;
    select * into sl from recurring_slots x where x.id = l.slot_id and x.org_id = l.org_id;
    if not found or l.slot_date is null or not sl.active then
      return 'NO_SLOT: this lesson has no usual slot to go back to. Ask an admin'; end if;
    if sl.taught_by is distinct from l.taught_by or sl.end_time - sl.start_time <> l.end_time - l.start_time then
      return 'SLOT_CHANGED: the usual slot has changed since this lesson was moved. Ask an admin'; end if;
  end if;
  start_ts := (l.lesson_date + l.start_time) at time zone tz;
  if start_ts <= now() then return 'PAST: this lesson has already started'; end if;
  notice := coalesce((cfg #>> '{lessons,min_notice_hours}')::int, 24);
  if start_ts < now() + make_interval(hours => notice) then
    return 'TOO_LATE: a lesson can only be changed ' || notice || ' hour' || case when notice = 1 then '' else 's' end || ' or more before it starts. Ask an admin'; end if;
  mx := coalesce((cfg #>> '{lessons,max_changes_per_month}')::int, 0);
  if mx > 0 then
    select count(*) into used from audit_log a
     where a.org_id = l.org_id and a.actor = me and a.action in ('tutor_postpone_lesson', 'tutor_revert_lesson', 'tutor_cancel_lesson')
       and a.at >= date_trunc('month', now() at time zone tz) at time zone tz;
    if used >= mx then
      return 'LIMIT: you have used your ' || mx || ' schedule change' || case when mx = 1 then '' else 's' end || ' for this month. Ask an admin'; end if;
  end if;
  return null;
end $$;

-- ---------------------------------------------------------------- 4. the one worker behind the three tutor functions
-- p_what: 'postpone' | 'revert' | 'cancel'. A class (lessons sharing a session_id) is one action, all or nothing. Internal.
create or replace function public.tutor_change_apply(p_lesson uuid, p_what text, p_date date, p_start time, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); l lessons; x lessons; tz text; today date; why text := nullif(trim(coalesce(p_reason, '')), ''); blk text;
        ids uuid[]; sid uuid; sl recurring_slots; nd date; ns time; ne time; hol text; clash text; before_j jsonb := '[]'::jsonb; after_j jsonb := '[]'::jsonb;
        grp boolean; what_done text := case p_what when 'postpone' then 'moved' when 'revert' then 'reverted' else 'cancelled' end;
begin
  if me is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into l from lessons where id = p_lesson;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  blk := tutor_change_block(l.id, p_what);
  if blk is not null then
    if blk = 'NOT_FOUND' then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
    raise exception '%', blk using errcode = 'P0001';
  end if;
  select o.timezone into tz from organisations o where o.id = l.org_id;
  today := (now() at time zone tz)::date;
  if why is null or length(why) < 3 then raise exception 'REASON_REQUIRED: say why (a few words). It is kept on record for the centre' using errcode = 'P0001'; end if;
  if length(why) > 300 then raise exception 'TOO_LONG: keep the reason under 300 characters' using errcode = 'P0001'; end if;
  if p_what = 'postpone' then
    if p_date is null or p_start is null then raise exception 'BAD_DATE: pick a date and a start time' using errcode = 'P0001'; end if;
    if p_date > today + 365 then raise exception 'BAD_DATE: pick a date within the next year' using errcode = 'P0001'; end if;
  end if;

  -- the lesson, or its whole class (same session_id): all or nothing, every one of them must be the caller's own
  select coalesce(array_agg(y.id order by y.id), array[l.id]) into ids from lessons y
   where y.org_id = l.org_id and (y.id = l.id or (l.session_id is not null and y.session_id = l.session_id));
  grp := array_length(ids, 1) > 1;
  perform 1 from lessons y where y.id = any(ids) order by y.id for update;
  foreach sid in array ids loop
    if sid <> l.id then
      blk := tutor_change_block(sid, p_what);
      if blk = 'NOT_FOUND' then
        raise exception 'GROUP_NOT_YOURS: this lesson is part of a class that includes lessons that aren''t yours. Ask an admin' using errcode = 'P0001'; end if;
      if blk is not null then raise exception '% (it is part of a class that changes together)', blk using errcode = 'P0001'; end if;
    end if;
  end loop;

  for x in select * from lessons y where y.id = any(ids) order by y.id loop
    before_j := before_j || jsonb_build_object('lesson_id', x.id, 'lesson_date', x.lesson_date, 'start_time', x.start_time, 'end_time', x.end_time,
                                                'postponed', x.postponed, 'status', x.status);
    if p_what = 'cancel' then
      update lessons set status = 'cancelled', compensation = 0, changed_by_tutor_at = now(), changed_by_tutor = x.taught_by,
             changed_by_tutor_what = 'cancelled', changed_by_tutor_reason = why, changed_from_date = x.lesson_date, changed_from_start = x.start_time
       where id = x.id;
    else
      if p_what = 'postpone' then
        nd := p_date; ns := p_start;
      else
        select * into sl from recurring_slots z where z.id = x.slot_id and z.org_id = x.org_id;
        nd := x.slot_date + (sl.weekday - (extract(isodow from x.slot_date)::int - 1)); ns := sl.start_time;     -- the slot's own day, in the week of the occurrence
      end if;
      if ((nd + ns) + (x.end_time - x.start_time))::date <> nd then
        raise exception 'BAD_TIME: the lesson would run past midnight. Pick an earlier start' using errcode = 'P0001'; end if;
      ne := ns + (x.end_time - x.start_time);
      if nd = x.lesson_date and ns = x.start_time then
        raise exception 'NO_CHANGE: the lesson is already at that time' using errcode = 'P0001'; end if;
      if ((nd + ns) at time zone tz) <= now() then
        raise exception 'BAD_DATE: that time has already passed. Pick a later one' using errcode = 'P0001'; end if;
      select h.name into hol from holidays h where h.org_id = x.org_id and h.branch_id is null and nd between h.starts_on and h.ends_on order by h.starts_on, h.name limit 1;
      if hol is not null then raise exception 'HOLIDAY: % is a holiday at this centre. Pick another day', hol using errcode = 'P0001'; end if;
      select s.name into clash from lessons y join students s on s.id = y.student_id and s.org_id = y.org_id
       where y.org_id = x.org_id and y.taught_by = x.taught_by and not (y.id = any(ids)) and y.status <> 'cancelled'
         and y.lesson_date = nd and y.start_time < ne and y.end_time > ns order by y.start_time, y.id limit 1;
      if clash is not null then raise exception 'CLASH: you already teach % at that time. Pick another time', clash using errcode = 'P0001'; end if;
      update lessons set lesson_date = nd, start_time = ns, end_time = ne, postponed = (p_what = 'postpone'),
             changed_by_tutor_at = now(), changed_by_tutor = x.taught_by, changed_by_tutor_what = what_done, changed_by_tutor_reason = why,
             changed_from_date = x.lesson_date, changed_from_start = x.start_time
       where id = x.id;
    end if;
  end loop;

  select coalesce(jsonb_agg(jsonb_build_object('lesson_id', y.id, 'lesson_date', y.lesson_date, 'start_time', y.start_time, 'end_time', y.end_time,
                                               'postponed', y.postponed, 'status', y.status) order by y.id), '[]'::jsonb) into after_j from lessons y where y.id = any(ids);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (l.org_id, me, 'tutor_' || p_what || '_lesson', 'lessons', l.id::text, jsonb_build_object('lessons', before_j),
          jsonb_build_object('lessons', after_j, 'reason', why, 'what', what_done));
  select * into x from lessons where id = l.id;
  return jsonb_build_object('lesson_id', l.id, 'lessons', array_length(ids, 1), 'what', what_done, 'lesson_date', x.lesson_date,
                            'start_time', x.start_time, 'end_time', x.end_time, 'cancelled', (x.status = 'cancelled'));
end $$;

-- ---------------------------------------------------------------- 5. the three functions a tutor calls
create or replace function public.tutor_postpone_lesson(p_lesson uuid, p_date date, p_start time, p_reason text default null) returns jsonb
language sql security definer set search_path = public as $$ select public.tutor_change_apply(p_lesson, 'postpone', p_date, p_start, p_reason) $$;
create or replace function public.tutor_revert_lesson(p_lesson uuid, p_reason text default null) returns jsonb
language sql security definer set search_path = public as $$ select public.tutor_change_apply(p_lesson, 'revert', null, null, p_reason) $$;
create or replace function public.tutor_cancel_lesson(p_lesson uuid, p_reason text default null) returns jsonb
language sql security definer set search_path = public as $$ select public.tutor_change_apply(p_lesson, 'cancel', null, null, p_reason) $$;

-- ---------------------------------------------------------------- 6. tutor_my_schedule, now with the buttons a lesson may show
-- Same answer as T6.1 plus, per lesson: can_postpone, can_revert, can_cancel (yes/no, from the same rulebook the functions use) and change_block (the
-- code of the reason a button is missing when the centre HAS switched it on, e.g. TOO_LATE; null otherwise); per centre: editing (the setting),
-- can_postpone / can_cancel (the centre's switches), min_notice_hours, max_changes_per_month and changes_left (null = no limit). No money.
drop function if exists public.tutor_my_schedule(date, date);
create or replace function public.tutor_my_schedule(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare orgs jsonb; lessons jsonb; hols jsonb; today date;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if not exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active') then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then
    raise exception 'BAD_RANGE: ask for at most 62 days' using errcode = 'P0001'; end if;

  select jsonb_agg(jsonb_build_object('org_id', o.id, 'name', o.trading_name, 'today', (now() at time zone o.timezone)::date,
                                      'timetable_editing', c.mode,
                                      'can_edit', (c.mode = 'tutors_direct' and (c.sw_postpone or c.sw_cancel)),
                                      'can_postpone', (c.mode = 'tutors_direct' and c.sw_postpone), 'can_cancel', (c.mode = 'tutors_direct' and c.sw_cancel),
                                      'min_notice_hours', c.notice, 'max_changes_per_month', c.mx,
                                      'changes_left', case when c.mx > 0 and c.mode = 'tutors_direct' then greatest(0, c.mx - (
                                          select count(*) from audit_log a where a.org_id = o.id and a.actor = auth.uid()
                                             and a.action in ('tutor_postpone_lesson', 'tutor_revert_lesson', 'tutor_cancel_lesson')
                                             and a.at >= date_trunc('month', now() at time zone o.timezone) at time zone o.timezone)) end)
                      order by o.trading_name, o.id),
         min((now() at time zone o.timezone)::date)
    into orgs, today
    from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
    cross join lateral (select org_settings_on(o.id, (now() at time zone o.timezone)::date) as s) cfg
    cross join lateral (select coalesce(cfg.s #>> '{lessons,timetable_editing}', 'admin_only') as mode,
                               coalesce((cfg.s #>> '{lessons,tutors_edit,postpone}')::boolean, true) as sw_postpone,
                               coalesce((cfg.s #>> '{lessons,tutors_edit,cancel}')::boolean, false) as sw_cancel,
                               coalesce((cfg.s #>> '{lessons,min_notice_hours}')::int, 24) as notice,
                               coalesce((cfg.s #>> '{lessons,max_changes_per_month}')::int, 0) as mx) c
   where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active';

  select coalesce(jsonb_agg(jsonb_build_object(
           'lesson_id', l.id, 'org_id', l.org_id, 'org_name', o.trading_name,
           'student_id', s.id, 'student_name', s.name, 'student_level', s.level,
           'parent_contact', case when coalesce((org_settings_on(l.org_id, current_date) #>> '{lessons,tutors_see_parent_contact}')::boolean, false) then s.contact end,
           'lesson_date', l.lesson_date, 'start_time', l.start_time, 'end_time', l.end_time,
           'minutes', (extract(epoch from (l.end_time - l.start_time)) / 60)::int, 'subject', l.subject,
           'trial', l.trial, 'attendance', l.attendance, 'status', l.status, 'cancelled', (l.status = 'cancelled'),
           'postponed', l.postponed, 'covering', (l.covered_for is not null), 'online_link', s.online_link,
           'holiday', (select h.name from holidays h where h.org_id = l.org_id and h.branch_id is null
                        and l.lesson_date between h.starts_on and h.ends_on order by h.starts_on, h.name limit 1),
           'can_postpone', (b.postpone is null), 'can_revert', (b.revert is null), 'can_cancel', (b.cancel is null),
           'change_block', case when b.postpone is null or b.cancel is null then null
                                when b.postpone not like 'NOT_ALLOWED%' and b.postpone not like 'SWITCH_OFF%' then split_part(b.postpone, ':', 1)
                                when b.cancel not like 'NOT_ALLOWED%' and b.cancel not like 'SWITCH_OFF%' then split_part(b.cancel, ':', 1) end,
           'changed_by_you', (l.changed_by_tutor_what), 'class_size', (select count(*)::int from lessons y where l.session_id is not null and y.org_id = l.org_id and y.session_id = l.session_id)
         ) order by l.lesson_date, l.start_time, s.name, l.id), '[]'::jsonb)
    into lessons
    from lessons l
    join memberships m on m.id = l.taught_by and m.org_id = l.org_id and m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active'
    join organisations o on o.id = l.org_id and o.kind = 'centre'
    join students s on s.id = l.student_id and s.org_id = l.org_id
    cross join lateral (select tutor_change_block(l.id, 'postpone') as postpone, tutor_change_block(l.id, 'revert') as revert, tutor_change_block(l.id, 'cancel') as cancel) b
   where l.lesson_date between p_from and p_to;

  select coalesce(jsonb_agg(jsonb_build_object('org_id', h.org_id, 'name', h.name, 'starts_on', h.starts_on, 'ends_on', h.ends_on)
                            order by h.starts_on, h.name, h.id), '[]'::jsonb)
    into hols
    from holidays h
   where h.branch_id is null and h.starts_on <= p_to and h.ends_on >= p_from
     and exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.org_id = h.org_id and m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active');

  return jsonb_build_object('today', today, 'from', p_from, 'to', p_to, 'orgs', orgs, 'lessons', lessons, 'holidays', hols);
end $$;

-- ---------------------------------------------------------------- 7. staff: what tutors changed in the last 7 days
-- Needs manage_timetable (NOT_FOUND for strangers, tutors, parents, solo organisations; NOT_ALLOWED for staff without that permission).
-- One row per lesson, newest first, at most 100. NO MONEY. `tell_family` = the centre's notify_family is list_for_admin.
create or replace function public.staff_tutor_changes(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_attendance_gate(p_org, false); rows jsonb; tell boolean;
begin
  if not org_can(p_org, 'manage_timetable') then
    raise exception 'NOT_ALLOWED: your account can''t see timetable changes at this centre' using errcode = '42501'; end if;
  tell := coalesce(org_settings_on(p_org, today) #>> '{lessons,notify_family}', 'list_for_admin') = 'list_for_admin';
  select coalesce(jsonb_agg(jsonb_build_object(
           'lesson_id', x.id, 'what', x.changed_by_tutor_what, 'changed_at', x.changed_by_tutor_at, 'reason', x.changed_by_tutor_reason,
           'tutor_id', x.changed_by_tutor,
           'tutor_name', case when t.id is null or t.status = 'disabled' then 'Former tutor' else coalesce(t.display_name, 'Tutor') end,
           'student_id', s.id, 'student_name', s.name, 'subject', x.subject,
           'lesson_date', x.lesson_date, 'start_time', x.start_time, 'end_time', x.end_time,
           'from_date', x.changed_from_date, 'from_start', x.changed_from_start, 'cancelled', (x.status = 'cancelled'), 'tell_family', tell)
           order by x.changed_by_tutor_at desc, x.id), '[]'::jsonb)
    into rows
    from (select * from lessons y where y.org_id = p_org and y.changed_by_tutor_at >= now() - interval '7 days'
           order by y.changed_by_tutor_at desc, y.id limit 100) x
    join students s on s.id = x.student_id and s.org_id = x.org_id
    left join memberships t on t.id = x.changed_by_tutor and t.org_id = x.org_id;
  return jsonb_build_object('today', today, 'days', 7, 'tell_family', tell, 'rows', rows);
end $$;

-- ---------------------------------------------------------------- who may call what
do $$
declare f text;
begin
  foreach f in array array['tutor_postpone_lesson(uuid,date,time,text)', 'tutor_revert_lesson(uuid,text)', 'tutor_cancel_lesson(uuid,text)',
                           'tutor_my_schedule(date,date)', 'staff_tutor_changes(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['tutor_change_block(uuid,text)', 'tutor_change_apply(uuid,text,date,time,text)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

-- #####################################################################################################
-- ### PART 9 of 9 — staff add past lessons (backfill), centre setting lessons.backfill_allowed_days
-- ### source branch: claude/t3-10-past-lessons   file: db/migration_past_lessons.sql   undo: db/migration_past_lessons_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T3.10 — centre staff ADD PAST LESSONS (backfill)                                          undo: migration_past_lessons_down.sql
-- =====================================================================================================
-- Needs migration_tutor_moves.sql (the settings validator this file replaces) and, through the chain, staff_slots (staff_slots_gate,
-- recurring_slots.taught_by), staff_attendance (the attendance guard and stamp), centre_invoice_run (how attended lessons are invoiced).
-- Run on the DEV project first. Safe to run twice. ADD-ONLY apart from the validator: four functions, no table or column is touched.
--
-- THE PROBLEM. "Create lessons" (staff_generate_lessons) only builds lessons from today on, so a student who started last week can't be invoiced for
-- lessons already taught. Staff now add them by hand, with a reason, and mark them attended in the same step; attended lessons are what the
-- invoice run bills, so they flow into the next run like any other lesson (and a deposit is raised for a never-invoiced student as designed).
--
-- THE CENTRE'S CHOICE (a process rule, read as of the centre's TODAY; saved under settings.lessons):
--   backfill_allowed_days   0-366, default 31: how far back staff may add. 0 = switched off (the functions say so in plain words).
-- Settings saved before this stay valid: the key is optional and a missing key means 31.
--
-- WHO MAY CALL (same words as the other staff screens)
--   an active OWNER, or STAFF with manage_timetable.  A tutor, a parent, switched-off staff, a stranger, a solo organisation and an unknown id all get
--   the SAME word, NOT_FOUND, so ids can't be probed; staff WITHOUT manage_timetable get NOT_ALLOWED. Solo tutors never reach these functions.
--
-- THE FOUR FUNCTIONS
--   staff_past_lessons_options(org, student)                      what the form needs: the window, the student's weekly pattern, tutors, last price, closed fee months
--   staff_past_lessons_pattern(org, student, from, to)            the dates of the student's weekly slots in a past range, as ready-made items (one per lesson)
--   staff_past_lessons_preview(org, student, tutor, items, confirm_holidays, allow_closed_month)   the list with a verdict per row and a count; writes NOTHING
--   staff_add_past_lessons(org, student, tutor, items, reason, mark_attended, remarks, confirm_holidays, allow_closed_month)   creates them
--   An item is {date, start, end, rate?, subject?} (rate = S$ per hour; missing = the student's weekly slot at that time, else their latest lesson's rate;
--   staff can always type another price, since staff already set prices). At most 62 lessons at a time, ONE student per call.
--
-- THE RULES (the same checks run in the preview and in the add; the add is ALL OR NOTHING: if one row is refused nothing is made)
--   BACKFILL_OFF         the centre's setting is 0
--   NOT_PAST             only days BEFORE today (the centre's own calendar day): today and later are made by "Create lessons"
--   TOO_OLD              older than today minus backfill_allowed_days
--   BEFORE_STUDENT_START older than the day the student was added minus backfill_allowed_days
--   AFTER_END            after the student's "lessons run until" date
--   BEFORE_BILLING_START before the centre's "billing starts from" date (setting billing.starts_from, import stage A). That setting isn't on this database
--                        until stage A is applied: this file looks for org_billing_start(org) at run time and ignores it when absent, then respects it
--                        the moment it exists. No change is needed here when stage A is applied.
--   FEE_MONTH_CLOSED     the month's platform fee is already recorded (a fee snapshot exists for any LATER month, because the fee of month M+1 is
--                        counted from the students of month M). Staff are refused; the OWNER may pass allow_closed_month (a reason is always needed),
--                        and the answer says the fee month was already closed (its fee is never recomputed).
--   HOLIDAY              a whole-centre holiday: refused unless staff confirm (confirm_holidays). Branch holidays are ignored (students carry no branch).
--   CLASH                the student already has a lesson at an overlapping time (a lesson cancelled by staff with no mark doesn't count). Stricter than "same
--                        student and tutor": one student can't be in two lessons at once, so a different tutor clashes too.
--   (already there)      the same student, tutor, day and start time = skipped, never an error and never doubled: calling twice creates nothing twice,
--                        and the same row twice in one call counts once. The call takes a per-centre lock like the generator.
--   REASON_REQUIRED      a written reason (1-500 characters) on every add.
--   REMARKS_REQUIRED     marking attended follows the centre's lessons.remarks.required, exactly like staff_mark_attendance.
-- A lesson made here is a manual lesson (one_off true, no weekly slot), filed under the centre owner's login like every centre row, scheduled for the
-- chosen tutor; when marked attended in the same step it goes through the normal stamp (status done, marked by the person who clicked, at the time they
-- clicked). Prices follow the generator: amount = rate x hours, rounded to the cent. Each lesson gets its own audit row (action staff_add_past_lesson)
-- carrying the reason. Money is returned only to people who may add (manage_timetable), as everywhere on the staff screens.
-- =====================================================================================================

-- ---------------------------------------------------------------- 1. the settings validator (tutor_moves' version, plus the new key at the end)
create or replace function public.org_validate_settings(s jsonb) returns void language plpgsql immutable set search_path = public as $$
declare k text; v jsonb; r record;
begin
  if coalesce((s->>'schema_version')::int, 0) <> 1 then raise exception 'Unknown settings schema_version'; end if;
  foreach k in array array['profile','calendar','billing','invoicing','payments','lessons','tutor_pay','data'] loop
    if jsonb_typeof(s->k) is distinct from 'object' then raise exception 'Settings section "%" is missing', k; end if;
  end loop;
  if (s#>>'{profile,gst_registered}')::boolean and not ((s#>>'{profile,gst_rate_bp}')::int between 0 and 5000) then
    raise exception 'GST rate must be between 0%% and 50%%'; end if;
  if s#>>'{billing,model}' not in ('prepaid_packages','fixed_in_advance','postpaid_lessons','pay_per_lesson') then
    raise exception 'Unknown billing model'; end if;
  if s#>>'{tutor_pay,mode}' not in ('off','report','full') then raise exception 'Unknown tutor pay mode'; end if;
  if s#>>'{tutor_pay,payable_when}' not in ('taught','parent_paid') then raise exception 'Unknown payable rule'; end if;
  if s#>>'{invoicing,grouping}' not in ('family','student') then raise exception 'Unknown invoice grouping'; end if;
  if s#>>'{lessons,attendance_by}' not in ('tutor','admin') then raise exception 'Unknown attendance setting'; end if;
  if s#>>'{lessons,cancellations_marked_by}' not in ('admin','tutor') then raise exception 'Unknown cancellation setting'; end if;
  if s#>>'{lessons,compensation_entered_by}' not in ('admin','tutor') then raise exception 'Unknown compensation setting'; end if;
  if s#>>'{lessons,trials_flagged_by}' not in ('admin','tutor') then raise exception 'Unknown trial setting'; end if;
  if s#>>'{lessons,attendance_window_days}' is not null and (s#>>'{lessons,attendance_window_days}' !~ '^[0-9]{1,3}$'
     or (s#>>'{lessons,attendance_window_days}')::int not between 1 and 60) then raise exception 'Attendance window must be 1-60 days'; end if;
  if not (s#>'{payments,modes}' ?| array['manual_paynow','statement_matching','hitpay','stripe']) then
    raise exception 'Pick at least one way for parents to pay'; end if;
  -- T4 S0 (centre money options). Every new key is optional, so settings saved before this migration stay valid;
  -- a key that is present must be right. assets/js/org-settings.js holds the labels and defaults (tests/org-settings.test.js compares the enums).
  if s#>>'{tutor_pay,rate_model}' is not null and s#>>'{tutor_pay,rate_model}' not in ('per_lesson','per_hour','per_student_lesson','monthly_fixed','percent_of_fee') then raise exception 'Unknown tutor pay rate'; end if;
  if s#>>'{tutor_pay,percent_base}' is not null and s#>>'{tutor_pay,percent_base}' not in ('billed_after_discounts','list_price') then raise exception 'Unknown percentage pay base'; end if;
  if s#>>'{tutor_pay,part_payments}' is not null and s#>>'{tutor_pay,part_payments}' not in ('after_full','pro_rata') then raise exception 'Unknown part-payment pay rule'; end if;
  if s#>>'{tutor_pay,cancelled_lessons}' is not null and s#>>'{tutor_pay,cancelled_lessons}' not in ('pay_if_charged','pay_rate','pay_nothing') then raise exception 'Unknown cancelled-lesson pay rule'; end if;
  if s#>>'{tutor_pay,group_count}' is not null and s#>>'{tutor_pay,group_count}' not in ('attended','enrolled') then raise exception 'Unknown group pay count'; end if;
  if s#>>'{billing,deposit,mode}' is not null and s#>>'{billing,deposit,mode}' not in ('none','fixed','percent_first_month') then raise exception 'Unknown deposit mode'; end if;
  if s#>>'{billing,deposit,due}' is not null and s#>>'{billing,deposit,due}' not in ('with_first_invoice','before_first_lesson') then raise exception 'Unknown deposit due rule'; end if;
  if s#>>'{billing,deposit,waived_by}' is not null and s#>>'{billing,deposit,waived_by}' not in ('owner','issue_invoices','nobody') then raise exception 'Unknown deposit waiver rule'; end if;
  if s#>>'{billing,deposit,release}' is not null and s#>>'{billing,deposit,release}' not in ('refund_full','refund_less_unpaid','admin_decides') then raise exception 'Unknown deposit release rule'; end if;
  if s#>>'{billing,deposit,refund_approved_by}' is not null and s#>>'{billing,deposit,refund_approved_by}' not in ('owner','staff','four_eyes') then raise exception 'Unknown deposit refund approver'; end if;
  if s#>>'{billing,late_fee,repeat}' is not null and s#>>'{billing,late_fee,repeat}' not in ('none','once','monthly') then raise exception 'Unknown late fee repeat'; end if;
  if s#>>'{billing,late_fee,type}' is not null and s#>>'{billing,late_fee,type}' not in ('fixed','percent') then raise exception 'Unknown late fee type'; end if;
  if s#>>'{billing,late_fee,show_as}' is not null and s#>>'{billing,late_fee,show_as}' not in ('next_invoice_line','own_invoice') then raise exception 'Unknown late fee placement'; end if;
  if s#>>'{billing,late_fee,waived_by}' is not null and s#>>'{billing,late_fee,waived_by}' not in ('owner','issue_invoices') then raise exception 'Unknown late fee waiver rule'; end if;
  if s#>>'{lessons,class_type}' is not null and s#>>'{lessons,class_type}' not in ('one_to_one','group','both') then raise exception 'Unknown class type'; end if;
  foreach k in array array['{billing,deposit,taxable}','{billing,deposit,top_up}','{billing,deposit,set_off_unpaid}','{billing,deposit,final_month}','{billing,trials,charged}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{billing,deposit,percent_bp}', 0, 10000, 'Deposit percentage must be between 0% and 100%'),
    ('{billing,deposit,forfeit_notice_days}', 0, 90, 'Deposit notice must be 0-90 days'),
    ('{billing,late_fee,percent_bp}', 0, 10000, 'Late fee percentage must be between 0% and 100%'),
    ('{billing,late_fee,after_days}', 0, 365, 'Late fee grace period must be 0-365 days'),
    ('{billing,late_fee,cap_cents}', 0, 100000000, 'Late fee limit must be a whole number of cents, 0 to 100000000'),
    ('{billing,late_fee,amount_cents}', 0, 100000000, 'Late fee amount must be a whole number of cents, 0 to 100000000'),
    ('{billing,one_off_fees,deposit_cents}', 0, 100000000, 'Deposit amount must be a whole number of cents, 0 to 100000000'),
    ('{profile,next_invoice_number}', 1, 999999999, 'Next invoice number must be a whole number, 1 or more')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,12}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- a percentage mode needs a real percentage (1 = 0.01%)
  if s#>>'{billing,deposit,mode}' = 'percent_first_month' and coalesce((s#>>'{billing,deposit,percent_bp}')::int, 0) < 1 then
    raise exception 'Deposit percentage must be between 0.01%% and 100%%'; end if;
  if s#>>'{billing,late_fee,type}' = 'percent' and coalesce((s#>>'{billing,late_fee,percent_bp}')::int, 0) < 1 then
    raise exception 'Late fee percentage must be between 0.01%% and 100%%'; end if;
  -- T6 step 2 (tutors change their own lessons). Every key is optional; a key that is present must be right. assets/js/org-settings.js has the labels and defaults.
  if s#>>'{lessons,timetable_editing}' is not null and s#>>'{lessons,timetable_editing}' not in ('admin_only','tutors_direct','tutors_propose') then raise exception 'Unknown timetable editing setting'; end if;
  if s#>>'{lessons,notify_family}' is not null and s#>>'{lessons,notify_family}' not in ('off','list_for_admin') then raise exception 'Unknown family notice setting'; end if;
  if s#>'{lessons,tutors_edit}' is not null and jsonb_typeof(s#>'{lessons,tutors_edit}') not in ('object','null') then raise exception 'Tutor editing switches are malformed'; end if;
  foreach k in array array['{lessons,tutors_edit,postpone}','{lessons,tutors_edit,cancel}','{lessons,tutors_edit,weekly_slots}','{lessons,tutors_edit,generate}','{lessons,tutors_edit,one_off}','{lessons,tutors_edit,link}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{lessons,min_notice_hours}', 0, 168, 'Notice before a change must be 0-168 hours'),
    ('{lessons,max_changes_per_month}', 0, 500, 'Changes per tutor per month must be 0-500 (0 = no limit)')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,4}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- T3.10 (staff add PAST lessons). Optional; a key that is present must be right. assets/js/org-settings.js has the label and default (31).
  v := s #> '{lessons,backfill_allowed_days}';
  if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,3}$'
       then (v#>>'{}')::bigint between 0 and 366 else false end) then
    raise exception 'Days staff may add past lessons must be 0-366 (0 = off)'; end if;
end $$;

-- ---------------------------------------------------------------- 2. the one rulebook (internal): a verdict for every item
-- p_today is the centre's own today (from the gate). Returns {"allowed_days": n, "rows": [ {idx, date, start, end, minutes, rate, amount, amount_cents,
-- subject, state: new|there|refused, code, message, holiday, fee_month_closed} ]}. The caller has already checked who the person is and the tutor.
create or replace function public.staff_past_lessons_plan(p_org uuid, p_student uuid, p_tutor uuid, p_items jsonb, p_confirm_holidays boolean,
                                                          p_allow_closed boolean, p_today date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare cfg jsonb := org_settings_on(p_org, p_today); allowed int; st students; tz text; created date; bstart date; lastl lessons; sl recurring_slots;
        it jsonb; i int := 0; d date; s time; e time; mins int; v_rate numeric; subj text; amt numeric; code text; msg text; hol boolean; closed boolean;
        ex_id uuid; ex_start time; ex_end time; ex_tname text; ex_exact boolean; seen text[] := '{}'; k text; rows jsonb := '[]'::jsonb; stt text; raw text; hname text;
begin
  allowed := coalesce((cfg #>> '{lessons,backfill_allowed_days}')::int, 31);
  if allowed < 1 then
    raise exception 'BACKFILL_OFF: this centre hasn''t switched on adding past lessons (Settings, Lessons: "days staff may add past lessons")' using errcode = 'P0001'; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) < 1 then
    raise exception 'BAD_ITEMS: pick at least one lesson' using errcode = 'P0001'; end if;
  if jsonb_array_length(p_items) > 62 then
    raise exception 'BAD_ITEMS: add at most 62 lessons at a time' using errcode = 'P0001'; end if;
  select * into st from students where id = p_student and org_id = p_org;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select o.timezone into tz from organisations o where o.id = p_org;
  created := (st.created_at at time zone tz)::date;
  if to_regprocedure('public.org_billing_start(uuid)') is not null then
    execute 'select public.org_billing_start($1)' into bstart using p_org;                    -- import stage A; absent = no cut-off
  end if;
  select * into lastl from lessons where org_id = p_org and student_id = p_student and rate is not null order by lesson_date desc, start_time desc limit 1;

  for it in select value from jsonb_array_elements(p_items) loop
    i := i + 1; code := null; msg := null; hol := false; closed := false; stt := 'new'; v_rate := null; subj := null; amt := null; d := null; s := null; e := null; mins := null;
    sl := null; ex_id := null; ex_start := null; ex_end := null; ex_tname := null; ex_exact := null;
    begin
      d := (it->>'date')::date; s := (it->>'start')::time; e := (it->>'end')::time;
      if d is null or s is null or e is null then raise exception 'x'; end if;
    exception when others then
      code := 'BAD_ITEM'; msg := 'Each lesson needs a date, a start time and an end time.';
    end;
    if code is null then
      mins := (extract(epoch from (e - s)) / 60)::int;
      if mins < 15 or mins > 480 then code := 'BAD_TIME'; msg := 'A lesson lasts 15 minutes to 8 hours, and ends after it starts.'; end if;
    end if;
    if code is null then                                                                        -- price per hour: typed, else the weekly slot, else the last lesson
      raw := nullif(trim(coalesce(it->>'rate', '')), '');
      if raw is not null then
        begin v_rate := raw::numeric; exception when others then code := 'BAD_RATE'; msg := 'The price per hour must be a number between 0 and 1000.'; end;
      else
        select x.* into sl from recurring_slots x where x.org_id = p_org and x.student_id = p_student and x.active
           and x.weekday = extract(isodow from d)::int - 1 and x.start_time = s limit 1;
        v_rate := coalesce(sl.rate, lastl.rate);
        if v_rate is null then code := 'NO_PRICE'; msg := 'Type the price per hour: this student has no weekly lesson or earlier lesson to take it from.'; end if;
      end if;
      if code is null and (v_rate < 0 or v_rate > 1000) then code := 'BAD_RATE'; msg := 'The price per hour must be a number between 0 and 1000.'; end if;
    end if;
    if code is null then
      subj := nullif(trim(coalesce(it->>'subject', '')), '');
      if subj is null then
        if sl.id is null then select x.* into sl from recurring_slots x where x.org_id = p_org and x.student_id = p_student and x.active
                                 and x.weekday = extract(isodow from d)::int - 1 and x.start_time = s limit 1; end if;
        subj := coalesce(sl.subject, lastl.subject);
      end if;
      if length(coalesce(subj, '')) > 60 then code := 'BAD_ITEM'; msg := 'The subject is too long (60 characters at most).'; end if;
      v_rate := round(v_rate, 2); amt := round(v_rate * mins / 60.0, 2);
    end if;

    if code is null and d >= p_today then
      code := 'NOT_PAST'; msg := 'Only days before today can be added here. Today and later lessons come from "Create lessons".';
    end if;
    if code is null then
      k := d::text || ' ' || s::text;
      if k = any(seen) then stt := 'there'; code := 'DUPLICATE'; msg := 'The same lesson is in the list twice; it is made once.';
      else seen := seen || k; end if;
    end if;
    if code is null then                                                                         -- an existing lesson of this student at an overlapping time
      select l.id, l.start_time, l.end_time, m.display_name, (l.start_time = s and l.taught_by is not distinct from p_tutor)
        into ex_id, ex_start, ex_end, ex_tname, ex_exact
        from lessons l left join memberships m on m.id = l.taught_by and m.org_id = l.org_id
       where l.org_id = p_org and l.student_id = p_student and l.lesson_date = d and not (l.status = 'cancelled' and l.attendance is null)
         and l.start_time < e and l.end_time > s
       order by (l.start_time = s and l.taught_by is not distinct from p_tutor) desc, l.start_time limit 1;
      if ex_id is not null and ex_exact then stt := 'there'; code := 'THERE'; msg := 'Already on the timetable: nothing to add.'; end if;
    end if;
    if code is null then
      if d < p_today - allowed then
        code := 'TOO_OLD'; msg := 'This centre lets staff add lessons up to ' || allowed || ' days back (' || to_char(p_today - allowed, 'DD Mon YYYY') || ' onward).';
      elsif d < created - allowed then
        code := 'BEFORE_STUDENT_START'; msg := 'This is too long before the student was added on ' || to_char(created, 'DD Mon YYYY') || ' (the limit is ' || allowed || ' days before).';
      elsif st.end_date is not null and d > st.end_date then
        code := 'AFTER_END'; msg := 'The student''s lessons ended on ' || to_char(st.end_date, 'DD Mon YYYY') || '.';
      elsif bstart is not null and d < bstart then
        code := 'BEFORE_BILLING_START'; msg := 'Billing for this centre starts from ' || to_char(bstart, 'DD Mon YYYY') || ', so earlier lessons can''t be added.';
      end if;
    end if;
    if code is null then
      closed := exists (select 1 from platform_fee_snapshots f where f.org_id = p_org and f.month > date_trunc('month', d)::date);
      if closed and not p_allow_closed then
        code := 'FEE_MONTH_CLOSED'; msg := 'The fee for ' || to_char(d, 'FMMonth YYYY') || ' is already closed. Only the centre owner can add lessons to it.';
      end if;
    end if;
    if code is null then
      select h.name into hname from holidays h where h.org_id = p_org and h.branch_id is null and d between h.starts_on and h.ends_on order by h.starts_on limit 1;
      hol := found;
      if hol and not coalesce(p_confirm_holidays, false) then
        code := 'HOLIDAY'; msg := 'That day is a centre holiday (' || hname || '). Confirm to add it anyway.';
      end if;
    end if;
    if code is null and ex_id is not null and not coalesce(ex_exact, false) then
      code := 'CLASH'; msg := 'This student already has a lesson then (' || to_char(ex_start, 'HH24:MI') || ' to ' || to_char(ex_end, 'HH24:MI')
                                || case when ex_tname is not null then ' with ' || ex_tname else '' end || ').';
    end if;
    if code is not null and stt = 'new' then stt := 'refused'; end if;
    rows := rows || jsonb_build_object('idx', i, 'date', d, 'start', s, 'end', e, 'minutes', mins, 'rate', v_rate, 'amount', amt,
              'amount_cents', case when amt is null then null else round(amt * 100)::bigint end, 'subject', subj, 'state', stt, 'code', code, 'message', msg,
              'holiday', hol, 'fee_month_closed', closed);
  end loop;
  return jsonb_build_object('allowed_days', allowed, 'rows', rows);
end $$;
revoke all on function public.staff_past_lessons_plan(uuid, uuid, uuid, jsonb, boolean, boolean, date) from public, anon, authenticated;

-- the checks every public function shares: the gate (owner / staff with manage_timetable), the owner-only override, the tutor. Returns the centre's today.
create or replace function public.staff_past_lessons_gate(p_org uuid, p_student uuid, p_tutor uuid, p_allow_closed boolean, p_need_tutor boolean) returns date
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true);
begin
  if not exists (select 1 from students s where s.id = p_student and s.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if coalesce(p_allow_closed, false) and not exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active' and m.role = 'owner') then
    raise exception 'NOT_ALLOWED: only the centre owner can add lessons to a month whose fee is already closed' using errcode = '42501'; end if;
  if p_need_tutor then
    if p_tutor is null then raise exception 'BAD_TUTOR: pick the tutor who taught these lessons' using errcode = 'P0001'; end if;
    if not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org and m.role in ('tutor', 'staff', 'owner') and m.status in ('active', 'invited')) then
      raise exception 'NOT_AVAILABLE: that person can''t be given lessons at this centre' using errcode = 'P0001'; end if;
  end if;
  return today;
end $$;
revoke all on function public.staff_past_lessons_gate(uuid, uuid, uuid, boolean, boolean) from public, anon, authenticated;

-- ---------------------------------------------------------------- 3. what the form needs
create or replace function public.staff_past_lessons_options(p_org uuid, p_student uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, false); can_add boolean := org_can(p_org, 'manage_timetable'); cfg jsonb := org_settings_on(p_org, today);
        allowed int; st students; tz text; created date; bstart date; lastl lessons; slots jsonb; tutors jsonb; deftutor uuid; closed_before date; is_owner boolean;
begin
  select * into st from students where id = p_student and org_id = p_org;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  allowed := coalesce((cfg #>> '{lessons,backfill_allowed_days}')::int, 31);
  select o.timezone into tz from organisations o where o.id = p_org;
  created := (st.created_at at time zone tz)::date;
  if to_regprocedure('public.org_billing_start(uuid)') is not null then execute 'select public.org_billing_start($1)' into bstart using p_org; end if;
  select * into lastl from lessons where org_id = p_org and student_id = p_student and rate is not null order by lesson_date desc, start_time desc limit 1;
  select max(f.month) into closed_before from platform_fee_snapshots f where f.org_id = p_org;
  is_owner := exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active' and m.role = 'owner');
  select coalesce(jsonb_agg(jsonb_build_object('weekday', x.weekday, 'start', x.start_time, 'end', x.end_time, 'subject', x.subject,
                                               'rate', case when can_add then x.rate end, 'tutor_id', x.taught_by) order by x.weekday, x.start_time), '[]'::jsonb) into slots
    from recurring_slots x where x.org_id = p_org and x.student_id = p_student and x.active;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', coalesce(m.display_name, 'Tutor')) order by m.display_name, m.id), '[]'::jsonb) into tutors
    from memberships m where m.org_id = p_org and m.role in ('tutor', 'staff', 'owner') and m.status in ('active', 'invited');
  select coalesce((select x.taught_by from recurring_slots x where x.org_id = p_org and x.student_id = p_student and x.active and x.taught_by is not null order by x.created_at limit 1),
                  (select st2.membership_id from student_tutors st2 where st2.org_id = p_org and st2.student_id = p_student and st2.active order by st2.since limit 1),
                  lastl.taught_by) into deftutor;
  return jsonb_build_object('today', today, 'enabled', allowed >= 1, 'allowed_days', allowed, 'can_add', can_add, 'is_owner', is_owner,
    'earliest', greatest(today - allowed, created - allowed, coalesce(bstart, date '1900-01-01')), 'billing_start', bstart,
    'student', jsonb_build_object('id', st.id, 'name', st.name, 'level', st.level, 'created', created, 'end_date', st.end_date),
    'slots', slots, 'tutors', tutors, 'default_tutor', deftutor,
    'last_rate', case when can_add then lastl.rate end, 'last_subject', lastl.subject, 'fee_closed_before', closed_before,
    'remarks_required', coalesce((cfg #>> '{lessons,remarks,required}')::boolean, false));
end $$;
revoke all on function public.staff_past_lessons_options(uuid, uuid) from public, anon;
grant execute on function public.staff_past_lessons_options(uuid, uuid) to authenticated;

-- ---------------------------------------------------------------- 4. the student's weekly pattern over a past range, as ready-made items
create or replace function public.staff_past_lessons_pattern(p_org uuid, p_student uuid, p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_past_lessons_gate(p_org, p_student, null, false, false); t date;
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 61 then
    raise exception 'BAD_RANGE: pick a range of at most 62 days' using errcode = 'P0001'; end if;
  t := least(p_to, today - 1);
  return coalesce((select jsonb_agg(jsonb_build_object('date', g.d, 'start', x.start_time, 'end', x.end_time, 'subject', x.subject, 'rate', x.rate, 'tutor_id', x.taught_by)
                          order by g.d, x.start_time)
                     from generate_series(p_from, t, interval '1 day') as g(d)
                     join recurring_slots x on x.org_id = p_org and x.student_id = p_student and x.active and x.weekday = extract(isodow from g.d)::int - 1), '[]'::jsonb);
end $$;
revoke all on function public.staff_past_lessons_pattern(uuid, uuid, date, date) from public, anon;
grant execute on function public.staff_past_lessons_pattern(uuid, uuid, date, date) to authenticated;

-- ---------------------------------------------------------------- 5. the preview (writes nothing)
create or replace function public.staff_past_lessons_preview(p_org uuid, p_student uuid, p_tutor uuid, p_items jsonb,
                                                             p_confirm_holidays boolean default false, p_allow_closed_month boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_past_lessons_gate(p_org, p_student, p_tutor, p_allow_closed_month, true); plan jsonb; rows jsonb;
begin
  plan := staff_past_lessons_plan(p_org, p_student, p_tutor, p_items, p_confirm_holidays, p_allow_closed_month, today);
  rows := plan->'rows';
  return jsonb_build_object('today', today, 'allowed_days', plan->'allowed_days', 'rows', rows,
    'new', (select count(*) from jsonb_array_elements(rows) r where r->>'state' = 'new'),
    'there', (select count(*) from jsonb_array_elements(rows) r where r->>'state' = 'there'),
    'refused', (select count(*) from jsonb_array_elements(rows) r where r->>'state' = 'refused'),
    'total_cents', (select coalesce(sum((r->>'amount_cents')::bigint), 0) from jsonb_array_elements(rows) r where r->>'state' = 'new'),
    'fee_month_closed', exists (select 1 from jsonb_array_elements(rows) r where r->>'state' = 'new' and (r->>'fee_month_closed')::boolean));
end $$;
revoke all on function public.staff_past_lessons_preview(uuid, uuid, uuid, jsonb, boolean, boolean) from public, anon;
grant execute on function public.staff_past_lessons_preview(uuid, uuid, uuid, jsonb, boolean, boolean) to authenticated;

-- ---------------------------------------------------------------- 6. add them
-- All or nothing. Answer: created, skipped (already there), lesson_ids, attended (true when marked in the same step), fee_month_closed (the owner passed
-- a closed fee month: say so on screen), invoiced_months (months that already have an issued invoice for this family: the new lessons go on the next one).
create or replace function public.staff_add_past_lessons(p_org uuid, p_student uuid, p_tutor uuid, p_items jsonb, p_reason text,
                                                         p_mark_attended boolean default false, p_remarks text default null,
                                                         p_confirm_holidays boolean default false, p_allow_closed_month boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := staff_past_lessons_gate(p_org, p_student, p_tutor, p_allow_closed_month, true); why text := nullif(trim(coalesce(p_reason, '')), '');
        rem text := nullif(trim(coalesce(p_remarks, '')), ''); cfg jsonb := org_settings_on(p_org, today); plan jsonb; r jsonb; nbad int; owner_uid uuid;
        st students; lid uuid; ids uuid[] := '{}'; n_new int := 0; n_there int := 0; any_closed boolean := false; months date[]; att boolean := coalesce(p_mark_attended, false);
begin
  if why is null then raise exception 'REASON_REQUIRED: say why these lessons are being added now' using errcode = 'P0001'; end if;
  if length(why) > 500 then raise exception 'TOO_LONG: keep the reason under 500 characters' using errcode = 'P0001'; end if;
  if length(coalesce(p_remarks, '')) > 2000 then raise exception 'TOO_LONG: keep the remarks under 2000 characters' using errcode = 'P0001'; end if;
  if att and coalesce((cfg #>> '{lessons,remarks,required}')::boolean, false) and rem is null then
    raise exception 'REMARKS_REQUIRED: this centre needs remarks before a lesson is marked attended' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('staff_add_past_lessons:' || p_org::text, 0));          -- two people at once: one waits, then finds the lessons already there
  plan := staff_past_lessons_plan(p_org, p_student, p_tutor, p_items, p_confirm_holidays, p_allow_closed_month, today);
  select count(*) into nbad from jsonb_array_elements(plan->'rows') r2 where r2->>'state' = 'refused';
  if nbad > 0 then
    raise exception 'REFUSED: % of these lessons can''t be added, so none were. First problem: %', nbad, (select r2->>'message' from jsonb_array_elements(plan->'rows') r2 where r2->>'state' = 'refused' limit 1)
      using errcode = 'P0001'; end if;
  select m.user_id into owner_uid from memberships m where m.org_id = p_org and m.role = 'owner' and m.status = 'active' and m.user_id is not null order by m.created_at limit 1;
  if owner_uid is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into st from students where id = p_student and org_id = p_org;

  for r in select value from jsonb_array_elements(plan->'rows') loop
    if r->>'state' = 'there' then n_there := n_there + 1; continue; end if;
    insert into lessons(tutor_id, org_id, student_id, lesson_date, start_time, end_time, subject, level, rate, split, amount, status, paid, one_off, taught_by)
    values (owner_uid, p_org, p_student, (r->>'date')::date, (r->>'start')::time, (r->>'end')::time, r->>'subject', st.level, (r->>'rate')::numeric, 1,
            (r->>'amount')::numeric, 'scheduled', false, true, p_tutor)
    returning id into lid;
    if att then update lessons set attendance = 'attended', remarks = rem, remarks_at = case when rem is null then null else now() end where id = lid; end if;
    ids := ids || lid; n_new := n_new + 1;
    if (r->>'fee_month_closed')::boolean then any_closed := true; end if;
    insert into audit_log(org_id, actor, action, table_name, row_id, after)
    values (p_org, auth.uid(), 'staff_add_past_lesson', 'lessons', lid::text,
            jsonb_build_object('student', p_student, 'tutor', p_tutor, 'date', r->>'date', 'start', r->>'start', 'end', r->>'end', 'rate', r->'rate', 'amount', r->'amount',
                               'attended', att, 'reason', why, 'holiday_confirmed', (r->>'holiday')::boolean, 'fee_month_closed_override', (r->>'fee_month_closed')::boolean));
  end loop;
  select coalesce(array_agg(distinct ci.period_start), '{}') into months from centre_invoices ci
   where ci.org_id = p_org and ci.kind = 'lesson' and ci.status = 'issued' and (ci.student_id = p_student or (st.household_id is not null and ci.household_id = st.household_id))
     and ci.period_start in (select date_trunc('month', (x->>'date')::date)::date from jsonb_array_elements(plan->'rows') x where x->>'state' = 'new');
  return jsonb_build_object('created', n_new, 'skipped', n_there, 'lesson_ids', to_jsonb(ids), 'attended', att and n_new > 0, 'fee_month_closed', any_closed,
                            'invoiced_months', to_jsonb(months));
end $$;
revoke all on function public.staff_add_past_lessons(uuid, uuid, uuid, jsonb, text, boolean, text, boolean, boolean) from public, anon;
grant execute on function public.staff_add_past_lessons(uuid, uuid, uuid, jsonb, text, boolean, text, boolean, boolean) to authenticated;

-- ####################################### POST-CHECK (read-only; this is the result you see) #######################################
-- Every line should say 'present'; the last line says OVERALL OK.
with want(kind, name) as (values
  ('table','centre_deposit_ledger'),('table','centre_deposits'),('table','centre_refund_events'),('table','centre_refunds'),
  ('table','centre_late_fees'),('table','org_notifications'),
  ('function','staff_reassign_lesson'),('function','centre_record_payment'),('function','centre_deposit_alloc_hook'),('function','centre_deposit_gate'),
  ('function','centre_deposit_guard'),('function','centre_deposit_ledger_get'),('function','centre_deposit_ledger_guard'),('function','centre_deposit_make_invoice'),
  ('function','centre_deposit_note'),('function','centre_deposit_opening_balance'),('function','centre_deposit_run_candidates'),('function','centre_deposit_status'),
